function MovRow({
  mov,
  disabled,
  onSave,
}: {
  mov: any;
  disabled: boolean;
  onSave: (utilizado: number) => void;
}) {
  const [val, setVal] = useState<string>(String(Number(mov.utilizado)));
  useEffect(() => {
    setVal(String(Number(mov.utilizado)));
  }, [mov.utilizado]);
  const final = Number(mov.inv_inicial) + Number(mov.recibido) - (Number(val) || 0);
  const max = Number(mov.inv_inicial) + Number(mov.recibido);
  const overflow = Number(val) > max + 1e-6;
  const insumoNombre = mov.insumo?.nombre ?? "ÔÇö";
  const proveedor = mov.proveedor || "ÔÇö";

  return (
    <TableRow>
      <TableCell className="py-1.5 px-1.5">
        <Tooltip>
          <TooltipTrigger asChild>
            <span className="truncate block cursor-default">{insumoNombre}</span>
          </TooltipTrigger>
          <TooltipContent side="top">{insumoNombre}</TooltipContent>
        </Tooltip>
      </TableCell>
      <TableCell className="py-1.5 px-1 text-center text-muted-foreground">
        <Tooltip>
          <TooltipTrigger asChild>
            <span className="truncate block cursor-default">{proveedor}</span>
          </TooltipTrigger>
          <TooltipContent side="top">{proveedor}</TooltipContent>
        </Tooltip>
      </TableCell>
      <TableCell className="py-1.5 px-1 text-center text-muted-foreground">
        {mov.insumo?.unidad ?? "ÔÇö"}
      </TableCell>
      <TableCell className="py-1.5 px-1 text-center tabular-nums truncate">
        {formatMXN(Number(mov.precio_unitario))}
      </TableCell>
      <TableCell className="py-1.5 px-1 text-center tabular-nums">
        {Number(mov.inv_inicial)}
      </TableCell>
      <TableCell className="py-1.5 px-1 text-center tabular-nums">{Number(mov.recibido)}</TableCell>
      <TableCell className="py-1.5 px-1 text-center">
        <Input
          type="number"
          step="0.01"
          min={0}
          max={max}
          value={val}
          disabled={disabled}
          onChange={(e) => setVal(e.target.value)}
          onBlur={() => {
            const n = Number(val);
            if (isNaN(n) || n < 0) {
              setVal(String(Number(mov.utilizado)));
              return;
            }
            if (n > max + 1e-6) {
              toast.error(
                `El utilizado no puede superar el inventario disponible (${max}) para ${insumoNombre}`,
              );
              setVal(String(Number(mov.utilizado)));
              return;
            }
            if (n === Number(mov.utilizado)) return;
            onSave(n);
          }}
          className={`h-7 w-full max-w-[64px] px-1 text-center mx-auto tabular-nums ${overflow ? "border-rose-500" : ""}`}
        />
      </TableCell>

      <TableCell
        className={`py-1.5 px-1 text-center tabular-nums font-medium ${final < 0 ? "text-rose-600" : ""}`}
      >
        {final}
      </TableCell>
    </TableRow>
  );
}

