source:
"use client";

import { useRef, useState, useEffect } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Download, FileUp, Trash2, Calendar, AlertTriangle, Eye, X } from "lucide-react";
import { supabase } from "@/integrations/supabase/client";
import { useServerFn } from "@/lib/server-fn/client";
import {
  listCompanyDocumentos,
  saveCompanyDocumento,
  deleteCompanyDocumento,
} from "@/lib/api-client/company.functions";
import { useAuthStore } from "@/stores/auth";
import { estadoVencimiento, formatDate, type EstadoDoc } from "@/lib/format";

const BUCKET = "company-docs";

const TIPOS_PREDEFINIDOS = [
  "Acta Constitutiva",
  "Constancia de Situaci├│n Fiscal (CSF)",
  "Opini├│n de Cumplimiento SAT",
  "Poder Notarial",
  "Comprobante de Domicilio Fiscal",
  "Identificaci├│n Representante Legal",
  "Registro IMSS / Patr├│n",
  "Registro INFONAVIT",
  "Contrato de Arrendamiento",
  "P├│liza de Seguro",
  "Otro",
];

const ESTADO_STYLES: Record<EstadoDoc, string> = {
  ok: "bg-emerald-100 text-emerald-800 hover:bg-emerald-100 dark:bg-emerald-950 dark:text-emerald-300",
  por_vencer: "bg-amber-100 text-amber-800 hover:bg-amber-100 dark:bg-amber-950 dark:text-amber-300",
  vencido: "bg-rose-100 text-rose-800 hover:bg-rose-100 dark:bg-rose-950 dark:text-rose-300",
  sin_documento: "bg-muted text-muted-foreground hover:bg-muted",
};

const ESTADO_LABEL: Record<EstadoDoc, string> = {
  ok: "Vigente",
  por_vencer: "Por vencer",
  vencido: "Expirado",
  sin_documento: "Sin fecha",
};

export function DocumentosTab() {
  const qc = useQueryClient();
  const companyId = useAuthStore((s) => s.profile?.company_id);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [tipoSelect, setTipoSelect] = useState<string>("");
  const [tipoCustom, setTipoCustom] = useState<string>("");
  const [vencimiento, setVencimiento] = useState<string>("");
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [uploading, setUploading] = useState(false);

  // Modal para ver documentos ya guardados
  const [viewerDoc, setViewerDoc] = useState<{ titulo: string; url: string; isPdf: boolean } | null>(null);

  // Manejar URL temporal del archivo seleccionado para previsualizaci├│n
  useEffect(() => {
    if (!selectedFile) {
      setPreviewUrl(null);
      return;
    }
    const objectUrl = URL.createObjectURL(selectedFile);
    setPreviewUrl(objectUrl);
    return () => URL.revokeObjectURL(objectUrl);
  }, [selectedFile]);

  const fetchDocs = useServerFn(listCompanyDocumentos);
  const saveDoc = useServerFn(saveCompanyDocumento);
  const deleteDoc = useServerFn(deleteCompanyDocumento);

  const { data: documentos = [], isLoading } = useQuery({
    queryKey: ["company_documentos", companyId],
    queryFn: () => fetchDocs(),
  });

  const saveMutation = useMutation({
    mutationFn: saveDoc,
    onSuccess: () => {
      toast.success("Documento guardado con ├®xito");
      qc.invalidateQueries({ queryKey: ["company_documentos", companyId] });
      qc.invalidateQueries({ queryKey: ["notificaciones"] });
      // Reset form
      setTipoSelect("");
      setTipoCustom("");
      setVencimiento("");
      setSelectedFile(null);
      if (fileInputRef.current) fileInputRef.current.value = "";
    },
    onError: (e: Error) => toast.error(e.message || "Error al registrar documento"),
  });

  const deleteMutation = useMutation({
    mutationFn: deleteDoc,
    onSuccess: () => {
      toast.success("Documento eliminado");
      qc.invalidateQueries({ queryKey: ["company_documentos", companyId] });
    },
    onError: (e: Error) => toast.error(e.message || "Error al eliminar documento"),
  });

  const handleVerDocumento = async (doc: any) => {
    try {
      const { data, error } = await supabase.storage.from(BUCKET).createSignedUrl(doc.url, 300);
      if (error || !data?.signedUrl) {
        toast.error("No se pudo obtener el archivo");
        return;
      }
      const isPdf = doc.nombre_archivo?.toLowerCase().endsWith(".pdf") || doc.url?.toLowerCase().endsWith(".pdf");
      setViewerDoc({ titulo: `${doc.tipo} - ${doc.nombre_archivo}`, url: data.signedUrl, isPdf });
    } catch {
      toast.error("Error al abrir visualizador");
    }
  };

  const handleDescargar = async (url: string) => {
    try {
      const { data, error } = await supabase.storage.from(BUCKET).createSignedUrl(url, 60);
      if (error || !data?.signedUrl) {
        toast.error("No se pudo obtener el archivo de descarga");
        return;
      }
      window.open(data.signedUrl, "_blank");
    } catch {
      toast.error("Error al abrir archivo");
    }
  };

  const handleUploadAndSave = async (e: React.FormEvent) => {
    e.preventDefault();
    const finalTipo = (tipoSelect === "Otro" ? tipoCustom : tipoSelect).trim();
    if (!finalTipo) {
      toast.error("Selecciona o escribe el tipo de documento");
      return;
    }
    if (!selectedFile) {
      toast.error("Selecciona un archivo a subir");
      return;
    }
    if (!companyId) {
      toast.error("No se pudo identificar la empresa actual");
      return;
    }

    setUploading(true);
    try {
      const ext = selectedFile.name.split(".").pop();
      const safeTipo = finalTipo.replace(/[^a-zA-Z0-9_-]/g, "_").toLowerCase();
      const path = `${companyId}/${safeTipo}-${Date.now()}.${ext}`;

      const { error: upErr } = await supabase.storage
        .from(BUCKET)
        .upload(path, selectedFile, { upsert: true });

      if (upErr) throw new Error(upErr.message);

      await saveMutation.mutateAsync({
        data: {
          tipo: finalTipo,
          url: path,
          nombre_archivo: selectedFile.name,
          fecha_vencimiento: vencimiento || null,
        },
      });
    } catch (err: any) {
      toast.error(err.message || "Error al subir archivo");
    } finally {
      setUploading(false);
    }
  };

  return (
    <div className="space-y-8">
      {/* Formulario para agregar / actualizar */}
      <form onSubmit={handleUploadAndSave} className="rounded-lg border bg-card p-5 space-y-4 shadow-sm">
        <h3 className="text-base font-semibold">Subir documento de la empresa</h3>
        <p className="text-sm text-muted-foreground">
          Sube actas, constancias, opiniones del SAT u otros archivos oficiales con control opcional de vigencia.
        </p>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-4 items-end">
          <div className="space-y-1.5">
            <Label htmlFor="tipo-doc">Tipo de documento *</Label>
            <Select value={tipoSelect} onValueChange={setTipoSelect}>
              <SelectTrigger id="tipo-doc">
                <SelectValue placeholder="Selecciona un tipo" />
              </SelectTrigger>
              <SelectContent>
                {TIPOS_PREDEFINIDOS.map((t) => (
                  <SelectItem key={t} value={t}>
                    {t}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
            {tipoSelect === "Otro" && (
              <Input
                className="mt-2"
                placeholder="Escribe el nombre del tipo..."
                value={tipoCustom}
                onChange={(e) => setTipoCustom(e.target.value)}
                required
              />
            )}
          </div>

          <div className="space-y-1.5">
            <Label htmlFor="vigencia-doc" className="flex items-center gap-1.5">
              <Calendar className="h-4 w-4 text-muted-foreground" />
              Fecha de vigencia (opcional)
            </Label>
            <Input
              id="vigencia-doc"
              type="date"
              value={vencimiento}
              onChange={(e) => setVencimiento(e.target.value)}
            />
          </div>

          <div className="space-y-1.5">
            <Label htmlFor="archivo-doc">Archivo (PDF / Imagen) *</Label>
            <Input
              id="archivo-doc"
              ref={fileInputRef}
              type="file"
              accept=".pdf,.png,.jpg,.jpeg,.webp"
              onChange={(e) => setSelectedFile(e.target.files?.[0] || null)}
              required
            />
          </div>
        </div>

        {/* Previsualizador del archivo que se va a subir */}
        {selectedFile && previewUrl && (
          <div className="rounded-md border p-3 bg-muted/30 space-y-2">
            <div className="flex items-center justify-between">
              <span className="text-xs font-medium text-muted-foreground flex items-center gap-1.5">
                <Eye className="h-3.5 w-3.5" />
                Vista previa: {selectedFile.name} ({(selectedFile.size / 1024).toFixed(0)} KB)
              </span>
              <Button
                type="button"
                variant="ghost"
                size="sm"
                className="h-6 px-2 text-xs text-muted-foreground hover:text-foreground"
                onClick={() => {
                  setSelectedFile(null);
                  if (fileInputRef.current) fileInputRef.current.value = "";
                }}
              >
                <X className="h-3.5 w-3.5 mr-1" /> Quitar
              </Button>
            </div>
            {selectedFile.type.includes("pdf") || selectedFile.name.toLowerCase().endsWith(".pdf") ? (
              <iframe
                src={previewUrl}
                title="Vista previa PDF"
                className="w-full h-72 rounded border bg-background"
              />
            ) : (
              <div className="flex justify-center bg-background/50 rounded border p-2">
                <img
                  src={previewUrl}
                  alt="Vista previa"
                  className="max-h-64 max-w-full rounded object-contain shadow-sm"
                />
              </div>
            )}
          </div>
        )}

        <div className="flex justify-end pt-2">
          <Button type="submit" disabled={uploading || saveMutation.isPending}>
            <FileUp className="h-4 w-4 mr-2" />
            {uploading || saveMutation.isPending ? "Subiendo..." : "Guardar documento"}
          </Button>
        </div>
      </form>

      {/* Lista de documentos existentes */}
      <div className="space-y-3">
        <h3 className="text-base font-semibold">Documentos registrados</h3>
        {isLoading ? (
          <p className="text-sm text-muted-foreground">Cargando documentosÔÇª</p>
        ) : documentos.length === 0 ? (
          <div className="text-center py-8 border border-dashed rounded-lg text-muted-foreground text-sm">
            No hay documentos cargados en la empresa.
          </div>
        ) : (
          <div className="rounded-md border overflow-x-auto">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Tipo de Documento</TableHead>
                  <TableHead>Archivo</TableHead>
                  <TableHead>Vigencia</TableHead>
                  <TableHead>Estatus</TableHead>
                  <TableHead className="text-right">Acciones</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {documentos.map((doc: any) => {
                  const est = doc.fecha_vencimiento
                    ? estadoVencimiento(doc.fecha_vencimiento, doc.url)
                    : "sin_documento";

                  return (
                    <TableRow key={doc.id}>
                      <TableCell className="font-medium">{doc.tipo}</TableCell>
                      <TableCell className="text-muted-foreground text-sm max-w-[200px] truncate" title={doc.nombre_archivo}>
                        {doc.nombre_archivo}
                      </TableCell>
                      <TableCell className="text-sm">
                        {doc.fecha_vencimiento ? formatDate(doc.fecha_vencimiento) : "ÔÇö"}
                      </TableCell>
                      <TableCell>
                        <Badge variant="secondary" className={ESTADO_STYLES[est]}>
                          {est === "por_vencer" || est === "vencido" ? (
                            <AlertTriangle className="h-3 w-3 mr-1 inline" />
                          ) : null}
                          {ESTADO_LABEL[est]}
                        </Badge>
                      </TableCell>
                      <TableCell className="text-right space-x-2">
                        <Button
                          variant="ghost"
                          size="icon"
                          title="Visualizar"
                          onClick={() => handleVerDocumento(doc)}
                        >
                          <Eye className="h-4 w-4" />
                        </Button>
                        <Button
                          variant="ghost"
                          size="icon"
                          title="Descargar"
                          onClick={() => handleDescargar(doc.url)}
                        >
                          <Download className="h-4 w-4" />
                        </Button>
                        <Button
                          variant="ghost"
                          size="icon"
                          className="text-destructive hover:text-destructive"
                          title="Eliminar"
                          disabled={deleteMutation.isPending}
                          onClick={() => {
                            if (confirm(`┬┐Eliminar el documento "${doc.tipo}"?`)) {
                              deleteMutation.mutate({ data: { id: doc.id } });
                            }
                          }}
                        >
                          <Trash2 className="h-4 w-4" />
                        </Button>
                      </TableCell>
                    </TableRow>
                  );
                })}
              </TableBody>
            </Table>
          </div>
        )}
      </div>

      {/* Modal para visualizar documento existente */}
      <Dialog open={!!viewerDoc} onOpenChange={(open) => !open && setViewerDoc(null)}>
        <DialogContent className="max-w-4xl max-h-[90vh] flex flex-col p-4">
          <DialogHeader>
            <DialogTitle className="text-base truncate pr-6">{viewerDoc?.titulo}</DialogTitle>
          </DialogHeader>
          <div className="flex-1 w-full min-h-[500px] overflow-hidden rounded border bg-muted/20 flex items-center justify-center">
            {viewerDoc?.isPdf ? (
              <iframe
                src={viewerDoc.url}
                title={viewerDoc.titulo}
                className="w-full h-[65vh] border-0 rounded"
              />
            ) : viewerDoc?.url ? (
              <img
                src={viewerDoc.url}
                alt={viewerDoc.titulo}
                className="max-h-[65vh] max-w-full object-contain rounded"
              />
            ) : null}
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
}

"use client";

import { forwardRef, useEffect, useImperativeHandle, useRef, useState } from "react";
import { useServerFn } from "@/lib/server-fn/client";

import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";
import { getCompanyConfig, updateCompanyFacturacion } from "@/lib/api-client/company.functions";

import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { REGIMENES_MORAL, REGIMENES_FISICA } from "@/components/terceros/constants";
import { ESTADOS_MX } from "@/lib/mx-estados";

type TipoPersona = "moral" | "fisica";

export type FacturacionTabHandle = {
  submit: () => void;
  submitAsync: () => Promise<void>;
  isSaving: boolean;
};

export const FacturacionTab = forwardRef<FacturacionTabHandle>(function FacturacionTab(_, ref) {
  const qc = useQueryClient();

  const fetchCfg = useServerFn(getCompanyConfig);
  const saveFn = useServerFn(updateCompanyFacturacion);
  const formRef = useRef<HTMLFormElement>(null);

  const cfg = useQuery({ queryKey: ["company-config"], queryFn: () => fetchCfg() });

  const [f, setF] = useState({
    tipo_persona: "moral" as TipoPersona,
    razon_social: "",
    nombre_completo: "",
    rfc: "",
    curp: "",
    regimen_fiscal: "",
    calle: "",
    numero_exterior: "",
    numero_interior: "",
    colonia: "",
    municipio: "",
    estado: "",
    codigo_postal: "",
    registro_imss: "",
    registro_infonavit: "",
  });

  useEffect(() => {
    if (!cfg.data) return;
    setF({
      tipo_persona: (cfg.data.tipo_persona as TipoPersona) ?? "moral",
      razon_social: cfg.data.razon_social ?? "",
      nombre_completo: cfg.data.nombre_completo ?? "",
      rfc: cfg.data.rfc ?? "",
      curp: cfg.data.curp ?? "",
      regimen_fiscal: cfg.data.regimen_fiscal ?? "",
      calle: cfg.data.calle ?? "",
      numero_exterior: cfg.data.numero_exterior ?? "",
      numero_interior: cfg.data.numero_interior ?? "",
      colonia: cfg.data.colonia ?? "",
      municipio: cfg.data.municipio ?? "",
      estado: cfg.data.estado ?? "",
      codigo_postal: cfg.data.codigo_postal ?? "",
      registro_imss: cfg.data.registro_imss ?? "",
      registro_infonavit: cfg.data.registro_infonavit ?? "",
    });
  }, [cfg.data]);

  const buildPayload = () => ({
    tipo_persona: f.tipo_persona,
    razon_social: f.razon_social.trim(),
    nombre_completo: f.nombre_completo.trim() || null,
    rfc: f.rfc.trim().toUpperCase(),
    curp: f.tipo_persona === "fisica" ? f.curp.trim() || null : null,
    regimen_fiscal: f.regimen_fiscal || null,
    calle: f.calle.trim() || null,
    numero_exterior: f.numero_exterior.trim() || null,
    numero_interior: f.numero_interior.trim() || null,
    colonia: f.colonia.trim() || null,
    municipio: f.municipio.trim() || null,
    estado: f.estado.trim() || null,
    codigo_postal: f.codigo_postal.trim() || null,
    registro_imss: f.registro_imss.trim() || null,
    registro_infonavit: f.registro_infonavit.trim() || null,
  });

  const save = useMutation({
    mutationFn: saveFn,
    onSuccess: () => {
      toast.success("Datos actualizados");
      qc.invalidateQueries({ queryKey: ["company-config"] });
    },
    onError: (e: Error) => toast.error(e.message),
  });

  const set = <K extends keyof typeof f>(k: K, v: (typeof f)[K]) => setF((p) => ({ ...p, [k]: v }));

  useImperativeHandle(
    ref,
    () => ({
      submit: () => formRef.current?.requestSubmit(),
      submitAsync: async () => {
        await save.mutateAsync({ data: buildPayload() });
      },
      isSaving: save.isPending,
    }),
    [save, f],
  );

  if (cfg.isLoading) return <p className="text-sm text-muted-foreground">CargandoÔÇª</p>;

  const regimenes = f.tipo_persona === "moral" ? REGIMENES_MORAL : REGIMENES_FISICA;
  const regimenOptions =
    f.regimen_fiscal && !regimenes.includes(f.regimen_fiscal)
      ? [f.regimen_fiscal, ...regimenes]
      : regimenes;

  return (
    <form
      ref={formRef}
      className="space-y-5"
      onSubmit={(e) => {
        e.preventDefault();
        save.mutate({ data: buildPayload() });
      }}
    >
      <div>
        <Label>Tipo de persona</Label>
        <RadioGroup
          value={f.tipo_persona}
          onValueChange={(v) =>
            setF((p) => ({ ...p, tipo_persona: v as TipoPersona, regimen_fiscal: "" }))
          }
          className="mt-2 flex flex-wrap gap-x-6 gap-y-2"
        >
          <label className="flex items-center gap-2 text-sm">
            <RadioGroupItem value="moral" /> Persona moral
          </label>
          <label className="flex items-center gap-2 text-sm">
            <RadioGroupItem value="fisica" /> Persona f├¡sica
          </label>
        </RadioGroup>
      </div>

      <div className="grid sm:grid-cols-2 gap-4">
        <div>
          <Label>{f.tipo_persona === "moral" ? "Raz├│n social *" : "Nombre completo *"}</Label>
          <Input
            value={f.razon_social}
            onChange={(e) => set("razon_social", e.target.value)}
            required
          />
        </div>
        {f.tipo_persona === "moral" && (
          <div>
            <Label>Nombre comercial</Label>
            <Input
              value={f.nombre_completo}
              onChange={(e) => set("nombre_completo", e.target.value)}
            />
          </div>
        )}
        <div>
          <Label>RFC *</Label>
          <Input
            value={f.rfc}
            onChange={(e) => set("rfc", e.target.value.toUpperCase())}
            maxLength={13}
            required
          />
        </div>
        {f.tipo_persona === "fisica" && (
          <div>
            <Label>CURP</Label>
            <Input
              value={f.curp}
              onChange={(e) => set("curp", e.target.value.toUpperCase())}
              maxLength={18}
            />
          </div>
        )}
        <div className="min-w-0 sm:col-span-2">
          <Label>R├®gimen fiscal</Label>
          <Select value={f.regimen_fiscal} onValueChange={(v) => set("regimen_fiscal", v)}>
            <SelectTrigger>
              <SelectValue placeholder="Selecciona r├®gimen" />
            </SelectTrigger>
            <SelectContent>
              {regimenOptions.map((r) => (
                <SelectItem key={r} value={r}>
                  {r}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
      </div>

      <div className="space-y-3 border-t pt-4">
        <h3 className="text-sm font-medium">Direcci├│n fiscal</h3>
        <div className="grid sm:grid-cols-4 gap-4">
          <div className="sm:col-span-2">
            <Label>Calle</Label>
            <Input value={f.calle} onChange={(e) => set("calle", e.target.value)} />
          </div>
          <div>
            <Label>N├║m. exterior</Label>
            <Input
              value={f.numero_exterior}
              onChange={(e) => set("numero_exterior", e.target.value)}
            />
          </div>
          <div>
            <Label>N├║m. interior</Label>
            <Input
              value={f.numero_interior}
              onChange={(e) => set("numero_interior", e.target.value)}
            />
          </div>
        </div>
        <div className="grid sm:grid-cols-3 gap-4">
          <div>
            <Label>Colonia</Label>
            <Input value={f.colonia} onChange={(e) => set("colonia", e.target.value)} />
          </div>
          <div>
            <Label>Municipio / Alcald├¡a</Label>
            <Input value={f.municipio} onChange={(e) => set("municipio", e.target.value)} />
          </div>
          <div>
            <Label>Estado</Label>
            <Select value={f.estado} onValueChange={(v) => set("estado", v)}>
              <SelectTrigger>
                <SelectValue placeholder="Selecciona estado" />
              </SelectTrigger>
              <SelectContent>
                {ESTADOS_MX.map((e) => (
                  <SelectItem key={e} value={e}>
                    {e}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
          <div>
            <Label>C├│digo postal</Label>
            <Input
              value={f.codigo_postal}
              onChange={(e) => set("codigo_postal", e.target.value)}
              maxLength={5}
            />
          </div>
        </div>
      </div>

      <div className="space-y-3 border-t pt-4">
        <h3 className="text-sm font-medium">Registros patronales</h3>
        <div className="grid sm:grid-cols-2 gap-4">
          <div>
            <Label>Registro IMSS</Label>
            <Input value={f.registro_imss} onChange={(e) => set("registro_imss", e.target.value)} />
          </div>
          <div>
            <Label>Registro INFONAVIT</Label>
            <Input
              value={f.registro_infonavit}
              onChange={(e) => set("registro_infonavit", e.target.value)}
            />
          </div>
        </div>
      </div>
    </form>
  );
});

"use client";

import { useMemo, useRef, useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { useServerFn } from "@/lib/server-fn/client";
import { Link } from "@/lib/navigation";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { AlertTriangle, ChevronRight, ExternalLink, Info } from "lucide-react";
import { formatMXN } from "@/lib/format";
import { getBalanceGeneral, getDetalleCuenta } from "@/lib/api-client/balance.functions";
import { GRUPO_LABELS, SUBGRUPO_LABELS, type GrupoContable } from "@/lib/contabilidad/catalogo";
import { gsap, MOTION, MOTION_OK, useGSAP } from "@/lib/anim/gsap";

type Saldo = {
  codigo: string;
  nombre: string;
  grupo: GrupoContable;
  subgrupo: string;
  descripcion: string;
  disponible: boolean;
  saldo: number;
  linkModulo?: string;
};

const EXPANDIBLES = new Set([
  "1100",
  "1110",
  "1120",
  "1210",
  "2100",
  "2110",
  "2120",
  "2130",
  "2150",
  "2160",
  "3100",
]);

export function ContabilidadModule() {
  const fetchBalance = useServerFn(getBalanceGeneral);
  const q = useQuery({
    queryKey: ["balance-general"],
    queryFn: () => fetchBalance(),
    staleTime: 30_000,
  });

  return (
    <div className="space-y-6">
      <header className="flex items-start justify-between gap-4 flex-wrap">
        <div>
          <h1 className="text-2xl font-semibold tracking-tight">Contabilidad</h1>
          <p className="text-sm text-muted-foreground mt-1">
            Balance General gerencial. Los saldos se derivan en vivo de las operaciones registradas.
          </p>
        </div>
        {q.data && (
          <p className="text-xs text-muted-foreground">
            Generado: {new Date(q.data.generadoEn).toLocaleString("es-MX")}
          </p>
        )}
      </header>

      {q.isLoading && <BalanceSkeleton />}
      {q.error && (
        <Alert variant="destructive">
          <AlertTriangle className="size-4" />
          <AlertTitle>No se pudo calcular el balance</AlertTitle>
          <AlertDescription>{(q.error as Error).message}</AlertDescription>
        </Alert>
      )}
      {q.data && <BalanceView data={q.data} />}
    </div>
  );
}

function BalanceView({ data }: { data: Awaited<ReturnType<typeof getBalanceGeneral>> }) {
  const grouped = useMemo(() => {
    const acc: Record<GrupoContable, Saldo[]> = { activo: [], pasivo: [], capital: [] };
    for (const s of data.saldos as Saldo[]) acc[s.grupo].push(s);
    return acc;
  }, [data.saldos]);

  const cuadre = data.totales.activo - (data.totales.pasivo + data.totales.capital);
  const cuadrado = Math.abs(cuadre) < 0.01;

  // Relevo esqueleto ÔåÆ balance: los tres bloques entran cuando llegan los
  // saldos. `gsap.from` deja el contenido visible si GSAP no llega a correr.
  const raiz = useRef<HTMLDivElement>(null);
  useGSAP(
    () => {
      const mm = gsap.matchMedia();
      mm.add(MOTION_OK, () => {
        gsap.from("[data-panel]", {
          autoAlpha: 0,
          y: 4,
          duration: MOTION.entrada,
          ease: "power2.out",
          stagger: 0.04,
        });
      });
      return () => mm.revert();
    },
    { scope: raiz },
  );

  return (
    <div ref={raiz} className="space-y-6">
      <div data-panel className="grid gap-4 md:grid-cols-3">
        <GrupoCard
          titulo="Activo"
          tono="success"
          total={data.totales.activo}
          saldos={grouped.activo}
        />
        <GrupoCard
          titulo="Pasivo"
          tono="warning"
          total={data.totales.pasivo}
          saldos={grouped.pasivo}
        />
        <GrupoCard
          titulo="Capital"
          tono="info"
          total={data.totales.capital}
          saldos={grouped.capital}
        />
      </div>

      <Card data-panel>
        <CardHeader>
          <CardTitle className="text-base">Comprobaci├│n de cuadre</CardTitle>
        </CardHeader>
        <CardContent className="space-y-2 text-sm">
          <div className="flex justify-between">
            <span className="text-muted-foreground">Activo</span>
            <span className="font-mono">{formatMXN(data.totales.activo)}</span>
          </div>
          <div className="flex justify-between">
            <span className="text-muted-foreground">Pasivo + Capital</span>
            <span className="font-mono">
              {formatMXN(data.totales.pasivo + data.totales.capital)}
            </span>
          </div>
          <div className="flex justify-between border-t pt-2">
            <span className="font-medium">Diferencia</span>
            <span
              className={`font-mono font-medium ${cuadrado ? "text-emerald-600" : "text-amber-600"}`}
            >
              {formatMXN(cuadre)}
            </span>
          </div>
          {!cuadrado && (
            <p className="text-xs text-muted-foreground mt-2">
              El cuadre se ajusta autom├íticamente con el <em>Resultado del ejercicio</em>. Esta
              diferencia residual indica anticipos, obras en proceso o almac├®n a├║n no modelados en
              el balance.
            </p>
          )}
        </CardContent>
      </Card>

      <Alert data-panel>
        <Info className="size-4" />
        <AlertTitle>Categor├¡as en fase futura</AlertTitle>
        <AlertDescription>
          Algunas categor├¡as aparecen como <Badge variant="secondary">Pendiente</Badge> porque
          requieren modelar facturaci├│n a cliente, almac├®n valorizado o anticipos a
          proveedores/subcontratistas. Se ir├ín habilitando en pr├│ximas fases.
        </AlertDescription>
      </Alert>
    </div>
  );
}

function GrupoCard({
  titulo,
  tono,
  total,
  saldos,
}: {
  titulo: string;
  tono: "success" | "warning" | "info";
  total: number;
  saldos: Saldo[];
}) {
  const accent =
    tono === "success"
      ? "text-emerald-600"
      : tono === "warning"
        ? "text-amber-600"
        : "text-sky-600";

  const porSubgrupo = saldos.reduce<Record<string, Saldo[]>>((acc, s) => {
    (acc[s.subgrupo] ||= []).push(s);
    return acc;
  }, {});

  return (
    <Card className="min-w-0">
      <CardHeader className="pb-3">
        <div className="flex items-baseline justify-between gap-2">
          <CardTitle className="min-w-0 truncate text-base">{titulo}</CardTitle>
          <span className={`shrink-0 text-lg font-semibold font-mono ${accent}`}>
            {formatMXN(total)}
          </span>
        </div>
      </CardHeader>
      <CardContent className="space-y-4 text-sm">
        {Object.entries(porSubgrupo).map(([sg, items]) => (
          <div key={sg} className="space-y-0.5">
            <p className="text-xs uppercase tracking-wide text-muted-foreground mb-1">
              {SUBGRUPO_LABELS[sg as keyof typeof SUBGRUPO_LABELS] ?? sg}
            </p>
            {items.map((s) => (
              <SaldoRow key={s.codigo} s={s} />
            ))}
          </div>
        ))}
      </CardContent>
    </Card>
  );
}

function SaldoRow({ s }: { s: Saldo }) {
  const [open, setOpen] = useState(false);
  const expandable = s.disponible && EXPANDIBLES.has(s.codigo);

  const fetchDetalle = useServerFn(getDetalleCuenta);
  const detalleQ = useQuery({
    queryKey: ["balance-detalle", s.codigo],
    queryFn: () => fetchDetalle({ data: { codigo: s.codigo } }),
    enabled: expandable && open,
    staleTime: 30_000,
  });

  const header = (
    <div className="flex w-full min-w-0 items-center justify-between gap-2 py-1 px-1 -mx-1 rounded hover:bg-muted/50">
      <div className="flex min-w-0 flex-1 items-center gap-2">
        {expandable ? (
          <ChevronRight
            className={`size-3.5 text-muted-foreground transition-transform shrink-0 ${
              open ? "rotate-90" : ""
            }`}
          />
        ) : (
          <span className="w-3.5 shrink-0" />
        )}
        <span className="text-xs text-muted-foreground tabular-nums">{s.codigo}</span>
        <span
          className={`truncate ${!s.disponible ? "text-muted-foreground" : ""}`}
          title={s.descripcion}
        >
          {s.nombre}
        </span>
        {!s.disponible && (
          <Badge variant="secondary" className="text-xs h-4">
            Pendiente
          </Badge>
        )}
        {s.linkModulo && s.disponible && (
          <Link
            to={s.linkModulo}
            onClick={(e) => e.stopPropagation()}
            className="text-muted-foreground hover:text-foreground"
            title="Ir al m├│dulo"
          >
            <ExternalLink className="size-3" />
          </Link>
        )}
      </div>
      <span
        className={`shrink-0 font-mono tabular-nums ${!s.disponible ? "text-muted-foreground" : ""}`}
      >
        {formatMXN(s.saldo)}
      </span>
    </div>
  );

  if (!expandable) {
    return <div>{header}</div>;
  }

  return (
    <div>
      <button
        type="button"
        onClick={() => setOpen((v) => !v)}
        className="w-full text-left"
        aria-expanded={open}
      >
        {header}
      </button>
      {open && (
        <div className="ml-6 mt-1 mb-2 space-y-1 border-l border-border pl-3">
          {detalleQ.isLoading && (
            <>
              <Skeleton className="h-4 w-full" />
              <Skeleton className="h-4 w-2/3" />
            </>
          )}
          {detalleQ.error && (
            <p className="text-xs text-destructive">No se pudo cargar el desglose.</p>
          )}
          {detalleQ.data && detalleQ.data.items.length === 0 && (
            <p className="text-xs text-muted-foreground py-1">Sin movimientos abiertos.</p>
          )}
          {detalleQ.data?.items.map((item) => (
            <div key={item.id} className="flex items-start justify-between gap-2 text-xs py-0.5">
              <div className="min-w-0">
                <p className="truncate">{item.etiqueta}</p>
                {item.referencia && (
                  <p className="text-[11px] text-muted-foreground truncate">{item.referencia}</p>
                )}
              </div>
              <span className="font-mono tabular-nums shrink-0">{formatMXN(item.saldo)}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

function BalanceSkeleton() {
  return (
    <div className="grid gap-4 md:grid-cols-3">
      {[0, 1, 2].map((i) => (
        <Card key={i}>
          <CardHeader>
            <Skeleton className="h-5 w-24" />
          </CardHeader>
          <CardContent className="space-y-2">
            {[0, 1, 2, 3].map((j) => (
              <Skeleton key={j} className="h-4 w-full" />
            ))}
          </CardContent>
        </Card>
      ))}
    </div>
  );
}

