"use client";

import { useEffect, useState } from "react";

import { useSearch, useNavigate } from "@/lib/navigation";
import { useServerFn } from "@/lib/server-fn/client";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { listDestajos, eliminarDestajo } from "@/lib/api-client/destajos.functions";
import { useEffectiveIsDirector } from "@/stores/auth";
import { useObraRole } from "@/hooks/useObraRole";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { Plus, Eye, Trash2, Users, FileText } from "lucide-react";
import { toast } from "sonner";
import { formatMXN } from "@/lib/format";
import { NuevoDestajoDialog } from "./NuevoDestajoDialog";
import { DestajoDetalleSheet } from "./DestajoDetalleSheet";

type Destajo = {
  id: string;
  obra_id: string;
  destajista_id: string;
  destajista_nombre: string;
  numero: number;
  nombre: string;
  descripcion: string | null;
  estatus: "borrador" | "enviado" | "autorizado" | "rechazado";
  estatus_base: "borrador" | "enviado" | "autorizado" | "rechazado";
  monto_total: number;
  pagado_acumulado: number;
  created_at: string;
};

const ESTATUS_LABEL: Record<Destajo["estatus"], string> = {
  borrador: "Borrador",
  enviado: "Por autorizar",
  autorizado: "Autorizado",
  rechazado: "Rechazado",
};
const ESTATUS_VARIANT: Record<
  Destajo["estatus"],
  "default" | "secondary" | "destructive" | "outline"
> = {
  borrador: "secondary",
  enviado: "outline",
  autorizado: "default",
  rechazado: "destructive",
};

export function DestajosModule({ obraId }: { obraId: string }) {
  const director = useEffectiveIsDirector();
  const { isSupervisor, isResidente } = useObraRole(obraId);
  const canEditDraft = director || isResidente;
  const qc = useQueryClient();
  const fetchList = useServerFn(listDestajos);
  const listQ = useQuery({
    queryKey: ["destajos", obraId],
    queryFn: () => fetchList({ data: { obraId } }),
  });

  const [creating, setCreating] = useState(false);
  const [viewingId, setViewingId] = useState<string | null>(null);
  const [toDelete, setToDelete] = useState<Destajo | null>(null);

  const search = useSearch({ strict: false }) as { destajo?: string };
  const navigate = useNavigate();

  // Abrir autom├íticamente el destajo indicado en ?destajo=<id> (notificaci├│n).
  useEffect(() => {
    if (search.destajo) {
      setViewingId(search.destajo);
      navigate({
        to: ".",
        search: (prev: any) => ({ ...prev, destajo: undefined }),
        replace: true,
      } as any);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [search.destajo]);

  const remove = useServerFn(eliminarDestajo);
  const removeM = useMutation({
    mutationFn: remove,
    onSuccess: () => {
      toast.success("Destajo eliminado");
      qc.invalidateQueries({ queryKey: ["destajos", obraId] });
      setToDelete(null);
    },
    onError: (e: Error) => toast.error(e.message),
  });

  const destajos = (listQ.data ?? []) as Destajo[];
  const contratado = destajos
    .filter((d) => d.estatus_base === "autorizado")
    .reduce((s, d) => s + Number(d.monto_total), 0);
  const pagado = destajos.reduce((s, d) => s + Number(d.pagado_acumulado), 0);
  const activos = destajos.filter((d) => d.estatus_base === "autorizado").length;

  return (
    <div className="space-y-4">
      <header className="flex items-center justify-between gap-4 flex-wrap">
        <h1 className="text-xl font-semibold tracking-tight">Destajos</h1>
        {canEditDraft && (
          <Button size="sm" onClick={() => setCreating(true)}>
            <Plus className="size-4 mr-1" /> Nuevo destajo
          </Button>
        )}
      </header>

      <Card className="flex divide-x divide-border">
        <div className="flex-1 p-3">
          <p className="text-[11px] uppercase tracking-wider text-muted-foreground">
            Contratado vigente
          </p>
          <p className="mt-0.5 text-base font-semibold tabular-nums">{formatMXN(contratado)}</p>
        </div>
        <div className="flex-1 p-3">
          <p className="text-[11px] uppercase tracking-wider text-muted-foreground">
            Pagado acumulado
          </p>
          <p className="mt-0.5 text-base font-semibold tabular-nums">{formatMXN(pagado)}</p>
        </div>
        <div className="flex-1 p-3 bg-primary/5">
          <p className="text-[11px] uppercase tracking-wider text-muted-foreground">
            Destajos activos
          </p>
          <p className="mt-0.5 text-base font-semibold tabular-nums">{activos}</p>
        </div>
      </Card>

      {listQ.isLoading ? (
        <p className="text-sm text-muted-foreground">CargandoÔÇª</p>
      ) : destajos.length === 0 ? (
        <Card className="border-dashed p-8 text-center text-sm text-muted-foreground">
          A├║n no hay destajos. Crea uno para comenzar.
        </Card>
      ) : (
        <Card className="overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full min-w-[720px] text-sm table-fixed">
              <thead className="bg-muted/50 text-[11px] uppercase tracking-wider text-muted-foreground">
                <tr>
                  <th className="text-left py-1.5 px-2 w-10">#</th>
                  <th className="text-left py-1.5 px-2">Destajo</th>
                  <th className="text-left py-1.5 px-2 w-32">Destajista</th>
                  <th className="text-left py-1.5 px-2 w-28">Estatus</th>
                  <th className="text-right py-1.5 px-2 w-28">Contratado</th>
                  <th className="text-right py-1.5 px-2 w-28">Pagado</th>
                  <th className="text-right py-1.5 px-2 w-20">Acc.</th>
                </tr>
              </thead>
              <tbody>
                {destajos.map((d) => {
                  const pct = d.monto_total > 0 ? (d.pagado_acumulado / d.monto_total) * 100 : 0;
                  return (
                    <tr key={d.id} className="border-t border-border">
                      <td className="py-1.5 px-2 tabular-nums">{d.numero}</td>
                      <td className="py-1.5 px-2">
                        <p className="font-medium truncate" title={d.descripcion ?? undefined}>
                          {d.nombre}
                        </p>
                      </td>
                      <td className="py-1.5 px-2 truncate">{d.destajista_nombre}</td>
                      <td className="py-1.5 px-2">
                        <Badge
                          variant={ESTATUS_VARIANT[d.estatus_base]}
                          className="whitespace-nowrap text-xs py-0 px-1.5 h-5"
                        >
                          {ESTATUS_LABEL[d.estatus_base]}
                        </Badge>
                      </td>
                      <td className="py-1.5 px-2 text-right tabular-nums">
                        {formatMXN(d.monto_total)}
                      </td>
                      <td className="py-1.5 px-2 text-right tabular-nums">
                        {formatMXN(d.pagado_acumulado)}
                        {d.monto_total > 0 && (
                          <span className="text-xs text-muted-foreground ml-1">
                            {pct.toFixed(0)}%
                          </span>
                        )}
                      </td>
                      <td className="py-1.5 px-2 text-right">
                        <div className="flex gap-1 justify-end">
                          <Button
                            size="icon"
                            variant="outline"
                            className="h-8 w-8"
                            aria-label="Ver destajo"
                            onClick={() => setViewingId(d.id)}
                          >
                            <Eye className="size-3.5" />
                          </Button>
                          {director &&
                            d.estatus_base === "borrador" &&
                            d.pagado_acumulado === 0 && (
                              <Button
                                size="icon"
                                variant="ghost"
                                className="h-8 w-8 text-destructive"
                                aria-label="Eliminar destajo"
                                onClick={() => setToDelete(d)}
                              >
                                <Trash2 className="size-3.5" />
                              </Button>
                            )}
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </Card>
      )}

      {creating && (
        <NuevoDestajoDialog
          obraId={obraId}
          onClose={() => setCreating(false)}
          onCreated={(id) => {
            setCreating(false);
            qc.invalidateQueries({ queryKey: ["destajos", obraId] });
            setViewingId(id);
          }}
        />
      )}

      {viewingId && (
        <DestajoDetalleSheet
          destajoId={viewingId}
          canAuthorize={director || isSupervisor}
          canEditDraft={canEditDraft}
          onClose={() => setViewingId(null)}
          onChanged={() => qc.invalidateQueries({ queryKey: ["destajos", obraId] })}
        />
      )}

      <AlertDialog open={!!toDelete} onOpenChange={(o) => !o && setToDelete(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>┬┐Eliminar destajo?</AlertDialogTitle>
            <AlertDialogDescription>
              Se eliminar├í "{toDelete?.nombre}" junto con todos sus presupuestos y asignaciones. No
              se puede deshacer.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancelar</AlertDialogCancel>
            <AlertDialogAction
              onClick={() => toDelete && removeM.mutate({ data: { id: toDelete.id } })}
            >
              Eliminar
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

"use client";

import { useState, useMemo } from "react";
import { useServerFn } from "@/lib/server-fn/client";
import { useQuery } from "@tanstack/react-query";
import dynamic from "next/dynamic";
import {
  getEstadoResultadosSemana,
  getEstadoResultadosHistorico,
  getEstadoResultadosAcumulado,
  getObraSemanaBoundaries,
  type CostoCategoria,
  type DocumentoCosto,
  type ConceptoDetalle,
} from "@/lib/api-client/estado-resultados.functions";
import {
  calcularSemana,
  formatRangoSemana,
  numeroSemanaObra,
  rangoSemanaObra,
  toISODate,
} from "@/lib/estimacion-utils";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group";
import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from "@/components/ui/accordion";
import { ChevronLeft, ChevronRight, TrendingDown, TrendingUp } from "lucide-react";
import { formatMXN } from "@/lib/format";

/**
 * La gr├ífica carga despu├®s de la ruta: `recharts` pesa m├ís que el resto del
 * m├│dulo y la tabla de semanas se lee sin ella.
 */
const HistorialChart = dynamic(
  () => import("@/components/estado-resultados/HistorialChart").then((m) => m.HistorialChart),
  { ssr: false, loading: () => <div className="h-[220px]" aria-hidden /> },
);

const CATEGORIA_LABELS: Record<CostoCategoria, string> = {
  almacen: "Almac├®n (consumido)",
  nomina: "N├│mina",
  destajos: "Destajos",
  subcontratos: "Subcontratos",
  rentas: "Rentas",
  gasolinas: "Gasolinas",
  cajaChica: "Caja chica",
};

const CATEGORIAS: CostoCategoria[] = [
  "almacen",
  "nomina",
  "destajos",
  "subcontratos",
  "rentas",
  "gasolinas",
  "cajaChica",
];

function shiftSemana(inicio: string, dias: number): string {
  const d = new Date(inicio + "T12:00:00");
  d.setDate(d.getDate() + dias);
  return toISODate(d);
}

export function EstadoResultadosModule({ obraId }: { obraId: string }) {
  const semanaActual = useMemo(() => calcularSemana(new Date()), []);
  const [modo, setModo] = useState<"semana" | "global">(() => {
    if (typeof window !== "undefined" && window.location.hash === "#global") return "global";
    return "semana";
  });
  const [semanaInicio, setSemanaInicio] = useState<string>(semanaActual.inicio);

  const fetchSemana = useServerFn(getEstadoResultadosSemana);
  const fetchHistorico = useServerFn(getEstadoResultadosHistorico);
  const fetchAcumulado = useServerFn(getEstadoResultadosAcumulado);
  const fetchBoundaries = useServerFn(getObraSemanaBoundaries);

  const boundariesQ = useQuery({
    queryKey: ["obra-semana-boundaries", obraId],
    queryFn: () => fetchBoundaries({ data: { obraId } }),
  });

  const semanaQ = useQuery({
    queryKey: ["estado-resultados", obraId, semanaInicio],
    queryFn: () => fetchSemana({ data: { obraId, semanaInicio } }),
    enabled: modo === "semana",
  });

  const acumQ = useQuery({
    queryKey: ["estado-resultados-acum", obraId],
    queryFn: () => fetchAcumulado({ data: { obraId } }),
    enabled: modo === "global",
  });

  const histQ = useQuery({
    queryKey: ["estado-resultados-hist", obraId],
    queryFn: () => fetchHistorico({ data: { obraId, semanas: 8 } }),
  });

  const activeQ = modo === "semana" ? semanaQ : acumQ;
  const semana = activeQ.data;
  const fechaInicio = boundariesQ.data?.fechaInicio;
  const primerSemana = boundariesQ.data?.primerSemana;
  const numActual = fechaInicio ? numeroSemanaObra(fechaInicio, semanaActual.inicio) : 0;
  const numSeleccion = fechaInicio ? numeroSemanaObra(fechaInicio, semanaInicio) : 0;
  const rango =
    modo === "semana"
      ? fechaInicio
        ? `Semana ${numSeleccion} ┬À ${rangoSemanaObra(fechaInicio, semanaInicio)}`
        : formatRangoSemana(semanaInicio, shiftSemana(semanaInicio, 6))
      : fechaInicio
        ? `Acumulado ┬À Semanas 1ÔÇô${numActual} hasta hoy`
        : "Acumulado de la obra";

  const puedeAnterior = modo === "semana" && (!primerSemana || semanaInicio > primerSemana);
  const puedeSiguiente = modo === "semana" && semanaInicio < semanaActual.inicio;

  const acumulado = useMemo(() => {
    if (modo !== "semana" || !histQ.data) return null;
    const hasta = histQ.data.filter((s) => s.semana_inicio <= semanaInicio);
    return hasta.reduce(
      (acc, s) => ({
        produccion: acc.produccion + s.produccion,
        costos: acc.costos + s.costos_total,
        resultado: acc.resultado + s.resultado,
      }),
      { produccion: 0, costos: 0, resultado: 0 },
    );
  }, [histQ.data, semanaInicio, modo]);

  return (
    <div className="space-y-6">
      <header className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
        <div>
          <h1 className="text-2xl font-semibold tracking-tight">Estado de resultados</h1>
          <p className="text-sm text-muted-foreground">
            Producci├│n contra costos ┬À{" "}
            {modo === "semana"
              ? fechaInicio
                ? `Semana ${numSeleccion} de la obra`
                : "semana seleccionada"
              : "acumulado de la obra"}
          </p>
        </div>
        <div className="flex items-center gap-3 flex-wrap">
          <ToggleGroup
            type="single"
            value={modo}
            onValueChange={(v) => v && setModo(v as "semana" | "global")}
            variant="outline"
            size="sm"
          >
            <ToggleGroupItem value="semana">Semana</ToggleGroupItem>
            <ToggleGroupItem value="global">Global</ToggleGroupItem>
          </ToggleGroup>

          {modo === "semana" ? (
            <div className="flex items-center gap-2">
              <Button
                variant="outline"
                size="icon"
                onClick={() => setSemanaInicio(shiftSemana(semanaInicio, -7))}
                disabled={!puedeAnterior}
                aria-label="Semana anterior"
              >
                <ChevronLeft className="size-4" />
              </Button>
              <div className="min-w-0 flex-1 px-1 text-center text-xs font-medium leading-tight sm:min-w-[260px] sm:flex-none sm:px-3 sm:text-sm">
                {rango}
              </div>
              <Button
                variant="outline"
                size="icon"
                onClick={() => setSemanaInicio(shiftSemana(semanaInicio, 7))}
                disabled={!puedeSiguiente}
                aria-label="Semana siguiente"
              >
                <ChevronRight className="size-4" />
              </Button>
            </div>
          ) : (
            <div className="text-sm text-muted-foreground">{rango}</div>
          )}
        </div>
      </header>

      {activeQ.isLoading ? (
        <p className="text-sm text-muted-foreground">CargandoÔÇª</p>
      ) : !semana ? (
        <p className="text-sm text-destructive">No se pudo cargar el estado de resultados.</p>
      ) : (
        <>
          {/* Tarjetas resumen */}
          <div className="grid gap-4 sm:grid-cols-3">
            <Card className="p-4">
              <p className="text-xs uppercase tracking-wider text-muted-foreground">
                Producci├│n ejercida
              </p>
              <p className="mt-2 text-2xl font-semibold text-emerald-700 dark:text-emerald-400">
                {formatMXN(semana.produccion)}
              </p>
              <p className="text-xs text-muted-foreground mt-1">
                {semana.produccion_detalle.length} estimaci├│n(es)
              </p>
            </Card>

            <Card className="p-4">
              <p className="text-xs uppercase tracking-wider text-muted-foreground">
                Costos totales
              </p>
              <p className="mt-2 text-2xl font-semibold text-rose-700 dark:text-rose-400">
                {formatMXN(semana.costos_total)}
              </p>
              <p className="text-xs text-muted-foreground mt-1">
                {semana.produccion > 0
                  ? `${((semana.costos_total / semana.produccion) * 100).toFixed(1)}% de producci├│n`
                  : "ÔÇö"}
              </p>
            </Card>

            <Card className="p-4">
              <div className="flex items-start justify-between gap-2">
                <p className="text-xs uppercase tracking-wider text-muted-foreground">Resultado</p>
                <Badge
                  className={
                    semana.resultado >= 0
                      ? "border-0 bg-emerald-100 text-emerald-800"
                      : "border-0 bg-rose-100 text-rose-800"
                  }
                >
                  {semana.resultado >= 0 ? "Utilidad" : "P├®rdida"}
                </Badge>
              </div>
              <p
                className={`mt-2 text-2xl font-semibold flex items-center gap-2 ${
                  semana.resultado >= 0
                    ? "text-emerald-700 dark:text-emerald-400"
                    : "text-rose-700 dark:text-rose-400"
                }`}
              >
                {semana.resultado >= 0 ? (
                  <TrendingUp className="size-5" />
                ) : (
                  <TrendingDown className="size-5" />
                )}
                {formatMXN(semana.resultado)}
              </p>
              <p className="text-xs text-muted-foreground mt-1">
                Margen {(semana.margen * 100).toFixed(1)}%
              </p>
            </Card>
          </div>
          {/* Producci├│n y categor├¡as de costo (acorde├│n inline) */}
          <Card className="p-0 overflow-hidden">
            <div className="px-4 py-3 border-b border-border">
              <h2 className="text-sm font-medium">Desglose de la semana</h2>
              <p className="text-xs text-muted-foreground mt-0.5">
                Expande cada categor├¡a para ver documentos y conceptos.
              </p>
            </div>
            <Accordion type="multiple" className="divide-y divide-border">
              {/* Producci├│n */}
              <CategoriaAccordion
                value="produccion"
                label="Producci├│n ejercida"
                monto={semana.produccion}
                pctCosto={null}
                pctProd={null}
                accent="emerald"
                docs={semana.produccion_detalle}
              />
              {/* Categor├¡as de costo */}
              {CATEGORIAS.map((cat) => {
                const monto = semana.costos[cat];
                const pctCosto = semana.costos_total > 0 ? (monto / semana.costos_total) * 100 : 0;
                const pctProd = semana.produccion > 0 ? (monto / semana.produccion) * 100 : 0;
                return (
                  <CategoriaAccordion
                    key={cat}
                    value={cat}
                    label={CATEGORIA_LABELS[cat]}
                    monto={monto}
                    pctCosto={monto > 0 ? pctCosto : null}
                    pctProd={monto > 0 && semana.produccion > 0 ? pctProd : null}
                    accent="rose"
                    docs={semana.detalle[cat]}
                  />
                );
              })}
              {/* Total costos (no expandible) */}
              <div className="grid grid-cols-[1fr_auto_auto_auto] items-center gap-4 px-4 py-3 font-semibold text-sm bg-muted/30">
                <div>Total costos</div>
                <div className="tabular-nums text-right min-w-[110px]">
                  {formatMXN(semana.costos_total)}
                </div>
                <div className="tabular-nums text-right text-muted-foreground min-w-[60px]">
                  100%
                </div>
                <div className="tabular-nums text-right text-muted-foreground min-w-[70px]">
                  {semana.produccion > 0
                    ? `${((semana.costos_total / semana.produccion) * 100).toFixed(1)}%`
                    : "ÔÇö"}
                </div>
              </div>
            </Accordion>
          </Card>

          {/* Hist├│rico 8 semanas */}
          {histQ.data && histQ.data.length > 0 && (
            <Card className="p-4">
              <h2 className="text-sm font-medium mb-3">├Ültimas 8 semanas</h2>
              <HistorialChart
                datos={histQ.data.map((s) => ({
                  semana: fechaInicio
                    ? `S${numeroSemanaObra(fechaInicio, s.semana_inicio)}`
                    : s.semana_inicio.slice(5),
                  produccion: s.produccion,
                  costos: s.costos_total,
                }))}
              />
            </Card>
          )}

          {/* Acumulado */}
          {acumulado && (
            <Card className="p-4">
              <h2 className="text-sm font-medium mb-3">
                Acumulado de la obra
                {fechaInicio ? ` (Semanas 1ÔÇô${numSeleccion})` : " (hasta esta semana)"}
              </h2>
              <div className="grid gap-4 sm:grid-cols-3 text-sm">
                <div>
                  <p className="text-xs uppercase tracking-wider text-muted-foreground">
                    Producci├│n
                  </p>
                  <p className="mt-1 text-lg font-semibold">{formatMXN(acumulado.produccion)}</p>
                </div>
                <div>
                  <p className="text-xs uppercase tracking-wider text-muted-foreground">Costos</p>
                  <p className="mt-1 text-lg font-semibold">{formatMXN(acumulado.costos)}</p>
                </div>
                <div>
                  <p className="text-xs uppercase tracking-wider text-muted-foreground">
                    Resultado
                  </p>
                  <p
                    className={`mt-1 text-lg font-semibold ${
                      acumulado.resultado >= 0
                        ? "text-emerald-600 dark:text-emerald-400"
                        : "text-rose-600 dark:text-rose-400"
                    }`}
                  >
                    {formatMXN(acumulado.resultado)}
                  </p>
                </div>
              </div>
              <p className="text-xs text-muted-foreground mt-2">
                Calculado sobre las ├║ltimas 8 semanas.
              </p>
            </Card>
          )}
        </>
      )}
    </div>
  );
}

function CategoriaAccordion({
  value,
  label,
  monto,
  pctCosto,
  pctProd,
  accent,
  docs,
}: {
  value: string;
  label: string;
  monto: number;
  pctCosto: number | null;
  pctProd: number | null;
  accent: "emerald" | "rose";
  docs: DocumentoCosto[];
}) {
  const disabled = monto <= 0;
  const accentClass =
    accent === "emerald"
      ? "text-emerald-600 dark:text-emerald-400"
      : "text-rose-600 dark:text-rose-400";
  return (
    <AccordionItem value={value} className="border-0" disabled={disabled}>
      <AccordionTrigger
        className="px-4 py-3 hover:no-underline data-[disabled]:opacity-60 data-[disabled]:cursor-default"
        disabled={disabled}
      >
        <div className="flex-1 grid grid-cols-[1fr_auto_auto_auto] items-center gap-4 pr-2 text-sm">
          <div className="font-medium text-left">{label}</div>
          <div
            className={`tabular-nums text-right min-w-[110px] ${monto > 0 ? accentClass : "text-muted-foreground"}`}
          >
            {monto > 0 ? formatMXN(monto) : "ÔÇö"}
          </div>
          <div className="tabular-nums text-right text-muted-foreground min-w-[60px]">
            {pctCosto != null ? `${pctCosto.toFixed(1)}%` : "ÔÇö"}
          </div>
          <div className="tabular-nums text-right text-muted-foreground min-w-[70px]">
            {pctProd != null ? `${pctProd.toFixed(1)}%` : "ÔÇö"}
          </div>
        </div>
      </AccordionTrigger>
      <AccordionContent className="px-4 pb-4 pt-0 bg-muted/20">
        <DocumentosLista docs={docs} />
      </AccordionContent>
    </AccordionItem>
  );
}

function DocumentosLista({ docs }: { docs: DocumentoCosto[] }) {
  if (docs.length === 0) {
    return <p className="text-sm text-muted-foreground">Sin movimientos en esta semana.</p>;
  }
  // Si ning├║n documento tiene conceptos, mostrar lista plana
  const conConceptos = docs.some((d) => d.conceptos && d.conceptos.length > 0);
  if (!conConceptos) {
    return (
      <div className="space-y-2">
        {docs.map((doc) => (
          <DocumentoFlat key={doc.id} doc={doc} />
        ))}
      </div>
    );
  }
  return (
    <Accordion type="multiple" className="space-y-2">
      {docs.map((doc) => {
        const hasConceptos = (doc.conceptos?.length ?? 0) > 0;
        if (!hasConceptos) {
          return (
            <div key={doc.id}>
              <DocumentoFlat doc={doc} />
            </div>
          );
        }
        return (
          <AccordionItem
            key={doc.id}
            value={doc.id}
            className="border border-border rounded-md px-3"
          >
            <AccordionTrigger className="py-3 hover:no-underline">
              <div className="flex-1 flex items-start justify-between gap-3 min-w-0 pr-2">
                <div className="min-w-0 text-left">
                  <p className="text-sm font-medium truncate">{doc.titulo}</p>
                  <div className="flex items-center gap-2 mt-1">
                    {doc.estatus && (
                      <Badge variant="outline" className="text-xs">
                        {doc.estatus}
                      </Badge>
                    )}
                    {doc.meta && (
                      <span className="text-xs text-muted-foreground truncate">{doc.meta}</span>
                    )}
                  </div>
                </div>
                <p className="text-sm tabular-nums font-medium whitespace-nowrap">
                  {formatMXN(doc.monto)}
                </p>
              </div>
            </AccordionTrigger>
            <AccordionContent className="pb-3">
              <ConceptosTabla items={doc.conceptos!} />
            </AccordionContent>
          </AccordionItem>
        );
      })}
    </Accordion>
  );
}

function DocumentoFlat({ doc }: { doc: DocumentoCosto }) {
  return (
    <div className="flex items-start justify-between gap-3 p-3 rounded-md border border-border">
      <div className="min-w-0">
        <p className="text-sm font-medium truncate">{doc.titulo}</p>
        <div className="flex items-center gap-2 mt-1">
          {doc.estatus && (
            <Badge variant="outline" className="text-xs">
              {doc.estatus}
            </Badge>
          )}
          {doc.meta && <span className="text-xs text-muted-foreground truncate">{doc.meta}</span>}
        </div>
      </div>
      <p className="text-sm tabular-nums font-medium whitespace-nowrap">{formatMXN(doc.monto)}</p>
    </div>
  );
}

function ConceptosTabla({ items }: { items: ConceptoDetalle[] }) {
  if (items.length === 0) {
    return <p className="text-xs text-muted-foreground">Sin conceptos.</p>;
  }
  const showCantidad = items.some((i) => i.cantidad != null && i.cantidad !== 0);
  const showPU = items.some((i) => i.precio_unitario != null && i.precio_unitario !== 0);
  return (
    <div className="overflow-x-auto -mx-3">
      <table className="w-full text-xs">
        <thead className="text-muted-foreground">
          <tr className="border-b border-border">
            <th className="text-left font-normal py-1.5 px-3">Concepto</th>
            {showCantidad && <th className="text-right font-normal py-1.5 px-2">Cant.</th>}
            {showPU && <th className="text-right font-normal py-1.5 px-2">P.U.</th>}
            <th className="text-right font-normal py-1.5 px-3">Importe</th>
          </tr>
        </thead>
        <tbody>
          {items.map((c) => (
            <tr key={c.id} className="border-b border-border/50 last:border-b-0">
              <td className="py-1.5 px-3">
                <div className="font-medium">{c.descripcion}</div>
                {c.meta && <div className="text-xs text-muted-foreground">{c.meta}</div>}
              </td>
              {showCantidad && (
                <td className="text-right tabular-nums py-1.5 px-2">
                  {c.cantidad != null ? `${c.cantidad}${c.unidad ? ` ${c.unidad}` : ""}` : "ÔÇö"}
                </td>
              )}
              {showPU && (
                <td className="text-right tabular-nums py-1.5 px-2 text-muted-foreground">
                  {c.precio_unitario != null ? formatMXN(c.precio_unitario) : "ÔÇö"}
                </td>
              )}
              <td className="text-right tabular-nums py-1.5 px-3 font-medium">
                {formatMXN(c.monto)}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

"use client";

import { useMemo, useState, useRef } from "react";
import { useServerFn } from "@/lib/server-fn/client";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import {
  getOrCreateBorrador,
  guardarRenglonesEstimacion,
} from "@/lib/api-client/estimaciones.functions";
import { calcularSemana, formatRangoSemana } from "@/lib/estimacion-utils";
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetDescription,
} from "@/components/ui/sheet";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip";
import { formatMXN } from "@/lib/format";
import { toast } from "sonner";
import { useSacudir } from "@/components/anim/useSacudir";
import { Save, AlertTriangle, Search } from "lucide-react";

type VigenteRow = {
  clave: string;
  concepto: string;
  unidad: string | null;
  cantidad: number | null;
  precio_unitario: number | null;
  importe: number;
  es_grupo: boolean;
  nivel: number;
  origen: "base" | "modificada" | "agregada";
};

export function CapturaEstimacionSheet({
  obraId,
  semanaInicio,
  onClose,
  onSaved,
}: {
  obraId: string;
  semanaInicio: string; // YYYY-MM-DD (lunes)
  onClose: () => void;
  onSaved?: () => void;
}) {
  const qc = useQueryClient();
  const fetchBorrador = useServerFn(getOrCreateBorrador);
  const q = useQuery({
    queryKey: ["estimacion-borrador", obraId, semanaInicio],
    queryFn: () => fetchBorrador({ data: { obraId, semanaInicio } }),
  });

  const [cantidades, setCantidades] = useState<Record<string, string>>({});
  const [filter, setFilter] = useState("");

  const [initialized, setInitialized] = useState(false);

  // Inicializar cantidades con lo capturado previamente
  if (!initialized && q.data?.capturados) {
    const init: Record<string, string> = {};
    for (const [k, v] of Object.entries(q.data.capturados)) {
      init[k] = String(v);
    }
    setCantidades(init);
    setInitialized(true);
  }

  const vigente = (q.data?.vigente ?? []) as VigenteRow[];
  const acumuladoPrevio = (q.data?.acumuladoPrevio ?? {}) as Record<string, number>;
  const estimacion = q.data?.estimacion;
  const semana = calcularSemana(semanaInicio);
  const semanaActual = calcularSemana(new Date()).inicio;
  const soloLectura = semanaInicio !== semanaActual;

  // Calcular validaciones y totales en cliente
  const computed = useMemo(() => {
    let totalSemana = 0;
    let totalAcum = 0;
    let totalVigente = 0;
    const erroresPorClave = new Map<string, string>();
    for (const r of vigente) {
      if (r.es_grupo) continue;
      const cantStr = cantidades[r.clave] ?? "";
      const cant = Number(cantStr || 0);
      const pu = Number(r.precio_unitario ?? 0);
      const cantVig = Number(r.cantidad ?? 0);
      const acumPrev = Number(acumuladoPrevio[r.clave] ?? 0);
      const nuevoAcum = acumPrev + (Number.isFinite(cant) ? cant : 0);
      if (cant > 0) totalSemana += cant * pu;
      totalAcum += nuevoAcum * pu;
      totalVigente += cantVig * pu;
      if (cantVig > 0 && nuevoAcum > cantVig + 0.0001) {
        erroresPorClave.set(
          r.clave,
          `Excede vigente por ${(nuevoAcum - cantVig).toLocaleString("es-MX", {
            maximumFractionDigits: 2,
          })}`,
        );
      }
    }
    return { totalSemana, totalAcum, totalVigente, erroresPorClave };
  }, [vigente, cantidades, acumuladoPrevio]);

  const visibleRows = useMemo(() => {
    const f = filter.trim().toLowerCase();
    if (!f) return vigente;
    return vigente.filter(
      (r) => r.clave.toLowerCase().includes(f) || r.concepto.toLowerCase().includes(f),
    );
  }, [vigente, filter]);

  const guardar = useServerFn(guardarRenglonesEstimacion);
  const guardarM = useMutation({
    mutationFn: guardar,
    onSuccess: () => {
      toast.success("Borrador guardado");
      qc.invalidateQueries({ queryKey: ["estimaciones", obraId] });
      qc.invalidateQueries({ queryKey: ["estimacion-borrador", obraId, semanaInicio] });
      onSaved?.();
      onClose();
    },
    onError: (e: Error) => toast.error(e.message),
  });

  // El toast dice qu├® fall├│; la sacudida dice d├│nde. Solo en validaci├│n local.
  const sacudirRef = useRef<HTMLDivElement>(null);
  const sacudir = useSacudir(sacudirRef);

  const handleGuardar = () => {
    if (!estimacion) return;
    if (computed.erroresPorClave.size > 0) {
      sacudir();
      toast.error("Hay conceptos que exceden el vigente. Corrige antes de guardar.");
      return;
    }
    const renglones = Object.entries(cantidades)
      .map(([k, v]) => ({ renglon_clave: k, cantidad_ejecutada: Number(v || 0) }))
      .filter((r) => Number.isFinite(r.cantidad_ejecutada) && r.cantidad_ejecutada > 0);

    guardarM.mutate({ data: { estimacionId: estimacion.id, renglones } });
  };

  const pctAvance =
    computed.totalVigente > 0 ? (computed.totalAcum / computed.totalVigente) * 100 : 0;

  return (
    <Sheet open onOpenChange={(o) => !o && onClose()}>
      <SheetContent ref={sacudirRef} side="right" className="w-full sm:max-w-6xl overflow-y-auto">
        <SheetHeader>
          <SheetTitle className="flex items-center gap-2 flex-wrap">
            Estimaci├│n semanal
            <Badge variant={soloLectura ? "default" : "secondary"}>
              {soloLectura ? "Cerrada" : "Activa"}
            </Badge>
            <span className="ml-auto text-sm text-muted-foreground">
              {formatRangoSemana(semana.inicio, semana.fin)}
            </span>
          </SheetTitle>
          <SheetDescription>
            Captura la cantidad ejecutada por concepto durante esta semana. Los grupos suman
            autom├íticamente.
          </SheetDescription>
        </SheetHeader>

        {q.isLoading ? (
          <p className="mt-6 text-sm text-muted-foreground">CargandoÔÇª</p>
        ) : !q.data?.hasBase ? (
          <Card className="mt-6 border-dashed p-8 text-center text-sm text-muted-foreground">
            No hay presupuesto base autorizado. No es posible estimar todav├¡a.
          </Card>
        ) : (
          <>
            <div className="grid gap-3 grid-cols-2 sm:grid-cols-4 mt-6">
              <StatCard label="Producci├│n semana" value={formatMXN(computed.totalSemana)} />
              <StatCard label="Acumulado a la fecha" value={formatMXN(computed.totalAcum)} />
              <StatCard label="Total vigente" value={formatMXN(computed.totalVigente)} />
              <StatCard
                label="% Avance"
                value={`${pctAvance.toFixed(1)}%`}
                tone={pctAvance > 100 ? "destructive" : "default"}
              />
            </div>

            <div className="flex items-center gap-2 mt-4">
              <div className="relative flex-1 max-w-sm">
                <Search className="absolute left-2 top-2.5 size-4 text-muted-foreground" />
                <Input
                  className="pl-8"
                  placeholder="Buscar por clave o conceptoÔÇª"
                  value={filter}
                  onChange={(e) => setFilter(e.target.value)}
                />
              </div>
              {computed.erroresPorClave.size > 0 && (
                <Badge variant="destructive" className="gap-1">
                  <AlertTriangle className="size-3" /> {computed.erroresPorClave.size} con exceso
                </Badge>
              )}
            </div>

            <TooltipProvider delayDuration={200}>
              <Card className="mt-4 overflow-x-auto">
                <table className="w-full min-w-[760px] text-xs table-fixed">
                  <colgroup>
                    <col className="w-24" />
                    <col />
                    <col className="w-14" />
                    <col className="w-20" />
                    <col className="w-20" />
                    <col className="w-24" />
                    <col className="w-28" />
                    <col className="w-16" />
                  </colgroup>
                  <thead className="bg-muted/50 text-[11px] uppercase tracking-wider text-muted-foreground">
                    <tr>
                      <th className="text-center px-2 py-1.5">Clave</th>
                      <th className="text-center px-2 py-1.5">Concepto</th>
                      <th className="text-center px-2 py-1.5">Un.</th>
                      <th className="text-center px-2 py-1.5">Cant. vig.</th>
                      <th className="text-center px-2 py-1.5">Acum. previo</th>
                      <th className="text-center px-2 py-1.5">Esta semana</th>
                      <th className="text-center px-2 py-1.5">Importe sem.</th>
                      <th className="text-center px-2 py-1.5">% Acum.</th>
                    </tr>
                  </thead>
                  <tbody>
                    {visibleRows.map((r) => {
                      const cantStr = cantidades[r.clave] ?? "";
                      const cant = Number(cantStr || 0);
                      const pu = Number(r.precio_unitario ?? 0);
                      const acumPrev = Number(acumuladoPrevio[r.clave] ?? 0);
                      const nuevoAcum = acumPrev + (Number.isFinite(cant) ? cant : 0);
                      const cantVig = Number(r.cantidad ?? 0);
                      const err = computed.erroresPorClave.get(r.clave);
                      const pct = cantVig > 0 ? (nuevoAcum / cantVig) * 100 : 0;
                      const importeSem = cant > 0 ? cant * pu : 0;
                      return (
                        <tr
                          key={r.clave}
                          className={`border-t border-border ${r.es_grupo ? "bg-muted/30 font-medium" : ""}`}
                        >
                          <td
                            className="px-2 py-1 tabular-nums whitespace-nowrap overflow-hidden text-ellipsis text-center"
                            style={{ paddingLeft: `${0.5 + (r.nivel - 1) * 1}rem` }}
                          >
                            {r.clave}
                          </td>
                          <td className="px-2 py-1 max-w-0 text-left">
                            <Tooltip>
                              <TooltipTrigger asChild>
                                <div className="truncate whitespace-nowrap overflow-hidden text-ellipsis cursor-default text-left">
                                  {r.concepto}
                                </div>
                              </TooltipTrigger>
                              <TooltipContent
                                side="top"
                                align="start"
                                className="max-w-md whitespace-normal"
                              >
                                {r.concepto}
                              </TooltipContent>
                            </Tooltip>
                          </td>
                          <td className="px-2 py-1 text-muted-foreground whitespace-nowrap overflow-hidden text-ellipsis text-center">
                            {r.unidad ?? "ÔÇö"}
                          </td>
                          <td className="px-2 py-1 text-center tabular-nums whitespace-nowrap">
                            {r.es_grupo
                              ? "ÔÇö"
                              : cantVig.toLocaleString("es-MX", { maximumFractionDigits: 2 })}
                          </td>
                          <td className="px-2 py-1 text-center tabular-nums text-muted-foreground whitespace-nowrap">
                            {r.es_grupo
                              ? "ÔÇö"
                              : acumPrev > 0
                                ? acumPrev.toLocaleString("es-MX", { maximumFractionDigits: 2 })
                                : "ÔÇö"}
                          </td>
                          <td className="px-2 py-1 text-center whitespace-nowrap">
                            {r.es_grupo ? (
                              <span className="text-muted-foreground">ÔÇö</span>
                            ) : (
                              <Input
                                type="number"
                                inputMode="decimal"
                                step="any"
                                min={0}
                                disabled={soloLectura}
                                value={cantStr}
                                onChange={(e) =>
                                  setCantidades((s) => ({ ...s, [r.clave]: e.target.value }))
                                }
                                className={`h-7 text-xs text-center tabular-nums ${err ? "border-destructive focus-visible:ring-destructive" : ""}`}
                                title={err ?? ""}
                              />
                            )}
                          </td>
                          <td className="px-2 py-1 text-center tabular-nums whitespace-nowrap">
                            {r.es_grupo ? "ÔÇö" : importeSem > 0 ? formatMXN(importeSem) : "ÔÇö"}
                          </td>
                          <td
                            className={`px-2 py-1 text-center tabular-nums whitespace-nowrap ${pct > 100 ? "text-destructive font-medium" : ""}`}
                          >
                            {r.es_grupo ? "ÔÇö" : `${pct.toFixed(0)}%`}
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </Card>
            </TooltipProvider>

            {!soloLectura && (
              <div className="flex gap-2 mt-4 flex-wrap justify-end sticky bottom-0 bg-background py-3">
                <Button
                  disabled={guardarM.isPending || computed.erroresPorClave.size > 0}
                  onClick={handleGuardar}
                  title={
                    computed.erroresPorClave.size > 0
                      ? "Hay conceptos que exceden el vigente. Corrige antes de guardar."
                      : undefined
                  }
                >
                  <Save className="size-4 mr-1" />
                  {guardarM.isPending ? "GuardandoÔÇª" : "Guardar"}
                </Button>
              </div>
            )}
          </>
        )}
      </SheetContent>
    </Sheet>
  );
}

