];
function toneFor(id: string | null | undefined) {
  if (!id) return "bg-muted text-muted-foreground";
  let h = 0;
  for (let i = 0; i < id.length; i++) h = (h * 31 + id.charCodeAt(i)) >>> 0;
  return BADGE_TONES[h % BADGE_TONES.length];
}

function fmtMoney(n: number) {
