function SolicitarDialog({
  open,
  onOpenChange,
  categorias,
  unidades,
  isDirector,
}: {
  open: boolean;
  onOpenChange: (b: boolean) => void;
  categorias: any[];
  unidades: any[];
  isDirector: boolean;
}) {
  const qc = useQueryClient();
  const defaultUnidad = unidades[0]?.codigo ?? "";
  const [nombre, setNombre] = useState("");
  const [unidad, setUnidad] = useState<Unidad>(defaultUnidad);
  const [categoriaId, setCategoriaId] = useState<string>("none");
  const [disponibleRenta, setDisponibleRenta] = useState<boolean>(false);

  // Ensure unidad has a valid default when unidades load
  if (!unidad && defaultUnidad) {
    setUnidad(defaultUnidad);
  }

  const mut = useMutation({
    mutationFn: useServerFn(solicitarInsumo),
    onSuccess: () => {
      toast.success(
        isDirector
          ? "Insumo creado y autorizado."
          : "Insumo solicitado. Pendiente de autorizaci├│n.",
      );
      qc.invalidateQueries({ queryKey: ["insumos"] });
      qc.invalidateQueries({ queryKey: ["insumos-metricas"] });
      setNombre("");
      setUnidad(defaultUnidad);
      setCategoriaId("none");
      setDisponibleRenta(false);
      onOpenChange(false);
    },
    onError: (e: any) => toast.error(e.message),
  });

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>{isDirector ? "Nuevo insumo" : "Solicitar insumo"}</DialogTitle>
          <DialogDescription>
            {isDirector
              ? "El insumo se crear├í autorizado en el cat├ílogo."
              : "El Director revisar├í tu solicitud."}
          </DialogDescription>
        </DialogHeader>
        <div className="space-y-3">
          <div>
            <Label>Nombre</Label>
            <Input value={nombre} onChange={(e) => setNombre(e.target.value)} maxLength={200} />
          </div>
          <div className="grid grid-cols-2 gap-3">
            <div>
              <Label>Unidad</Label>
              <Select value={unidad} onValueChange={(v) => setUnidad(v)}>
                <SelectTrigger>
                  <SelectValue placeholder="Seleccionar..." />
                </SelectTrigger>
                <SelectContent>
                  {unidades.length === 0 && (
                    <div className="px-2 py-1.5 text-xs text-muted-foreground">
                      Sin unidades. Pide al Director crearlas.
                    </div>
                  )}
                  {unidades.map((u: any) => (
                    <SelectItem key={u.id} value={u.codigo}>
                      {u.codigo}
                      {u.nombre ? ` ÔÇö ${u.nombre}` : ""}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label>Categor├¡a</Label>
              <Select value={categoriaId} onValueChange={setCategoriaId}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="none">Sin categor├¡a</SelectItem>
                  {categorias.map((c) => (
                    <SelectItem key={c.id} value={c.id}>
                      {c.nombre}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>
          {isDirector && (
            <div className="flex items-start gap-2 pt-1">
              <Checkbox
                id="disponible-renta-nuevo"
                checked={disponibleRenta}
                onCheckedChange={(v) => setDisponibleRenta(v === true)}
              />
              <div className="grid gap-0.5">
                <Label htmlFor="disponible-renta-nuevo" className="cursor-pointer">
                  Disponible para rentas
                </Label>
                <p className="text-xs text-muted-foreground">
                  Si se activa, este insumo podr├í seleccionarse al crear una renta.
                </p>
              </div>
            </div>
          )}
        </div>
        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            Cancelar
          </Button>
          <Button
            disabled={!nombre.trim() || !unidad || mut.isPending}
            onClick={() =>
              mut.mutate({
                data: {
                  nombre: nombre.trim(),
                  unidad,
                  categoriaId: categoriaId === "none" ? null : categoriaId,
                  ...(isDirector ? { disponibleRenta } : {}),
                },
              })
            }
          >
            {isDirector ? "Crear" : "Solicitar"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

function derivarPrefijoUI(nombre: string): string {
  const clean = nombre.toUpperCase().replace(/[^A-Z0-9]/g, "");
  return (clean + "XXX").slice(0, 3);
}

function CategoriasDialog({
  open,
  onOpenChange,
  categorias,
}: {
  open: boolean;
  onOpenChange: (b: boolean) => void;
  categorias: any[];
}) {
  const qc = useQueryClient();
  const [nueva, setNueva] = useState("");
  const [nuevoPrefijo, setNuevoPrefijo] = useState("");
  const [editing, setEditing] = useState<{ id: string; nombre: string; prefijo: string } | null>(
    null,
  );

  const invalidate = () => {
    qc.invalidateQueries({ queryKey: ["insumo-categorias"] });
    qc.invalidateQueries({ queryKey: ["insumos-metricas"] });
    qc.invalidateQueries({ queryKey: ["insumos"] });
  };

  const crearMut = useMutation({
    mutationFn: useServerFn(crearCategoria),
    onSuccess: () => {
      toast.success("Categor├¡a creada");
      setNueva("");
      setNuevoPrefijo("");
      invalidate();
    },
    onError: (e: any) => toast.error(e.message),
  });
  const editMut = useMutation({
    mutationFn: useServerFn(editarCategoria),
    onSuccess: () => {
      toast.success("Categor├¡a actualizada");
      setEditing(null);
      invalidate();
    },
    onError: (e: any) => toast.error(e.message),
  });
  const delMut = useMutation({
    mutationFn: useServerFn(eliminarCategoria),
    onSuccess: () => {
      toast.success("Categor├¡a eliminada");
      invalidate();
    },
    onError: (e: any) => toast.error(e.message),
  });

  const prefijoAuto = nueva.trim() ? derivarPrefijoUI(nueva.trim()) : "";

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>Categor├¡as de insumos</DialogTitle>
          <DialogDescription>
            El prefijo (3 caracteres) se usa para generar el c├│digo de los insumos, ej.{" "}
            <span className="font-mono">CEM-0001</span>.
          </DialogDescription>
        </DialogHeader>
        <div className="space-y-3">
          <div className="grid grid-cols-[1fr_100px_auto] gap-2 items-end">
            <div>
              <Label className="text-xs">Nombre</Label>
              <Input
                value={nueva}
                onChange={(e) => setNueva(e.target.value)}
                placeholder="Nueva categor├¡a..."
                maxLength={100}
              />
            </div>
            <div>
              <Label className="text-xs">Prefijo</Label>
              <Input
                value={nuevoPrefijo}
                onChange={(e) =>
                  setNuevoPrefijo(
                    e.target.value
                      .toUpperCase()
                      .replace(/[^A-Z0-9]/g, "")
                      .slice(0, 3),
                  )
                }
                placeholder={prefijoAuto || "AUTO"}
                maxLength={3}
                className="font-mono uppercase"
              />
            </div>
            <Button
              disabled={!nueva.trim() || crearMut.isPending}
              onClick={() =>
                crearMut.mutate({
                  data: {
                    nombre: nueva.trim(),
                    prefijo: nuevoPrefijo.length === 3 ? nuevoPrefijo : undefined,
                  },
                })
              }
            >
              <Plus /> Agregar
            </Button>
          </div>
          <div className="border rounded-md divide-y max-h-80 overflow-auto">
            {categorias.length === 0 && (
              <p className="text-sm text-muted-foreground p-4 text-center">Sin categor├¡as a├║n.</p>
            )}
            {categorias.map((c) => (
              <div key={c.id} className="flex items-center gap-2 p-2">
                {editing && editing.id === c.id ? (
                  <>
                    <Input
                      value={editing.nombre}
                      onChange={(e) =>
                        setEditing((prev) => (prev ? { ...prev, nombre: e.target.value } : prev))
                      }
                      maxLength={100}
                      className="flex-1"
                    />
                    <Input
                      value={editing.prefijo}
                      onChange={(e) =>
                        setEditing((prev) =>
                          prev
                            ? {
                                ...prev,
                                prefijo: e.target.value
                                  .toUpperCase()
                                  .replace(/[^A-Z0-9]/g, "")
                                  .slice(0, 3),
                              }
                            : prev,
                        )
                      }
                      maxLength={3}
                      className="w-20 font-mono uppercase"
                    />
                    <Button
                      size="sm"
                      onClick={() =>
                        editing &&
                        editMut.mutate({
                          data: {
                            id: editing.id,
                            nombre: editing.nombre.trim(),
                            prefijo: editing.prefijo.length === 3 ? editing.prefijo : undefined,
                          },
                        })
                      }
                    >
                      Guardar
                    </Button>
                    <Button size="sm" variant="outline" onClick={() => setEditing(null)}>
                      Cancelar
                    </Button>
                  </>
                ) : (
                  <>
                    <span className="flex-1 text-sm">{c.nombre}</span>
                    <Badge variant="outline" className="font-mono">
                      {c.prefijo ?? "ÔÇö"}
                    </Badge>
                    <Button
                      size="icon"
                      variant="ghost"
                      aria-label={`Editar categor├¡a ${c.nombre}`}
                      onClick={() =>
                        setEditing({ id: c.id, nombre: c.nombre, prefijo: c.prefijo ?? "" })
                      }
                    >
                      <Pencil />
                    </Button>
                    <Button
                      size="icon"
                      variant="ghost"
                      aria-label={`Eliminar categor├¡a ${c.nombre}`}
                      onClick={() => {
                        if (confirm(`┬┐Eliminar "${c.nombre}"?`))
                          delMut.mutate({ data: { id: c.id } });
                      }}
                    >
                      <Trash2 />
                    </Button>
                  </>
                )}
              </div>
            ))}
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

function EditarInsumoDialog({
  insumo,
  categorias,
  unidades,
  onClose,
}: {
  insumo: any;
  categorias: any[];
  unidades: any[];
  onClose: () => void;
}) {
  const qc = useQueryClient();
  const [nombre, setNombre] = useState(insumo.nombre);
  const [codigo, setCodigo] = useState<string>(insumo.codigo ?? "");
  const [unidad, setUnidad] = useState<Unidad>(insumo.unidad);
  const [categoriaId, setCategoriaId] = useState<string>(insumo.categoria_id ?? "none");
  const [disponibleRenta, setDisponibleRenta] = useState<boolean>(!!insumo.disponible_renta);

  const codigoValido = !codigo || /^[A-Z0-9]{2,5}-\d{3,6}$/.test(codigo);

  const mut = useMutation({
    mutationFn: useServerFn(editarInsumo),
    onSuccess: () => {
      toast.success("Insumo actualizado");
      qc.invalidateQueries({ queryKey: ["insumos"] });
      qc.invalidateQueries({ queryKey: ["insumos-renta"] });
      onClose();
    },
    onError: (e: any) => toast.error(e.message),
  });

  return (
    <Dialog open onOpenChange={(o) => !o && onClose()}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>Editar insumo</DialogTitle>
        </DialogHeader>
        <div className="space-y-3">
          <div className="grid grid-cols-[140px_1fr] gap-3">
            <div>
              <Label>C├│digo</Label>
              <Input
                value={codigo}
                onChange={(e) => setCodigo(e.target.value.toUpperCase().replace(/[^A-Z0-9-]/g, ""))}
                placeholder="CEM-0001"
                maxLength={12}
                className="font-mono uppercase"
              />
              {!codigoValido && (
                <p className="text-[11px] text-destructive mt-1">
                  Formato: PREFIJO-N├ÜMERO (ej. CEM-0001)
                </p>
              )}
            </div>
            <div>
              <Label>Nombre</Label>
              <Input value={nombre} onChange={(e) => setNombre(e.target.value)} maxLength={200} />
            </div>
          </div>
          <div className="grid grid-cols-2 gap-3">
            <div>
              <Label>Unidad</Label>
              <Select value={unidad} onValueChange={(v) => setUnidad(v)}>
                <SelectTrigger>
                  <SelectValue placeholder="Seleccionar..." />
                </SelectTrigger>
                <SelectContent>
                  {unidades.map((u: any) => (
                    <SelectItem key={u.id} value={u.codigo}>
                      {u.codigo}
                      {u.nombre ? ` ÔÇö ${u.nombre}` : ""}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label>Categor├¡a</Label>
              <Select value={categoriaId} onValueChange={setCategoriaId}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="none">Sin categor├¡a</SelectItem>
                  {categorias.map((c) => (
                    <SelectItem key={c.id} value={c.id}>
                      {c.nombre}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>

          <label className="flex items-start gap-3 rounded-md border p-3 cursor-pointer hover:bg-muted/40">
            <Checkbox
              checked={disponibleRenta}
              onCheckedChange={(v) => setDisponibleRenta(v === true)}
              className="mt-0.5"
            />
            <div className="flex-1">
              <p className="text-sm font-medium">Disponible para rentas</p>
              <p className="text-xs text-muted-foreground">
                Si est├í activo, el insumo podr├í seleccionarse al crear una solicitud de renta en
                obra.
              </p>
            </div>
          </label>

          <p className="text-xs text-muted-foreground">
            El c├│digo se asigna autom├íticamente al crear el insumo. Solo se edita si necesitas
            corregirlo manualmente.
          </p>
        </div>
        <DialogFooter>
          <Button variant="outline" onClick={onClose}>
            Cancelar
          </Button>
          <Button
            disabled={!nombre.trim() || !codigoValido || mut.isPending}
            onClick={() =>
              mut.mutate({
                data: {
                  id: insumo.id,
                  nombre: nombre.trim(),
                  unidad,
                  categoriaId: categoriaId === "none" ? null : categoriaId,
                  codigo: codigo || undefined,
                  disponibleRenta,
                },
              })
            }
          >
            Guardar
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

