  const bloqueadosMap = useMemo(() => {
    const m = new Map<string, { destajo_id: string; destajo_nombre: string }>();
    for (const b of (bloqueadosQ.data ?? []) as Array<{
      trabajador_id: string;
      destajo_id: string;
      destajo_nombre: string;
