                  {renglones.reduce((s, r) => s + Number(r.horas_extras_total), 0).toFixed(1)}
                </p>
              </Card>
              <Card className="p-3 border-primary/30 bg-primary/5">
                <p className="text-xs text-muted-foreground">Monto semana</p>
