function DiaCell({
  renglonId,
  fecha,
  jornada,
  horasExtras,
  notaExtras,
  disabled,
  onSaved,
}: {
  renglonId: string;
  fecha: string;
  jornada: number;
  horasExtras: number;
  notaExtras: string | null;
  disabled: boolean;
  onSaved: () => void;
}) {
  const [j, setJ] = useState(jornada);
  const [h, setH] = useState(horasExtras);
  const [nota, setNota] = useState(notaExtras ?? "");
  const [popOpen, setPopOpen] = useState(false);
  useEffect(() => {
    setJ(jornada);
  }, [jornada]);
  useEffect(() => {
    setH(horasExtras);
  }, [horasExtras]);
  useEffect(() => {
    setNota(notaExtras ?? "");
  }, [notaExtras]);

  const guardar = useServerFn(guardarAsistencia);
  const save = useMutation({
    mutationFn: guardar,
    onSuccess: () => onSaved(),
    onError: (e: Error) => toast.error(e.message),
  });

  const commitJornada = (nj: 0 | 0.5 | 1) => {
    if (nj === jornada) return;
    save.mutate({
      data: { renglonId, fecha, jornada: nj, horasExtras, notaExtras: notaExtras ?? null },
    });
  };

  const guardarExtras = () => {
    const notaLimpia = nota.trim();
    if (h > 0 && notaLimpia.length < 3) {
      toast.error("Captura una nota que explique el motivo de las horas extras.");
      return;
    }
    save.mutate(
      {
        data: {
          renglonId,
          fecha,
          jornada: j as 0 | 0.5 | 1,
          horasExtras: h,
          notaExtras: h > 0 ? notaLimpia : null,
        },
      },
