function diasSemana(inicio: string): string[] {
  const out: string[] = [];
  const d = new Date(inicio + "T12:00:00");
  for (let i = 0; i < 7; i++) {
    const x = new Date(d);
    x.setDate(d.getDate() + i);
    out.push(toISODate(x));
  }
  return out;
}

function shiftSemana(inicio: string, deltaDias: number): string {
  const d = new Date(inicio + "T12:00:00");
  d.setDate(d.getDate() + deltaDias);
  return calcularSemana(d).inicio;
}

function tieneAjustes(t: { obras: { asistencias: { ajustado_at: string | null }[] }[] }): boolean {
  return t.obras.some((o) => o.asistencias.some((a) => !!a.ajustado_at));
}

