          </Card>
        ) : (
          <Card className="p-3 border-primary/30 bg-primary/5">
            <p className="text-sm font-medium flex items-center gap-2">
              <CheckCircle2 className="size-4 text-primary-ink" />
              Semana cuadrada: ning├║n d├¡a excede una jornada.
            </p>
          </Card>
        )}

        {puedeAjustar && (
          <p className="text-xs text-muted-foreground">
            Haz click en una celda para ajustar la jornada u horas extras de esa obra y d├¡a. Cada
            ajuste requiere motivo y queda registrado.
          </p>
        )}

        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead className="bg-muted/50 text-xs uppercase tracking-wider text-muted-foreground">
              <tr>
                <th className="text-left p-2">Obra</th>
                {dias.map((f, i) => (
                  <th key={f} className="text-center p-1 w-14">
                    <div>{DOW[i]}</div>
                    <div className="text-xs font-normal opacity-70">{f.slice(8)}</div>
                  </th>
                ))}
                <th className="text-right p-2 w-20">D├¡as</th>
                <th className="text-right p-2 w-20">HE</th>
                <th className="text-right p-2 w-24">Importe</th>
              </tr>
            </thead>
            <tbody>
              {trabajador.obras.map((o) => {
                const map = new Map(o.asistencias.map((a) => [a.fecha, a]));
                const editable = puedeAjustar && o.estatus !== "pagada";
                return (
                  <tr key={o.nomina_id} className="border-t border-border">
                    <td className="p-2 font-medium">{o.nombre}</td>
                    {dias.map((f) => {
                      const a = map.get(f) ?? null;
                      const ajustada = !!a?.ajustado_at;
                      const contenido = (
                        <div className="flex flex-col items-center leading-tight">
                          <span className="inline-flex items-center gap-0.5">
                            {a && a.jornada > 0 ? a.jornada.toFixed(1) : "ÔÇö"}
                            {ajustada && <Pencil className="size-2.5 text-edited-foreground" />}
                          </span>
                          {a && a.horas_extras > 0 && (
                            <span
                              className="text-xs text-primary-ink inline-flex items-center gap-0.5"
                              title={a.nota_extras ?? "Sin nota"}
                            >
                              +{a.horas_extras}h
                              {a.nota_extras && <MessageSquare className="size-2.5 opacity-70" />}
                            </span>
                          )}
                        </div>
                      );
                      return (
                        <td
                          key={f}
                          className={cn(
                            "p-1 text-center tabular-nums text-xs",
                            editable && "cursor-pointer hover:bg-muted/50 rounded",
                            ajustada &&
                              "bg-edited text-edited-foreground font-medium ring-1 ring-inset ring-edited-border rounded hover:bg-edited",
                          )}
                          onClick={
                            editable
                              ? () => setEditando({ obra: o, fecha: f, asistencia: a })
                              : undefined
                          }
                        >
                          {ajustada ? (
                            <Tooltip>
                              <TooltipTrigger asChild>
                                <div>{contenido}</div>
                              </TooltipTrigger>
                              <TooltipContent className="max-w-xs text-xs">
                                <p>
                                  Ajustado {formatDateTime(a!.ajustado_at)} ┬À antes{" "}
                                  {Number(a!.jornada_original ?? 0).toFixed(1)} jornada
                                  {a!.horas_extras_original
                                    ? ` / ${Number(a!.horas_extras_original).toFixed(1)}h extra`
                                    : ""}
                                </p>
                                <p className="mt-1 opacity-80">{a!.ajuste_motivo}</p>
                              </TooltipContent>
                            </Tooltip>
                          ) : (
                            contenido
                          )}
