                    })}
                    <td className="p-2 text-right tabular-nums">{o.dias.toFixed(1)}</td>
                    <td className="p-2 text-right tabular-nums">{o.horas_extras.toFixed(1)}</td>
                    <td className="p-2 text-right tabular-nums">{formatMXN(o.importe)}</td>
                  </tr>
                );
