              <tr className="border-t border-border font-medium bg-muted/30">
                <td className="p-2">Suma diaria</td>
                {dias.map((f) => {
                  const s = sumaPorFecha.get(f) ?? 0;
                  const dup = s > 1.0001;
                  return (
                    <td
                      key={f}
                      className={cn(
                        "p-1 text-center tabular-nums text-xs",
                        dup && "text-destructive font-semibold",
                      )}
                    >
                      {s > 0 ? s.toFixed(1) : "ÔÇö"}
                    </td>
                  );
                })}
                <td className="p-2 text-right tabular-nums">
                  {trabajador.dias_totales.toFixed(1)}
                </td>
                <td className="p-2 text-right tabular-nums">
                  {trabajador.horas_extras_totales.toFixed(1)}
                </td>
                <td className="p-2 text-right tabular-nums">
                  {formatMXN(trabajador.importe_total)}
                </td>
              </tr>
            </tbody>
          </table>
        </div>

        {editando && (
          <AjusteAsistenciaDialog
            obra={editando.obra}
            fecha={editando.fecha}
            asistencia={editando.asistencia}
            semanaInicio={semanaInicio}
            trabajadorNombre={trabajador.nombre}
            onClose={() => setEditando(null)}
          />
        )}
      </DialogContent>
    </Dialog>
  );
}

function AjusteAsistenciaDialog({
  obra,
  fecha,
  asistencia,
  semanaInicio,
  trabajadorNombre,
  onClose,
}: {
  obra: ObraPanel;
  fecha: string;
  asistencia: AsistenciaPanel | null;
  semanaInicio: string;
  trabajadorNombre: string;
  onClose: () => void;
}) {
  const yaAjustada = !!asistencia?.ajustado_at;
  const [jornada, setJornada] = useState<number>(asistencia?.jornada ?? 0);
  const [horas, setHoras] = useState<string>(String(asistencia?.horas_extras ?? 0));
  const [motivo, setMotivo] = useState(asistencia?.ajuste_motivo ?? "");
  const [saving, setSaving] = useState(false);
  const qc = useQueryClient();
  const ajustar = useServerFn(ajustarAsistenciaAdmin);

  const horasNum = Number(horas) || 0;
  const valido = motivo.trim().length >= 5 && horasNum >= 0 && horasNum <= 24;

  async function guardar() {
    if (!valido) return;
    setSaving(true);
    try {
      await ajustar({
        data: {
          renglonId: obra.renglon_id,
          fecha,
          jornada: jornada as 0 | 0.5 | 1,
          horasExtras: horasNum,
          motivo: motivo.trim(),
        },
      });
      await qc.invalidateQueries({ queryKey: ["nomina-panel", semanaInicio] });
      await qc.invalidateQueries({ queryKey: ["nomina-por-pagar"] });
      toast.success("Asistencia ajustada");
      onClose();
    } catch (e: any) {
      toast.error(e?.message ?? "No se pudo ajustar");
    } finally {
      setSaving(false);
    }
  }

  return (
    <Dialog open onOpenChange={(o) => !o && onClose()}>
      <DialogContent className="max-w-md">
        <DialogHeader>
          <DialogTitle>{yaAjustada ? "Editar ajuste" : "Ajustar asistencia"}</DialogTitle>
          <DialogDescription>
            {trabajadorNombre} ┬À {obra.nombre} ┬À {fecha}
          </DialogDescription>
        </DialogHeader>

        {yaAjustada && (
          <Card className="p-3 bg-muted/40 text-xs space-y-1">
            <p className="font-medium">Ajustado el {formatDateTime(asistencia!.ajustado_at)}</p>
            <p className="text-muted-foreground">
              Valores originales: {Number(asistencia!.jornada_original ?? 0).toFixed(1)} jornada ┬À{" "}
              {Number(asistencia!.horas_extras_original ?? 0).toFixed(1)} h extra
            </p>
            <p className="text-muted-foreground">
              Al guardar se actualiza este mismo ajuste (no se crea uno nuevo).
            </p>
          </Card>
        )}

        <div className="space-y-4">
          <div>
            <Label className="text-xs">Jornada</Label>
            <div className="flex gap-2 mt-1">
              {[0, 0.5, 1].map((v) => (
                <Button
                  key={v}
                  type="button"
                  size="sm"
                  variant={jornada === v ? "default" : "outline"}
                  onClick={() => setJornada(v)}
                >
                  {v === 0 ? "Falta" : v === 0.5 ? "Medio d├¡a" : "D├¡a completo"}
                </Button>
              ))}
            </div>
          </div>

          <div>
            <Label className="text-xs">Horas extras</Label>
            <Input
              type="number"
              min={0}
              max={24}
              step="0.5"
              value={horas}
              onChange={(e) => setHoras(e.target.value)}
              className="mt-1"
            />
          </div>

          <div>
            <Label className="text-xs">
              Motivo del ajuste <span className="text-destructive">*</span>
            </Label>
            <Textarea
              value={motivo}
              onChange={(e) => setMotivo(e.target.value)}
              placeholder="Ej. El trabajador estuvo medio d├¡a en esta obra; el resto en la otra."
              rows={3}
              className="mt-1"
            />
            <p className="text-[11px] text-muted-foreground mt-1">M├¡nimo 5 caracteres.</p>
          </div>
        </div>

        <DialogFooter>
          <Button variant="ghost" onClick={onClose} disabled={saving}>
            Cancelar
          </Button>
          <Button onClick={guardar} disabled={!valido || saving}>
            {saving ? "GuardandoÔÇª" : yaAjustada ? "Actualizar ajuste" : "Guardar ajuste"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useMemo, useRef, useState } from "react";
import { useServerFn } from "@/lib/server-fn/client";
import { useQuery, useQueryClient, useMutation } from "@tanstack/react-query";
import { useNavigate } from "@/lib/navigation";
import { Bell, CheckCheck, Search } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Card } from "@/components/ui/card";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { formatDateTime } from "@/lib/format";
import { useStagger } from "@/components/anim/useStagger";
import {
  listMisNotificaciones,
  marcarNotificacionLeida,
  marcarTodasLeidas,
} from "@/lib/api-client/notificaciones.functions";

type Filter = "todas" | "no_leidas" | "leidas";

export function NotificacionesModule() {
  const qc = useQueryClient();
  const navigate = useNavigate();
  const fetchList = useServerFn(listMisNotificaciones);
  const markOneFn = useServerFn(marcarNotificacionLeida);
  const markAllFn = useServerFn(marcarTodasLeidas);

  const [filter, setFilter] = useState<Filter>("todas");
  const [tipo, setTipo] = useState<string>("todos");
  const [search, setSearch] = useState("");

  const q = useQuery({
    queryKey: ["notificaciones", "modulo"],
    queryFn: () => fetchList({ data: { limit: 100 } }),
    refetchInterval: 30_000,
  });

  const items = (q.data as any)?.items ?? [];
  const noLeidas = (q.data as any)?.noLeidas ?? 0;

  const tipos = useMemo(() => {
    const set = new Set<string>();
    for (const n of items) if (n.tipo) set.add(n.tipo);
    return Array.from(set).sort();
  }, [items]);

  const filtered = useMemo(() => {
    return items.filter((n: any) => {
      if (filter === "no_leidas" && n.leida_at) return false;
      if (filter === "leidas" && !n.leida_at) return false;
      if (tipo !== "todos" && n.tipo !== tipo) return false;
      if (search.trim()) {
        const s = search.toLowerCase();
        const hay = `${n.titulo ?? ""} ${n.mensaje ?? ""}`.toLowerCase();
        if (!hay.includes(s)) return false;
      }
      return true;
    });
  }, [items, filter, tipo, search]);

  const markOne = useMutation({
    mutationFn: (id: string) => markOneFn({ data: { id } }),
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: ["notificaciones"] });
      qc.invalidateQueries({ queryKey: ["notificaciones", "modulo"] });
    },
  });
  const markAll = useMutation({
    mutationFn: () => markAllFn(),
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: ["notificaciones"] });
      qc.invalidateQueries({ queryKey: ["notificaciones", "modulo"] });
    },
  });

  const handleOpen = (n: any) => {
    if (!n.leida_at) markOne.mutate(n.id);
    if (!n.link) return;
    const url = new URL(n.link, window.location.origin);
    const search = Object.fromEntries(url.searchParams.entries());
    navigate({ to: url.pathname as any, search: search as any });
  };

  // Lista de decisi├│n, no tabla: los avisos entran escalonados al cargar y al
  // cambiar de filtro. El tope de 8 del primitivo evita una cascada de 100.
  const lista = useRef<HTMLUListElement>(null);
  useStagger(lista, "[data-aviso]", [filtered.length, q.isLoading]);

  return (
    <div className="space-y-6">
      <header className="flex flex-wrap items-center justify-between gap-3">
        <div>
          <h1 className="text-2xl font-semibold tracking-tight flex items-center gap-2">
            <Bell className="size-6" /> Notificaciones
            {noLeidas > 0 && (
              <Badge className="bg-rose-600 text-white border-0">{noLeidas} nuevas</Badge>
            )}
          </h1>
          <p className="text-sm text-muted-foreground mt-1">
            Historial completo de notificaciones de tu cuenta.
          </p>
        </div>
        {noLeidas > 0 && (
          <Button
            variant="outline"
            size="sm"
            className="gap-1"
            onClick={() => markAll.mutate()}
            disabled={markAll.isPending}
          >
            <CheckCheck className="size-4" /> Marcar todas como le├¡das
          </Button>
        )}
      </header>

      <Card className="p-4 space-y-4">
        <div className="flex flex-wrap items-center gap-3">
          <Tabs value={filter} onValueChange={(v) => setFilter(v as Filter)}>
            <TabsList>
              <TabsTrigger value="todas">Todas</TabsTrigger>
              <TabsTrigger value="no_leidas">
                No le├¡das{noLeidas > 0 ? ` (${noLeidas})` : ""}
              </TabsTrigger>
              <TabsTrigger value="leidas">Le├¡das</TabsTrigger>
            </TabsList>
          </Tabs>

          <Select value={tipo} onValueChange={setTipo}>
            <SelectTrigger className="w-52">
              <SelectValue placeholder="Tipo" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="todos">Todos los tipos</SelectItem>
              {tipos.map((t) => (
                <SelectItem key={t} value={t}>
                  {t}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>

          <div className="relative flex-1 min-w-[200px]">
            <Search className="absolute left-2 top-1/2 -translate-y-1/2 size-4 text-muted-foreground" />
            <Input
              className="pl-8"
              aria-label="Buscar en notificaciones" placeholder="Buscar en t├¡tulo o mensajeÔÇª"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
            />
          </div>
        </div>

        {q.isLoading ? (
          <p className="p-8 text-sm text-muted-foreground text-center">CargandoÔÇª</p>
        ) : filtered.length === 0 ? (
          <div className="p-10 text-center">
            <Bell className="size-8 mx-auto text-muted-foreground/50" />
            <p className="mt-2 text-sm text-muted-foreground">Sin notificaciones para mostrar</p>
          </div>
        ) : (
          <ul ref={lista} className="divide-y rounded-md border">
            {filtered.map((n: any) => (
              <li
                key={n.id}
                data-aviso
                className={`px-4 py-3 cursor-pointer hover:bg-muted/50 transition-colors ${
                  !n.leida_at ? "bg-blue-50/40" : ""
                }`}
                onClick={() => handleOpen(n)}
              >
                <div className="flex items-start gap-3">
                  <span
                    className={`mt-1.5 size-2 rounded-full shrink-0 ${
                      !n.leida_at ? "bg-blue-500" : "bg-transparent"
                    }`}
                  />
                  <div className="flex-1 min-w-0">
                    <div className="flex items-start justify-between gap-2">
                      <p
                        className={`text-sm truncate ${!n.leida_at ? "font-semibold" : "font-medium"}`}
                      >
                        {n.titulo}
                      </p>
                      {n.tipo && (
                        <Badge variant="outline" className="text-xs shrink-0">
                          {n.tipo}
                        </Badge>
                      )}
                    </div>
                    <p className="text-xs text-muted-foreground mt-0.5 line-clamp-2">{n.mensaje}</p>
                    <p className="text-xs text-muted-foreground mt-1">
                      {formatDateTime(n.created_at)}
                    </p>
                  </div>
                </div>
              </li>
            ))}
          </ul>
        )}
      </Card>
    </div>
  );
}

"use client";

import { useMemo, useState } from "react";
