type AnticipoRow = {
  anticipoId: string;
  destajoId: string;
  monto: number;
  solicitadoAt: string;
  notas: string | null;
  solicitadoPorNombre: string;
  destajoNombre: string;
  destajoNumero: number | null;
  destajistaNombre: string;
  obraNombre: string;
};

type CxPRow = {
  id: string;
  folio: string;
  fecha_emision: string;
  obra_id: string | null;
  obra_nombre: string | null;
  beneficiario_nombre: string;
  concepto: string;
  monto_total: number;
  monto_pagado: number;
  saldo: number;
  estatus: "pendiente" | "parcial" | "pagada" | "cancelada";
  origen_tipo: string;
  origen_id: string | null;
};

type UnifiedRow =
  | {
      key: string;
      tipo: "anticipo";
      fecha: string;
      folio: string;
      obra: string;
      destajista: string;
      concepto: string;
      total: number;
      pagado: number;
      saldo: number;
      estatus: "pendiente";
      anticipo: AnticipoRow;
    }
  | {
      key: string;
      tipo: "estimacion";
      fecha: string;
      folio: string;
      obra: string;
      destajista: string;
      concepto: string;
      total: number;
      pagado: number;
      saldo: number;
      estatus: "pendiente" | "parcial" | "pagada" | "cancelada";
      cxp: CxPRow;
    };

function AnticiposDestajoTab() {
  const fetchAnticipos = useServerFn(listAnticiposDestajoPendientes);
  const fetchEstimaciones = useServerFn(listCxPDestajoPendientes);
  const qc = useQueryClient();
  const [pagar, setPagar] = useState<AnticipoRow | null>(null);
  const [pagarCxP, setPagarCxP] = useState<CxPRow | null>(null);

  const antQ = useQuery({
    queryKey: ["anticipos-destajo-pendientes"],
    queryFn: () => fetchAnticipos(),
  });
  const estQ = useQuery({
    queryKey: ["cxp-destajo-pendientes"],
    queryFn: () => fetchEstimaciones(),
  });

  const anticipos = (antQ.data ?? []) as AnticipoRow[];
  const estimaciones = (estQ.data ?? []) as CxPRow[];

  const unified: UnifiedRow[] = [
    ...estimaciones.map<UnifiedRow>((r) => ({
      key: `est-${r.id}`,
      tipo: "estimacion",
      fecha: r.fecha_emision,
      folio: r.folio,
      obra: r.obra_nombre ?? "ÔÇö",
      destajista: r.beneficiario_nombre,
      concepto: r.concepto,
      total: r.monto_total,
      pagado: r.monto_pagado,
      saldo: r.saldo,
      estatus: r.estatus,
      cxp: r,
    })),
    ...anticipos.map<UnifiedRow>((r) => ({
      key: `ant-${r.anticipoId}`,
      tipo: "anticipo",
      fecha: r.solicitadoAt,
      folio: r.destajoNumero != null ? `#${r.destajoNumero} ┬À ${r.destajoNombre}` : r.destajoNombre,
      obra: r.obraNombre,
      destajista: r.destajistaNombre,
      concepto: r.notas ? `Anticipo de destajo ┬À ${r.notas}` : "Anticipo de destajo",
      total: r.monto,
      pagado: 0,
      saldo: r.monto,
      estatus: "pendiente",
      anticipo: r,
    })),
  ].sort((a, b) => (a.fecha < b.fecha ? 1 : a.fecha > b.fecha ? -1 : 0));

  const totalSaldo = unified.reduce((s, r) => s + r.saldo, 0);
  const isLoading = antQ.isLoading || estQ.isLoading;

  const invalidateAll = () => {
    qc.invalidateQueries({ queryKey: ["anticipos-destajo-pendientes"] });
    qc.invalidateQueries({ queryKey: ["cxp-destajo-pendientes"] });
    qc.invalidateQueries({ queryKey: ["destajo-anticipo"] });
    qc.invalidateQueries({ queryKey: ["cuentas-activas"] });
    qc.invalidateQueries({ queryKey: ["balance"] });
  };

  return (
    <div className="space-y-4">
      <div className="flex items-end justify-between gap-4 flex-wrap">
        <div>
          <h3 className="text-base font-semibold">Pagos a destajistas pendientes</h3>
          <p className="text-xs text-muted-foreground">
            Anticipos solicitados y estimaciones autorizadas pendientes de pago.
          </p>
        </div>
        <Card className="px-4 py-2">
          <p className="text-xs text-muted-foreground">Saldo total</p>
          <p className="text-lg font-semibold">{formatMXN(totalSaldo)}</p>
        </Card>
      </div>

      <Card>
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>Tipo</TableHead>
              <TableHead>Folio / Ref</TableHead>
              <TableHead>Obra</TableHead>
              <TableHead>Destajista</TableHead>
              <TableHead>Concepto</TableHead>
              <TableHead>Fecha</TableHead>
              <TableHead className="text-right">Total</TableHead>
              <TableHead className="text-right">Pagado</TableHead>
              <TableHead className="text-right">Saldo</TableHead>
              <TableHead>Estatus</TableHead>
              <TableHead className="text-right">Acci├│n</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {isLoading && (
              <TableRow>
                <TableCell colSpan={11} className="text-center text-sm text-muted-foreground py-8">
                  CargandoÔÇª
                </TableCell>
              </TableRow>
            )}
            {!isLoading && unified.length === 0 && (
              <TableRow>
                <TableCell colSpan={11} className="text-center text-sm text-muted-foreground py-8">
                  <HandCoins className="size-8 mx-auto mb-2 text-muted-foreground/50" />
                  Sin pagos a destajistas pendientes.
                </TableCell>
              </TableRow>
            )}
            {unified.map((r) => (
              <TableRow key={r.key}>
                <TableCell className="whitespace-nowrap">
                  <Badge
                    className={
                      r.tipo === "anticipo"
                        ? "bg-blue-100 text-blue-800"
                        : "bg-slate-100 text-slate-700"
                    }
                  >
                    {r.tipo === "anticipo" ? "Anticipo" : "Estimaci├│n"}
                  </Badge>
                </TableCell>
                <TableCell className="font-medium text-sm max-w-[200px]">
                  <TruncatedCell>{r.folio}</TruncatedCell>
                </TableCell>
                <TableCell className="text-xs max-w-[180px]">
                  <TruncatedCell>{r.obra}</TruncatedCell>
                </TableCell>
                <TableCell className="text-sm max-w-[180px]">
                  <TruncatedCell>{r.destajista}</TruncatedCell>
                </TableCell>
                <TableCell className="text-xs max-w-[260px]">
                  <TruncatedCell>{r.concepto}</TruncatedCell>
                </TableCell>
                <TableCell className="text-xs whitespace-nowrap">{formatDate(r.fecha)}</TableCell>
                <TableCell className="text-right whitespace-nowrap">{formatMXN(r.total)}</TableCell>
                <TableCell className="text-right whitespace-nowrap">
                  {formatMXN(r.pagado)}
                </TableCell>
                <TableCell className="text-right font-semibold whitespace-nowrap">
                  {formatMXN(r.saldo)}
                </TableCell>
                <TableCell className="whitespace-nowrap">
                  <Badge
                    className={
                      ESTADO_PAGO_BADGE[r.estatus === "pagada" ? "pagado" : r.estatus] ?? ""
                    }
                  >
                    {r.estatus === "parcial"
                      ? "Parcial"
                      : r.estatus === "pagada"
                        ? "Pagado"
                        : "Pendiente"}
                  </Badge>
                </TableCell>
                <TableCell className="text-right whitespace-nowrap">
                  {r.saldo > 0 && (
                    <Button
                      size="sm"
                      onClick={() => {
                        if (r.tipo === "anticipo") setPagar(r.anticipo);
                        else setPagarCxP(r.cxp);
                      }}
                    >
                      Registrar pago
                    </Button>
                  )}
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </Card>

      {pagar && (
        <RegistrarPagoAnticipoDialog
          destajoId={pagar.destajoId}
          destajoNombre={pagar.destajoNombre}
          destajistaNombre={pagar.destajistaNombre}
          folio={(pagar as any).folio ?? null}
          montoTotalContrato={Number((pagar as any).destajoMontoTotal ?? 0)}
          anticipoPct={Number((pagar as any).destajoAnticipoPct ?? 0)}
          monto={pagar.monto}
          open={!!pagar}
          onOpenChange={(o) => !o && setPagar(null)}
          onSaved={invalidateAll}
        />
      )}

      {pagarCxP && (
        <RegistrarPagoCxPDialog
          cxpId={pagarCxP.id}
          folio={pagarCxP.folio}
          beneficiarioNombre={pagarCxP.beneficiario_nombre}
          saldoPendiente={pagarCxP.saldo}
          open={!!pagarCxP}
          onOpenChange={(o) => !o && setPagarCxP(null)}
          onSaved={invalidateAll}
        />
      )}
    </div>
  );
}

