type AnticipoSubRow = {
  anticipoId: string;
  subcontratoId: string;
  monto: number;
  folio: string | null;
  solicitadoAt: string;
  notas: string | null;
  solicitadoPorNombre: string;
  subcontratoNombre: string;
  subcontratoNumero: number | null;
  subcontratoMontoTotal: number;
  subcontratoAnticipoPct: number;
  contratistaNombre: string;
  obraNombre: string;
};

type UnifiedSubRow =
  | {
      key: string;
      tipo: "anticipo";
      fecha: string;
      folio: string;
      obra: string;
      contratista: string;
      concepto: string;
      total: number;
      pagado: number;
      saldo: number;
      estatus: "pendiente";
      anticipo: AnticipoSubRow;
    }
  | {
      key: string;
      tipo: "estimacion";
      fecha: string;
      folio: string;
      obra: string;
      contratista: string;
      concepto: string;
      total: number;
      pagado: number;
      saldo: number;
      estatus: "pendiente" | "parcial" | "pagada" | "cancelada";
      cxp: CxPRow;
    };

function AnticiposSubcontratoTab() {
  const fetchAnticipos = useServerFn(listAnticiposSubcontratoPendientes);
  const fetchEstimaciones = useServerFn(listCxPSubcontratoPendientes);
  const qc = useQueryClient();
  const [pagar, setPagar] = useState<AnticipoSubRow | null>(null);
  const [pagarCxP, setPagarCxP] = useState<CxPRow | null>(null);

  const antQ = useQuery({
    queryKey: ["anticipos-subcontrato-pendientes"],
    queryFn: () => fetchAnticipos(),
  });
  const estQ = useQuery({
    queryKey: ["cxp-subcontrato-pendientes"],
    queryFn: () => fetchEstimaciones(),
  });

  const anticipos = (antQ.data ?? []) as AnticipoSubRow[];
  const estimaciones = (estQ.data ?? []) as CxPRow[];

  const unified: UnifiedSubRow[] = [
    ...estimaciones.map<UnifiedSubRow>((r) => ({
      key: `est-${r.id}`,
      tipo: "estimacion",
      fecha: r.fecha_emision,
      folio: r.folio,
      obra: r.obra_nombre ?? "ÔÇö",
      contratista: r.beneficiario_nombre,
      concepto: r.concepto,
      total: r.monto_total,
      pagado: r.monto_pagado,
      saldo: r.saldo,
      estatus: r.estatus,
      cxp: r,
    })),
    ...anticipos.map<UnifiedSubRow>((r) => ({
      key: `ant-${r.anticipoId}`,
      tipo: "anticipo",
      fecha: r.solicitadoAt,
      folio:
        r.subcontratoNumero != null
          ? `#${r.subcontratoNumero} ┬À ${r.subcontratoNombre}`
          : r.subcontratoNombre,
      obra: r.obraNombre,
      contratista: r.contratistaNombre,
      concepto: r.notas ? `Anticipo de subcontrato ┬À ${r.notas}` : "Anticipo de subcontrato",
      total: r.monto,
      pagado: 0,
      saldo: r.monto,
      estatus: "pendiente",
      anticipo: r,
    })),
  ].sort((a, b) => (a.fecha < b.fecha ? 1 : a.fecha > b.fecha ? -1 : 0));

  const totalSaldo = unified.reduce((s, r) => s + r.saldo, 0);
  const isLoading = antQ.isLoading || estQ.isLoading;

  const invalidateAll = () => {
    qc.invalidateQueries({ queryKey: ["anticipos-subcontrato-pendientes"] });
    qc.invalidateQueries({ queryKey: ["cxp-subcontrato-pendientes"] });
    qc.invalidateQueries({ queryKey: ["subcontrato-anticipo"] });
    qc.invalidateQueries({ queryKey: ["cuentas-activas"] });
    qc.invalidateQueries({ queryKey: ["balance"] });
  };

  return (
    <div className="space-y-4">
      <div className="flex items-end justify-between gap-4 flex-wrap">
        <div>
          <h3 className="text-base font-semibold">Pagos a contratistas pendientes</h3>
          <p className="text-xs text-muted-foreground">
            Anticipos solicitados y estimaciones autorizadas pendientes de pago.
          </p>
        </div>
        <Card className="px-4 py-2">
          <p className="text-xs text-muted-foreground">Saldo total</p>
          <p className="text-lg font-semibold">{formatMXN(totalSaldo)}</p>
        </Card>
      </div>

      <Card>
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>Tipo</TableHead>
              <TableHead>Folio / Ref</TableHead>
              <TableHead>Obra</TableHead>
              <TableHead>Contratista</TableHead>
              <TableHead>Concepto</TableHead>
              <TableHead>Fecha</TableHead>
              <TableHead className="text-right">Total</TableHead>
              <TableHead className="text-right">Pagado</TableHead>
              <TableHead className="text-right">Saldo</TableHead>
              <TableHead>Estatus</TableHead>
              <TableHead className="text-right">Acci├│n</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {isLoading && (
              <TableRow>
                <TableCell colSpan={11} className="text-center text-sm text-muted-foreground py-8">
                  CargandoÔÇª
                </TableCell>
              </TableRow>
            )}
            {!isLoading && unified.length === 0 && (
              <TableRow>
                <TableCell colSpan={11} className="text-center text-sm text-muted-foreground py-8">
                  <HandCoins className="size-8 mx-auto mb-2 text-muted-foreground/50" />
                  Sin pagos a contratistas pendientes.
                </TableCell>
              </TableRow>
            )}
            {unified.map((r) => (
              <TableRow key={r.key}>
                <TableCell className="whitespace-nowrap">
                  <Badge
                    className={
                      r.tipo === "anticipo"
                        ? "bg-blue-100 text-blue-800"
                        : "bg-slate-100 text-slate-700"
                    }
                  >
                    {r.tipo === "anticipo" ? "Anticipo" : "Estimaci├│n"}
                  </Badge>
                </TableCell>
                <TableCell className="font-medium text-sm max-w-[200px]">
                  <TruncatedCell>{r.folio}</TruncatedCell>
                </TableCell>
                <TableCell className="text-xs max-w-[180px]">
                  <TruncatedCell>{r.obra}</TruncatedCell>
                </TableCell>
                <TableCell className="text-sm max-w-[180px]">
                  <TruncatedCell>{r.contratista}</TruncatedCell>
                </TableCell>
                <TableCell className="text-xs max-w-[260px]">
                  <TruncatedCell>{r.concepto}</TruncatedCell>
                </TableCell>
                <TableCell className="text-xs whitespace-nowrap">{formatDate(r.fecha)}</TableCell>
                <TableCell className="text-right whitespace-nowrap">{formatMXN(r.total)}</TableCell>
                <TableCell className="text-right whitespace-nowrap">
                  {formatMXN(r.pagado)}
                </TableCell>
                <TableCell className="text-right font-semibold whitespace-nowrap">
                  {formatMXN(r.saldo)}
                </TableCell>
                <TableCell className="whitespace-nowrap">
                  <Badge
                    className={
                      ESTADO_PAGO_BADGE[r.estatus === "pagada" ? "pagado" : r.estatus] ?? ""
                    }
                  >
                    {r.estatus === "parcial"
                      ? "Parcial"
                      : r.estatus === "pagada"
                        ? "Pagado"
                        : "Pendiente"}
                  </Badge>
                </TableCell>
                <TableCell className="text-right whitespace-nowrap">
                  {r.saldo > 0 && (
                    <Button
                      size="sm"
                      onClick={() => {
                        if (r.tipo === "anticipo") setPagar(r.anticipo);
                        else setPagarCxP(r.cxp);
                      }}
                    >
                      Registrar pago
                    </Button>
                  )}
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </Card>

      {pagar && (
        <RegistrarPagoAnticipoSubcontratoDialog
          subcontratoId={pagar.subcontratoId}
          subcontratoNombre={pagar.subcontratoNombre}
          contratistaNombre={pagar.contratistaNombre}
          folio={pagar.folio}
          montoTotalContrato={pagar.subcontratoMontoTotal}
          anticipoPct={pagar.subcontratoAnticipoPct}
          monto={pagar.monto}
          open={!!pagar}
          onOpenChange={(o) => !o && setPagar(null)}
          onSaved={invalidateAll}
        />
      )}

      {pagarCxP && (
        <RegistrarPagoCxPDialog
          cxpId={pagarCxP.id}
          folio={pagarCxP.folio}
          beneficiarioNombre={pagarCxP.beneficiario_nombre}
          saldoPendiente={pagarCxP.saldo}
          open={!!pagarCxP}
          onOpenChange={(o) => !o && setPagarCxP(null)}
          onSaved={invalidateAll}
        />
      )}
    </div>
  );
}

"use client";

import { useMemo, useState } from "react";
import { useServerFn } from "@/lib/server-fn/client";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { Fuel, Search } from "lucide-react";
import { Card } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Badge } from "@/components/ui/badge";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { listValesPorPagar } from "@/lib/api-client/vales-gasolina.functions";
import { formatMXN, formatDate } from "@/lib/format";
import {
  RegistrarPagoValesGasolinaDialog,
  type ValeSeleccionado,
} from "./RegistrarPagoValesGasolinaDialog";
import { TruncatedCell } from "./TruncatedCell";

type ValeRow = {
  id: string;
  folio: string;
  obra_id: string | null;
  obra_nombre: string | null;
  tipo_combustible: string;
  estatus: string;
  ligado_at: string | null;
  solicitante_nombre: string | null;
  monto_autorizado: number;
  pagado: number;
  saldo: number;
};

export function GasolinasPorPagarTab() {
  const fetchVales = useServerFn(listValesPorPagar);
  const qc = useQueryClient();
  const [q, setQ] = useState("");
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [dialogOpen, setDialogOpen] = useState(false);

  const valesQ = useQuery({
    queryKey: ["vales-por-pagar"],
    queryFn: () => fetchVales(),
  });

  const allVales = (valesQ.data ?? []) as ValeRow[];

  const filtered = useMemo(() => {
    const term = q.trim().toLowerCase();
    if (!term) return allVales;
    return allVales.filter(
      (v) =>
        v.folio.toLowerCase().includes(term) ||
        (v.obra_nombre ?? "").toLowerCase().includes(term) ||
        (v.solicitante_nombre ?? "").toLowerCase().includes(term) ||
        v.tipo_combustible.toLowerCase().includes(term),
    );
  }, [allVales, q]);

  const totalSaldo = useMemo(() => allVales.reduce((s, v) => s + v.saldo, 0), [allVales]);

  const toggle = (id: string) => {
    setSelected((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  };
  const toggleAll = () => {
    if (filtered.every((v) => selected.has(v.id)) && filtered.length > 0) {
      setSelected((prev) => {
        const next = new Set(prev);
        filtered.forEach((v) => next.delete(v.id));
        return next;
      });
    } else {
      setSelected((prev) => {
        const next = new Set(prev);
        filtered.forEach((v) => next.add(v.id));
        return next;
      });
    }
  };

  const selectedRows = allVales.filter((v) => selected.has(v.id));
  const selectedTotal = selectedRows.reduce((s, v) => s + v.saldo, 0);
  const allChecked = filtered.length > 0 && filtered.every((v) => selected.has(v.id));

  const valesParaPagar: ValeSeleccionado[] = selectedRows.map((v) => ({
    id: v.id,
    folio: v.folio,
    obra_nombre: v.obra_nombre,
    saldo: v.saldo,
  }));

  const onSaved = () => {
    setSelected(new Set());
    qc.invalidateQueries({ queryKey: ["vales-por-pagar"] });
    qc.invalidateQueries({ queryKey: ["cuentas-activas"] });
    qc.invalidateQueries({ queryKey: ["balance"] });
    qc.invalidateQueries({ queryKey: ["vales-gasolina"] });
  };

  return (
    <div className="space-y-4 pb-24">
      <div className="flex items-end justify-between gap-4 flex-wrap">
        <div>
          <h3 className="text-base font-semibold">Vales de gasolina por pagar</h3>
          <p className="text-xs text-muted-foreground">
            Vales ligados y entregados al residente, pendientes de pago. Selecciona varios para
            liquidarlos en una sola operaci├│n.
          </p>
        </div>
        <Card className="px-4 py-2">
          <p className="text-xs text-muted-foreground">Saldo total</p>
          <p className="text-lg font-semibold">{formatMXN(totalSaldo)}</p>
        </Card>
      </div>

      <div className="relative max-w-sm">
        <Search className="absolute left-2 top-1/2 -translate-y-1/2 size-4 text-muted-foreground" />
        <Input
          className="pl-8"
          placeholder="Buscar folio, obra o solicitanteÔÇª"
          value={q}
          onChange={(e) => setQ(e.target.value)}
        />
      </div>

      <Card>
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead className="w-[40px]">
                <Checkbox
                  checked={allChecked}
                  onCheckedChange={toggleAll}
                  aria-label="Seleccionar todos"
                />
              </TableHead>
              <TableHead>Folio</TableHead>
              <TableHead>Obra</TableHead>
              <TableHead>Combustible</TableHead>
              <TableHead>Solicitante</TableHead>
              <TableHead>Entregado</TableHead>
              <TableHead className="text-right">Autorizado</TableHead>
              <TableHead className="text-right">Pagado</TableHead>
              <TableHead className="text-right">Saldo</TableHead>
              <TableHead>Estatus</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {valesQ.isLoading && (
              <TableRow>
                <TableCell colSpan={10} className="text-center text-sm text-muted-foreground py-8">
                  CargandoÔÇª
                </TableCell>
              </TableRow>
            )}
            {!valesQ.isLoading && filtered.length === 0 && (
              <TableRow>
                <TableCell colSpan={10} className="text-center text-sm text-muted-foreground py-8">
                  <Fuel className="size-8 mx-auto mb-2 text-muted-foreground/50" />
                  Sin vales de gasolina pendientes de pago.
                </TableCell>
              </TableRow>
            )}
            {filtered.map((v) => (
              <TableRow key={v.id} className={selected.has(v.id) ? "bg-muted/40" : ""}>
                <TableCell>
                  <Checkbox
                    checked={selected.has(v.id)}
                    onCheckedChange={() => toggle(v.id)}
                    aria-label={`Seleccionar ${v.folio}`}
                  />
                </TableCell>
                <TableCell className="font-medium max-w-[140px]">
                  <TruncatedCell>{v.folio}</TruncatedCell>
                </TableCell>
                <TableCell className="text-xs max-w-[180px]">
                  <TruncatedCell>{v.obra_nombre ?? "ÔÇö"}</TruncatedCell>
                </TableCell>
                <TableCell className="text-xs capitalize whitespace-nowrap">
                  {v.tipo_combustible}
                </TableCell>
                <TableCell className="text-xs max-w-[180px]">
                  <TruncatedCell>{v.solicitante_nombre ?? "ÔÇö"}</TruncatedCell>
                </TableCell>
                <TableCell className="text-xs whitespace-nowrap">
                  {v.ligado_at ? formatDate(v.ligado_at) : "ÔÇö"}
                </TableCell>
                <TableCell className="text-right whitespace-nowrap">
                  {formatMXN(v.monto_autorizado)}
                </TableCell>
                <TableCell className="text-right whitespace-nowrap">
                  {formatMXN(v.pagado)}
                </TableCell>
                <TableCell className="text-right font-semibold whitespace-nowrap">
                  {formatMXN(v.saldo)}
                </TableCell>
                <TableCell className="whitespace-nowrap">
                  <Badge
                    className={
                      v.estatus === "confirmado"
                        ? "bg-emerald-100 text-emerald-800"
                        : "bg-amber-100 text-amber-800"
                    }
                  >
                    {v.estatus === "confirmado" ? "Confirmado" : "Entregado"}
                  </Badge>
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </Card>

      {selected.size > 0 && (
        <div className="fixed bottom-4 left-1/2 -translate-x-1/2 z-50 bg-background border shadow-lg rounded-full px-6 py-3 flex items-center gap-4">
          <div className="text-sm">
            <span className="font-semibold">{selected.size}</span> vale
            {selected.size === 1 ? "" : "s"}
            <span className="text-muted-foreground"> ┬À </span>
            <span className="font-semibold">{formatMXN(selectedTotal)}</span>
          </div>
          <Button variant="ghost" size="sm" onClick={() => setSelected(new Set())}>
            Limpiar
          </Button>
          <Button size="sm" onClick={() => setDialogOpen(true)}>
            Registrar pago
          </Button>
        </div>
      )}

      {dialogOpen && (
        <RegistrarPagoValesGasolinaDialog
          vales={valesParaPagar}
          open={dialogOpen}
          onOpenChange={setDialogOpen}
          onSaved={onSaved}
        />
      )}
    </div>
  );
}

"use client";

import { useMemo, useState } from "react";
import { useServerFn } from "@/lib/server-fn/client";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { Receipt, Search } from "lucide-react";
import { Card } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { listCxPGastosObra } from "@/lib/api-client/gastos-obra.functions";
import { formatMXN, formatDate } from "@/lib/format";
import { RegistrarPagoCxPDialog } from "./RegistrarPagoCxPDialog";
import { TruncatedCell } from "./TruncatedCell";

type Row = {
  id: string;
  folio: string;
  fecha_emision: string;
  obra_id: string | null;
  obra_nombre: string | null;
  beneficiario_nombre: string;
  concepto: string;
  monto_total: number;
  monto_pagado: number;
  pendiente: number;
  estatus: string;
  requiere_banco: boolean;
};

export function GastosObraPorPagarTab() {
  const fetchCxP = useServerFn(listCxPGastosObra);
  const qc = useQueryClient();
  const [q, setQ] = useState("");
  const [pagar, setPagar] = useState<Row | null>(null);

  const cxpQ = useQuery({
    queryKey: ["gastos-obra-por-pagar"],
    queryFn: () => fetchCxP(),
  });

  const all = ((cxpQ.data ?? []) as Row[]).filter((r) => r.pendiente > 0.009);
  const filtered = useMemo(() => {
    const term = q.trim().toLowerCase();
    if (!term) return all;
    return all.filter(
      (r) =>
        r.folio.toLowerCase().includes(term) ||
        (r.obra_nombre ?? "").toLowerCase().includes(term) ||
        r.beneficiario_nombre.toLowerCase().includes(term) ||
        r.concepto.toLowerCase().includes(term),
    );
  }, [all, q]);

  const total = useMemo(() => all.reduce((s, r) => s + r.pendiente, 0), [all]);

  const onSaved = () => {
    setPagar(null);
    qc.invalidateQueries({ queryKey: ["gastos-obra-por-pagar"] });
    qc.invalidateQueries({ queryKey: ["gastos-obra"] });
    qc.invalidateQueries({ queryKey: ["cuentas-activas"] });
    qc.invalidateQueries({ queryKey: ["balance"] });
  };

  return (
    <div className="space-y-4">
      <div className="flex items-end justify-between gap-4 flex-wrap">
        <div>
          <h3 className="text-base font-semibold">Gastos de obra por pagar</h3>
          <p className="text-xs text-muted-foreground">
            Pagos directos autorizados por el supervisor. Con factura se paga desde banco; con nota,
            desde caja fuerte.
          </p>
        </div>
        <Card className="px-4 py-2">
          <p className="text-xs text-muted-foreground">Total pendiente</p>
          <p className="text-lg font-semibold">{formatMXN(total)}</p>
        </Card>
      </div>

      <div className="relative max-w-sm">
        <Search className="absolute left-2 top-1/2 -translate-y-1/2 size-4 text-muted-foreground" />
        <Input
          className="pl-8"
          placeholder="Buscar folio, obra, proveedor o conceptoÔÇª"
          value={q}
          onChange={(e) => setQ(e.target.value)}
        />
      </div>

      <Card>
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>Folio</TableHead>
              <TableHead>Fecha</TableHead>
              <TableHead>Obra</TableHead>
              <TableHead>Proveedor</TableHead>
              <TableHead>Concepto</TableHead>
              <TableHead>Pago</TableHead>
              <TableHead className="text-right">Monto</TableHead>
              <TableHead className="text-right">Pendiente</TableHead>
              <TableHead></TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {cxpQ.isLoading && (
              <TableRow>
                <TableCell colSpan={9} className="text-center text-sm text-muted-foreground py-8">
                  CargandoÔÇª
                </TableCell>
              </TableRow>
            )}
            {!cxpQ.isLoading && filtered.length === 0 && (
              <TableRow>
                <TableCell colSpan={9} className="text-center text-sm text-muted-foreground py-8">
                  <Receipt className="size-8 mx-auto mb-2 text-muted-foreground/50" />
                  Sin gastos de obra pendientes.
                </TableCell>
              </TableRow>
            )}
            {filtered.map((r) => (
              <TableRow key={r.id}>
                <TableCell className="whitespace-nowrap font-medium">{r.folio}</TableCell>
                <TableCell className="whitespace-nowrap">{formatDate(r.fecha_emision)}</TableCell>
                <TableCell className="max-w-[140px]">
                  <TruncatedCell>{r.obra_nombre ?? "ÔÇö"}</TruncatedCell>
                </TableCell>
                <TableCell className="max-w-[160px]">
                  <TruncatedCell>{r.beneficiario_nombre}</TruncatedCell>
                </TableCell>
                <TableCell className="max-w-[200px]">
                  <TruncatedCell>{r.concepto}</TruncatedCell>
                </TableCell>
                <TableCell className="whitespace-nowrap">
                  <Badge variant={r.requiere_banco ? "default" : "secondary"}>
                    {r.requiere_banco ? "Banco (factura)" : "Caja fuerte (nota)"}
                  </Badge>
                </TableCell>
                <TableCell className="text-right whitespace-nowrap">
                  {formatMXN(r.monto_total)}
                </TableCell>
                <TableCell className="text-right whitespace-nowrap font-semibold">
                  {formatMXN(r.pendiente)}
                </TableCell>
                <TableCell className="text-right">
                  <Button size="sm" onClick={() => setPagar(r)}>
                    Pagar
                  </Button>
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </Card>

      {pagar && (
        <RegistrarPagoCxPDialog
          cxpId={pagar.id}
          folio={pagar.folio}
          beneficiarioNombre={pagar.beneficiario_nombre}
          saldoPendiente={pagar.pendiente}
          open={!!pagar}
          onOpenChange={(o) => !o && setPagar(null)}
          onSaved={onSaved}
          defaultCuentaTipo={pagar.requiere_banco ? "bancaria" : "caja_fuerte"}
          restringirCuentaTipo
        />
      )}
    </div>
  );
}

"use client";

import { useEffect, useMemo, useState, useRef } from "react";
import { useServerFn } from "@/lib/server-fn/client";
import { useMutation, useQuery } from "@tanstack/react-query";
import {
  getPresupuesto,
  getVigente,
  guardarRenglonesOC,
  solicitarAutorizacionPresupuesto,
} from "@/lib/api-client/presupuestos.functions";
import {
  procesarOrdenCambio,
  calcularClavesPadre,
  type OCInput,
  type VigenteNode,
} from "@/lib/presupuesto-utils";
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetDescription,
} from "@/components/ui/sheet";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Card } from "@/components/ui/card";
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs";
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip";
import { Plus, Trash2, AlertCircle, CheckCircle2, Search, Eye } from "lucide-react";
import { VigenteViewerDialog } from "./VigenteViewerDialog";
import { toast } from "sonner";
import { useSacudir } from "@/components/anim/useSacudir";
import { formatMXN } from "@/lib/format";

type ModRow = {
  _id: string;
  clave: string;
  cantidad: number | null;
  precio_unitario: number | null;
};
type AddRow = {
  _id: string;
  clave: string;
  concepto: string;
  unidad: string;
  cantidad: number | null;
  precio_unitario: number | null;
};
type DelRow = { _id: string; clave: string };

let _id = 0;
const nextId = () => `o${++_id}`;

export function CapturaOrdenCambioSheet({
  obraId,
  presupuestoId,
  onClose,
  onSaved,
}: {
  obraId: string;
  presupuestoId: string;
  onClose: () => void;
  onSaved: () => void;
}) {
  const fetchOne = useServerFn(getPresupuesto);
  const fetchVigente = useServerFn(getVigente);

  const presQ = useQuery({
    queryKey: ["presupuesto", presupuestoId],
    queryFn: () => fetchOne({ data: { id: presupuestoId } }),
  });
  const vigQ = useQuery({
    queryKey: ["presupuesto-vigente", obraId],
    queryFn: () => fetchVigente({ data: { obraId } }),
  });

  const presupuesto = presQ.data?.presupuesto;
  const yaAutorizado = presupuesto?.estatus !== "borrador";
  const vigente = (vigQ.data?.vigente ?? []) as VigenteNode[];
  const vigenteMap = useMemo(() => {
    const m = new Map<string, VigenteNode>();
    for (const n of vigente) m.set(n.clave, n);
    return m;
  }, [vigente]);
  const hojasVigentes = useMemo(() => vigente.filter((n) => !n.es_grupo), [vigente]);

  const [mods, setMods] = useState<ModRow[]>([]);
  const [adds, setAdds] = useState<AddRow[]>([]);
  const [dels, setDels] = useState<DelRow[]>([]);

  // Cargar renglones existentes de la OC (si la estamos editando)
  useEffect(() => {
    const renglones = presQ.data?.renglones as any[] | undefined;
    if (!renglones || renglones.length === 0) return;
    const m: ModRow[] = [];
    const a: AddRow[] = [];
    const d: DelRow[] = [];
    for (const r of renglones) {
      if (r.tipo_movimiento === "modificacion") {
        m.push({
          _id: nextId(),
          clave: r.clave,
          cantidad: r.cantidad != null ? Number(r.cantidad) : null,
          precio_unitario: r.precio_unitario != null ? Number(r.precio_unitario) : null,
        });
      } else if (r.tipo_movimiento === "adicion") {
        a.push({
          _id: nextId(),
          clave: r.clave,
          concepto: r.concepto,
          unidad: r.unidad ?? "",
          cantidad: r.cantidad != null ? Number(r.cantidad) : null,
          precio_unitario: r.precio_unitario != null ? Number(r.precio_unitario) : null,
        });
      } else if (r.tipo_movimiento === "eliminacion") {
        d.push({ _id: nextId(), clave: r.clave });
      }
    }
    setMods(m);
    setAdds(a);
    setDels(d);
  }, [presQ.data]);

  // ====== C├ílculo en vivo ======
  const input: OCInput[] = useMemo(() => {
    const out: OCInput[] = [];
    for (const r of mods) {
      out.push({
        clave: r.clave.trim(),
        tipo_movimiento: "modificacion",
        cantidad: r.cantidad,
        precio_unitario: r.precio_unitario,
      });
    }
    for (const r of adds) {
      out.push({
        clave: r.clave.trim(),
        tipo_movimiento: "adicion",
        concepto: r.concepto.trim(),
        unidad: r.unidad.trim() || null,
        cantidad: r.cantidad,
        precio_unitario: r.precio_unitario,
      });
    }
    for (const r of dels) {
      out.push({
        clave: r.clave.trim(),
        tipo_movimiento: "eliminacion",
      });
    }
    return out;
  }, [mods, adds, dels]);

  const calc = useMemo(() => procesarOrdenCambio(vigente, input), [vigente, input]);
  const erroresPorClave = useMemo(() => {
    const map = new Map<string, string[]>();
    for (const e of calc.errores) {
      const existing = map.get(e.clave) ?? [];
      map.set(e.clave, [...existing, ...e.errores]);
    }
    return map;
  }, [calc.errores]);
  const deltaPorClave = useMemo(() => {
    const m = new Map<string, number>();
    if (calc.errores.length === 0) {
      for (const r of calc.renglones) m.set(r.clave, r.importe_delta);
    }
    return m;
  }, [calc]);

  // Claves padre dentro de las adiciones (al combinar vigente + adiciones, una adici├│n
  // puede convertirse en partida si otra adici├│n la usa como prefijo).
  const clavesPadreAdds = useMemo(() => calcularClavesPadre(adds.map((r) => r.clave)), [adds]);

  // ====== Mutations ======
  const guardar = useServerFn(guardarRenglonesOC);
  const guardarM = useMutation({
    mutationFn: guardar,
    onSuccess: () => {
      toast.success("Orden de cambio guardada");
      onSaved();
    },
    onError: (e: Error) => toast.error(e.message),
  });
  const solicitar = useServerFn(solicitarAutorizacionPresupuesto);
  const solicitarM = useMutation({
    mutationFn: solicitar,
    onSuccess: () => {
      toast.success("Solicitud enviada al supervisor");
      onSaved();
    },
    onError: (e: Error) => toast.error(e.message),
  });

  // El toast dice qu├® fall├│; la sacudida dice d├│nde. Solo en validaci├│n local.
  const sacudirRef = useRef<HTMLDivElement>(null);
  const sacudir = useSacudir(sacudirRef);

  const handleGuardar = (solicitarDespues: boolean) => {
    if (calc.errores.length > 0) {
      sacudir();
      toast.error("Corrige los errores antes de guardar");
      return;
    }
    if (input.length === 0) {
      toast.error("Agrega al menos un movimiento");
      return;
    }
    guardarM.mutate(
      { data: { presupuestoId, renglones: input } },
      {
        onSuccess: () => {
          if (solicitarDespues) {
            solicitarM.mutate({ data: { id: presupuestoId } });
          }
        },
      },
    );
  };

  // ====== Pickers ======
  const [pickMod, setPickMod] = useState(false);
  const [pickDel, setPickDel] = useState(false);
  const [showVigente, setShowVigente] = useState(false);

  const addMod = (n: VigenteNode) => {
    if (mods.some((m) => m.clave === n.clave)) {
      toast.error(`${n.clave} ya est├í en modificaciones`);
      return;
    }
    setMods((rs) => [
      ...rs,
      {
        _id: nextId(),
        clave: n.clave,
        cantidad: n.cantidad,
        precio_unitario: n.precio_unitario,
      },
    ]);
    setPickMod(false);
  };
  const addDel = (n: VigenteNode) => {
    if (dels.some((d) => d.clave === n.clave)) return;
    setDels((rs) => [...rs, { _id: nextId(), clave: n.clave }]);
  };

  const loading = presQ.isLoading || vigQ.isLoading;
  const tieneBase = vigQ.data?.hasBase;

  return (
    <Sheet open onOpenChange={(o) => !o && onClose()}>
      <SheetContent ref={sacudirRef} side="right" className="w-full sm:max-w-5xl overflow-y-auto">
        <SheetHeader>
          <SheetTitle className="flex items-center gap-2 flex-wrap">
            {presupuesto?.nombre ?? "Orden de cambio"}
            {presupuesto && presupuesto.estatus !== "borrador" && (
              <Badge className="ml-2">
                {presupuesto.estatus === "autorizado"
                  ? "Autorizada"
                  : presupuesto.estatus === "solicitada"
                    ? "Solicitada"
                    : "Rechazada"}
              </Badge>
            )}
          </SheetTitle>
          <SheetDescription>
            Captura las modificaciones, adiciones y eliminaciones sobre el presupuesto vigente. El
            base nunca se modifica.
          </SheetDescription>
        </SheetHeader>

        {loading ? (
          <p className="text-sm text-muted-foreground mt-6">CargandoÔÇª</p>
        ) : !tieneBase ? (
          <Card className="mt-6 border-dashed p-8 text-center text-sm text-muted-foreground">
            No hay presupuesto base autorizado todav├¡a.
          </Card>
        ) : (
          <div className="mt-6 space-y-4">
            {/* Resumen */}
            <div className="flex items-center justify-end gap-2 flex-wrap">
              <Button
                size="sm"
                variant="outline"
                onClick={() => setShowVigente(true)}
                className="mr-auto"
              >
                <Eye className="size-4 mr-1" /> Ver vigente
              </Button>
              {calc.errores.length > 0 ? (
                <Badge variant="destructive" className="gap-1">
                  <AlertCircle className="size-3" />
                  {calc.errores.length} error(es)
                </Badge>
              ) : (
                <Badge
                  variant="secondary"
                  className={`gap-1 ${
                    calc.montoDelta < 0 ? "text-destructive" : "text-foreground"
                  }`}
                >
                  <CheckCircle2 className="size-3" />╬ö {formatMXN(calc.montoDelta)}
                </Badge>
              )}
            </div>

            <Tabs defaultValue="mod">
              <TabsList>
                <TabsTrigger value="mod">Modificar ({mods.length})</TabsTrigger>
                <TabsTrigger value="add">Agregar ({adds.length})</TabsTrigger>
                <TabsTrigger value="del">Eliminar ({dels.length})</TabsTrigger>
              </TabsList>

              {/* ===== MODIFICAR ===== */}
              <TabsContent value="mod" className="mt-4 space-y-3">
                <Button
                  size="sm"
                  variant="outline"
                  onClick={() => setPickMod(true)}
                  disabled={yaAutorizado}
                >
                  <Plus className="size-4 mr-1" /> Seleccionar conceptoÔÇª
                </Button>
                {mods.length === 0 ? (
                  <Card className="border-dashed p-6 text-center text-sm text-muted-foreground">
                    Sin modificaciones.
                  </Card>
                ) : (
                  <Card className="overflow-x-auto">
                    <table className="w-full text-sm">
                      <thead className="bg-muted/50 text-xs uppercase tracking-wider text-muted-foreground">
                        <tr>
                          <th className="text-left p-2 w-24">Clave</th>
                          <th className="text-left p-2">Concepto</th>
                          <th className="text-right p-2 w-24">Cant. actual</th>
                          <th className="text-right p-2 w-24">PU actual</th>
                          <th className="text-right p-2 w-24">Cant. nueva</th>
                          <th className="text-right p-2 w-24">PU nuevo</th>
                          <th className="text-right p-2 w-28">╬ö Importe</th>
                          <th className="w-10"></th>
                        </tr>
                      </thead>
                      <tbody>
                        {mods.map((r) => {
                          const orig = vigenteMap.get(r.clave);
                          const errs = erroresPorClave.get(r.clave) ?? [];
                          const delta = deltaPorClave.get(r.clave) ?? 0;
                          return (
                            <tr
                              key={r._id}
                              className={`border-t border-border ${
                                errs.length ? "bg-destructive/5" : ""
                              }`}
                            >
                              <td className="p-2 tabular-nums">{r.clave}</td>
                              <td className="p-2">
                                {orig?.concepto ?? "ÔÇö"}
                                {errs.length > 0 && (
                                  <p className="text-xs text-destructive mt-1">
                                    {errs.join(" ┬À ")}
                                  </p>
                                )}
                              </td>
                              <td className="p-2 text-right tabular-nums text-muted-foreground">
                                {orig?.cantidad ?? "ÔÇö"}
                              </td>
                              <td className="p-2 text-right tabular-nums text-muted-foreground">
                                {orig?.precio_unitario != null
                                  ? formatMXN(Number(orig.precio_unitario))
                                  : "ÔÇö"}
                              </td>
                              <td className="p-1">
                                <Input
                                  type="number"
                                  value={r.cantidad ?? ""}
                                  onChange={(e) =>
                                    setMods((rs) =>
                                      rs.map((x) =>
                                        x._id === r._id
                                          ? {
                                              ...x,
                                              cantidad:
                                                e.target.value === ""
                                                  ? null
                                                  : Number(e.target.value),
                                            }
                                          : x,
                                      ),
                                    )
                                  }
                                  className="h-8 text-right"
                                />
                              </td>
                              <td className="p-1">
                                <Input
                                  type="number"
                                  value={r.precio_unitario ?? ""}
                                  onChange={(e) =>
                                    setMods((rs) =>
                                      rs.map((x) =>
                                        x._id === r._id
                                          ? {
                                              ...x,
                                              precio_unitario:
                                                e.target.value === ""
                                                  ? null
                                                  : Number(e.target.value),
                                            }
                                          : x,
                                      ),
                                    )
                                  }
                                  className="h-8 text-right"
                                />
                              </td>
                              <td
                                className={`p-2 text-right tabular-nums ${
                                  delta < 0
                                    ? "text-destructive"
                                    : delta > 0
                                      ? "text-foreground"
                                      : ""
                                }`}
                              >
                                {formatMXN(delta)}
                              </td>
                              <td className="p-1 text-right">
                                <Button
                                  size="icon"
                                  variant="ghost"
                                  className="h-8 w-8"
                                  aria-label="Quitar rengl├│n"
                                  onClick={() => setMods((rs) => rs.filter((x) => x._id !== r._id))}
                                >
                                  <Trash2 className="size-3.5" />
                                </Button>
                              </td>
                            </tr>
                          );
                        })}
                      </tbody>
                    </table>
                  </Card>
                )}
              </TabsContent>

              {/* ===== AGREGAR ===== */}
              <TabsContent value="add" className="mt-4 space-y-3">
                <Button
                  size="sm"
                  variant="ghost"
                  disabled={yaAutorizado}
                  onClick={() =>
                    setAdds((rs) => [
                      ...rs,
                      {
                        _id: nextId(),
                        clave: "",
                        concepto: "",
                        unidad: "",
                        cantidad: null,
                        precio_unitario: null,
                      },
                    ])
                  }
                >
                  <Plus className="size-4 mr-1" /> Agregar rengl├│n
                </Button>
                {adds.length === 0 ? (
                  <Card className="border-dashed p-6 text-center text-sm text-muted-foreground">
                    Sin adiciones.
                  </Card>
                ) : (
                  <Card className="overflow-x-auto">
                    <table className="w-full text-sm">
                      <thead className="bg-muted/50 text-xs uppercase tracking-wider text-muted-foreground">
                        <tr>
                          <th className="text-left p-2 w-24">Clave</th>
                          <th className="text-left p-2">Concepto</th>
                          <th className="text-left p-2 w-20">Unidad</th>
                          <th className="text-right p-2 w-24">Cantidad</th>
                          <th className="text-right p-2 w-24">PU</th>
                          <th className="text-right p-2 w-28">╬ö Importe</th>
                          <th className="w-10"></th>
                        </tr>
                      </thead>
                      <tbody>
                        {adds.map((r) => {
                          const claveTrim = r.clave.trim();
                          const errs = erroresPorClave.get(claveTrim) ?? [];
                          const delta = deltaPorClave.get(claveTrim) ?? 0;
                          const esPadre = claveTrim !== "" && clavesPadreAdds.has(claveTrim);
                          return (
                            <tr
                              key={r._id}
                              className={`border-t border-border ${
                                errs.length
                                  ? "bg-destructive/5"
                                  : esPadre
                                    ? "bg-accent/40 font-medium"
                                    : ""
                              }`}
                            >
                              <td className="p-1">
                                <Input
                                  value={r.clave}
                                  placeholder="3.1"
                                  className="h-8"
                                  onChange={(e) =>
                                    setAdds((rs) =>
                                      rs.map((x) =>
                                        x._id === r._id ? { ...x, clave: e.target.value } : x,
                                      ),
                                    )
                                  }
                                />
                              </td>
                              <td className="p-1">
                                <Input
                                  value={r.concepto}
                                  placeholder="Concepto"
                                  className="h-8"
                                  onChange={(e) =>
                                    setAdds((rs) =>
                                      rs.map((x) =>
                                        x._id === r._id ? { ...x, concepto: e.target.value } : x,
                                      ),
                                    )
                                  }
                                />
                                {errs.length > 0 && (
                                  <p className="text-xs text-destructive mt-1">
                                    {errs.join(" ┬À ")}
                                  </p>
                                )}
                              </td>
                              {esPadre ? (
                                <>
                                  <td className="p-2 text-center text-muted-foreground">ÔÇö</td>
                                  <td className="p-2 text-center text-muted-foreground">ÔÇö</td>
                                  <td className="p-2 text-center text-muted-foreground">ÔÇö</td>
                                </>
                              ) : (
                                <>
                                  <td className="p-1">
                                    <Input
                                      value={r.unidad}
                                      placeholder="m2"
                                      className="h-8"
                                      onChange={(e) =>
                                        setAdds((rs) =>
                                          rs.map((x) =>
                                            x._id === r._id ? { ...x, unidad: e.target.value } : x,
                                          ),
                                        )
                                      }
                                    />
                                  </td>
                                  <td className="p-1">
                                    <Input
                                      type="number"
                                      value={r.cantidad ?? ""}
                                      className="h-8 text-right"
                                      onChange={(e) =>
                                        setAdds((rs) =>
                                          rs.map((x) =>
                                            x._id === r._id
                                              ? {
                                                  ...x,
                                                  cantidad:
                                                    e.target.value === ""
                                                      ? null
                                                      : Number(e.target.value),
                                                }
                                              : x,
                                          ),
                                        )
                                      }
                                    />
                                  </td>
                                  <td className="p-1">
                                    <Input
                                      type="number"
                                      value={r.precio_unitario ?? ""}
                                      className="h-8 text-right"
                                      onChange={(e) =>
                                        setAdds((rs) =>
                                          rs.map((x) =>
                                            x._id === r._id
                                              ? {
                                                  ...x,
                                                  precio_unitario:
                                                    e.target.value === ""
                                                      ? null
                                                      : Number(e.target.value),
                                                }
                                              : x,
                                          ),
                                        )
                                      }
                                    />
                                  </td>
                                </>
                              )}
                              <td className="p-2 text-right tabular-nums">{formatMXN(delta)}</td>
                              <td className="p-1 text-right">
                                <Button
                                  size="icon"
                                  variant="ghost"
                                  className="h-8 w-8"
                                  aria-label="Quitar rengl├│n"
                                  onClick={() => setAdds((rs) => rs.filter((x) => x._id !== r._id))}
                                >
                                  <Trash2 className="size-3.5" />
                                </Button>
                              </td>
                            </tr>
                          );
                        })}
                      </tbody>
                    </table>
                  </Card>
                )}
              </TabsContent>

              {/* ===== ELIMINAR ===== */}
              <TabsContent value="del" className="mt-4 space-y-3">
                <Button
                  size="sm"
                  variant="outline"
                  onClick={() => setPickDel(true)}
                  disabled={yaAutorizado}
                >
                  <Plus className="size-4 mr-1" /> Seleccionar conceptosÔÇª
                </Button>
                {dels.length === 0 ? (
                  <Card className="border-dashed p-6 text-center text-sm text-muted-foreground">
                    Sin eliminaciones.
                  </Card>
                ) : (
                  <Card className="overflow-x-auto">
                    <table className="w-full text-sm">
                      <thead className="bg-muted/50 text-xs uppercase tracking-wider text-muted-foreground">
                        <tr>
                          <th className="text-left p-2 w-24">Clave</th>
                          <th className="text-left p-2">Concepto</th>
                          <th className="text-right p-2 w-32">Importe a restar</th>
                          <th className="w-10"></th>
                        </tr>
                      </thead>
                      <tbody>
                        {dels.map((r) => {
                          const orig = vigenteMap.get(r.clave);
                          const delta = deltaPorClave.get(r.clave) ?? 0;
                          const errs = erroresPorClave.get(r.clave) ?? [];
                          return (
                            <tr
                              key={r._id}
                              className={`border-t border-border ${
                                errs.length ? "bg-destructive/5" : ""
                              }`}
                            >
                              <td className="p-2 tabular-nums">{r.clave}</td>
                              <td className="p-2">
                                {orig?.concepto ?? "ÔÇö"}
                                {errs.length > 0 && (
                                  <p className="text-xs text-destructive mt-1">
                                    {errs.join(" ┬À ")}
                                  </p>
                                )}
                              </td>
                              <td className="p-2 text-right tabular-nums text-destructive">
                                {formatMXN(delta)}
                              </td>
                              <td className="p-1 text-right">
                                <Button
                                  size="icon"
                                  variant="ghost"
                                  className="h-8 w-8"
                                  aria-label="Quitar rengl├│n"
                                  onClick={() => setDels((rs) => rs.filter((x) => x._id !== r._id))}
                                >
                                  <Trash2 className="size-3.5" />
                                </Button>
                              </td>
                            </tr>
                          );
                        })}
                      </tbody>
                    </table>
                  </Card>
                )}
              </TabsContent>
            </Tabs>

            <div className="flex items-center justify-end gap-2 sticky bottom-0 bg-background py-3 border-t">
              <Button variant="outline" onClick={onClose}>
                Cerrar
              </Button>
              <Button
                disabled={guardarM.isPending || calc.errores.length > 0 || yaAutorizado}
                onClick={() => handleGuardar(false)}
              >
                {guardarM.isPending ? "GuardandoÔÇª" : "Guardar borrador"}
              </Button>
              <Button
                disabled={
                  guardarM.isPending ||
                  solicitarM.isPending ||
                  calc.errores.length > 0 ||
                  yaAutorizado ||
                  input.length === 0
                }
                onClick={() => handleGuardar(true)}
              >
                Guardar y solicitar autorizaci├│n
              </Button>
            </div>
          </div>
        )}

        {/* Picker de modificaci├│n */}
        {pickMod && (
          <ConceptoPicker
            hojas={hojasVigentes}
            excluir={new Set(mods.map((m) => m.clave))}
            onClose={() => setPickMod(false)}
            onSelect={addMod}
            title="Selecciona un concepto a modificar"
          />
        )}
        {/* Picker de eliminaci├│n (multi) */}
        {pickDel && (
          <ConceptoPicker
            hojas={hojasVigentes}
            excluir={new Set(dels.map((d) => d.clave))}
            onClose={() => setPickDel(false)}
            onSelect={(n) => {
              addDel(n);
            }}
            title="Selecciona conceptos a eliminar"
            multi
          />
        )}
        <VigenteViewerDialog
          open={showVigente}
          onClose={() => setShowVigente(false)}
          vigente={vigente as any[]}
          total={vigQ.data?.montoTotal}
        />
      </SheetContent>
    </Sheet>
  );
}

function ConceptoPicker({
  hojas,
  excluir,
  onClose,
  onSelect,
  title,
  multi,
}: {
  hojas: VigenteNode[];
  excluir: Set<string>;
  onClose: () => void;
  onSelect: (n: VigenteNode) => void;
  title: string;
  multi?: boolean;
}) {
  const [q, setQ] = useState("");
  const filtradas = useMemo(() => {
    const term = q.trim().toLowerCase();
    return hojas.filter(
      (h) =>
        !excluir.has(h.clave) &&
        (!term || h.clave.toLowerCase().includes(term) || h.concepto.toLowerCase().includes(term)),
    );
  }, [hojas, excluir, q]);

  return (
    <Sheet open onOpenChange={(o) => !o && onClose()}>
      <SheetContent side="right" className="w-full sm:max-w-md overflow-y-auto">
        <SheetHeader>
          <SheetTitle>{title}</SheetTitle>
        </SheetHeader>
        <div className="mt-4 space-y-3">
          <div className="relative">
            <Search className="size-4 absolute left-2 top-2.5 text-muted-foreground" />
            <Input
              autoFocus
              value={q}
              onChange={(e) => setQ(e.target.value)}
              placeholder="Buscar por clave o conceptoÔÇª"
              className="pl-8"
            />
          </div>
          {filtradas.length === 0 ? (
            <p className="text-sm text-muted-foreground p-4 text-center">Sin resultados.</p>
          ) : (
            <TooltipProvider delayDuration={200}>
              <ul className="divide-y border rounded-md">
                {filtradas.map((h) => (
                  <li key={h.clave}>
                    <button
                      className="w-full text-left p-2 hover:bg-muted/50 text-sm flex items-center gap-2"
                      onClick={() => onSelect(h)}
                    >
                      <span className="font-mono text-xs text-muted-foreground w-16">
                        {h.clave}
                      </span>
                      <Tooltip>
                        <TooltipTrigger asChild>
                          <span className="flex-1 truncate cursor-default">{h.concepto}</span>
                        </TooltipTrigger>
                        <TooltipContent
                          side="top"
                          align="start"
                          className="max-w-md whitespace-normal"
                        >
                          {h.concepto}
                        </TooltipContent>
                      </Tooltip>
                      <span className="text-xs text-muted-foreground">
                        {formatMXN(Number(h.importe))}
                      </span>
                    </button>
                  </li>
                ))}
              </ul>
            </TooltipProvider>
          )}
          {multi && (
            <div className="flex justify-end">
              <Button variant="outline" onClick={onClose}>
                Listo
              </Button>
            </div>
          )}
        </div>
      </SheetContent>
    </Sheet>
  );
}

"use client";

import { useServerFn } from "@/lib/server-fn/client";
import { useQuery } from "@tanstack/react-query";
import { getPresupuesto } from "@/lib/api-client/presupuestos.functions";
import { Sheet, SheetContent, SheetHeader, SheetTitle } from "@/components/ui/sheet";
import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip";
import { formatMXN } from "@/lib/format";

type Renglon = {
  id: string;
  clave: string;
  nivel: number;
  parent_clave: string | null;
  concepto: string;
  unidad: string | null;
  cantidad: number | null;
  precio_unitario: number | null;
  importe: number;
  importe_delta?: number | null;
  tipo_movimiento?: "renglon" | "modificacion" | "adicion" | "eliminacion" | null;
  es_grupo: boolean;
};

const MOV_LABEL: Record<
  string,
  { label: string; variant: "default" | "secondary" | "destructive" }
> = {
  modificacion: { label: "Modif.", variant: "secondary" },
  adicion: { label: "Adici├│n", variant: "default" },
  eliminacion: { label: "Elim.", variant: "destructive" },
};

export function VerPresupuestoSheet({
  presupuestoId,
  onClose,
}: {
  presupuestoId: string;
  onClose: () => void;
}) {
  const fetchOne = useServerFn(getPresupuesto);
  const { data, isLoading } = useQuery({
    queryKey: ["presupuesto", presupuestoId],
    queryFn: () => fetchOne({ data: { id: presupuestoId } }),
  });

  const presupuesto = data?.presupuesto;
  const renglones = (data?.renglones ?? []) as Renglon[];
  const esOC = presupuesto?.tipo === "adenda";

  return (
    <Sheet open onOpenChange={(o) => !o && onClose()}>
      <SheetContent side="right" className="w-full sm:max-w-5xl overflow-y-auto">
        <SheetHeader>
          <SheetTitle className="flex items-center gap-2 flex-wrap pr-10">
            {presupuesto?.nombre ?? "Presupuesto"}
            {presupuesto &&
              (() => {
                const e = presupuesto.estatus as
                  "borrador" | "solicitada" | "autorizado" | "rechazada";
                const label =
                  e === "autorizado"
                    ? "Autorizado"
                    : e === "solicitada"
                      ? "Solicitada"
                      : e === "rechazada"
                        ? "Rechazada"
                        : "Borrador";
                const variant =
                  e === "autorizado"
                    ? "default"
                    : e === "rechazada"
                      ? "destructive"
                      : e === "solicitada"
                        ? "outline"
                        : "secondary";
                return <Badge variant={variant as any}>{label}</Badge>;
              })()}
            <span className="ml-auto text-base font-semibold">
              {presupuesto &&
                (esOC
                  ? `╬ö ${formatMXN(presupuesto.monto_total)}`
                  : formatMXN(presupuesto.monto_total))}
            </span>
          </SheetTitle>
        </SheetHeader>

        <div className="mt-6">
          {isLoading ? (
            <p className="text-sm text-muted-foreground">CargandoÔÇª</p>
          ) : renglones.length === 0 ? (
            <p className="text-sm text-muted-foreground">Sin renglones.</p>
          ) : (
            <TooltipProvider delayDuration={200}>
              <Card className="overflow-x-auto">
                <table className="w-full min-w-[640px] text-xs table-fixed">
                  <colgroup>
                    <col className="w-28" />
                    <col />
                    <col className="w-16" />
                    <col className="w-20" />
                    <col className="w-24" />
                    <col className="w-28" />
                  </colgroup>
                  <thead className="bg-muted/50 text-[11px] uppercase tracking-wider text-muted-foreground">
                    <tr>
                      <th className="text-left px-2 py-1.5">Clave</th>
                      <th className="text-left px-2 py-1.5">Concepto</th>
                      <th className="text-left px-2 py-1.5">Unidad</th>
                      <th className="text-right px-2 py-1.5">Cantidad</th>
                      <th className="text-right px-2 py-1.5">PU</th>
                      <th className="text-right px-2 py-1.5">{esOC ? "╬ö Importe" : "Importe"}</th>
                    </tr>
                  </thead>
                  <tbody>
                    {renglones.map((r) => {
                      const mov = r.tipo_movimiento && MOV_LABEL[r.tipo_movimiento];
                      const valor = esOC ? Number(r.importe_delta ?? 0) : Number(r.importe);
                      return (
                        <tr
                          key={r.id}
                          className={`border-t border-border ${r.es_grupo ? "bg-muted/30 font-medium" : ""}`}
                        >
                          <td
                            className="px-2 py-1 tabular-nums whitespace-nowrap overflow-hidden text-ellipsis"
                            style={{ paddingLeft: `${0.5 + (r.nivel - 1) * 1}rem` }}
                          >
                            <div className="flex items-center gap-1.5">
                              <span className="truncate">{r.clave}</span>
                              {mov && (
                                <Badge
                                  variant={mov.variant}
                                  className="text-xs h-4 px-1 shrink-0"
                                >
                                  {mov.label}
                                </Badge>
                              )}
                            </div>
                          </td>
                          <td className="px-2 py-1 max-w-0">
                            <Tooltip>
                              <TooltipTrigger asChild>
                                <div className="truncate whitespace-nowrap overflow-hidden text-ellipsis cursor-default">
                                  {r.concepto}
                                </div>
                              </TooltipTrigger>
                              <TooltipContent
                                side="top"
                                align="start"
                                className="max-w-md whitespace-normal"
                              >
                                {r.concepto}
                              </TooltipContent>
                            </Tooltip>
                          </td>
                          <td className="px-2 py-1 text-muted-foreground whitespace-nowrap overflow-hidden text-ellipsis">
                            {r.unidad ?? "ÔÇö"}
                          </td>
                          <td className="px-2 py-1 text-right tabular-nums whitespace-nowrap">
                            {r.cantidad != null ? Number(r.cantidad).toLocaleString("es-MX") : "ÔÇö"}
                          </td>
                          <td className="px-2 py-1 text-right tabular-nums whitespace-nowrap">
                            {r.precio_unitario != null ? formatMXN(Number(r.precio_unitario)) : "ÔÇö"}
                          </td>
                          <td
                            className={`px-2 py-1 text-right tabular-nums whitespace-nowrap ${
                              esOC && valor < 0 ? "text-destructive" : ""
                            }`}
                          >
                            {formatMXN(valor)}
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </Card>
            </TooltipProvider>
          )}
        </div>
      </SheetContent>
    </Sheet>
  );
}

"use client";

import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip";
import { formatMXN } from "@/lib/format";

export type VigenteRow = {
  clave: string;
  concepto?: string | null;
  unidad?: string | null;
  cantidad?: number | null;
  precio_unitario?: number | null;
  importe?: number | null;
  nivel?: number;
  es_grupo?: boolean;
  origen?: "base" | "modificada" | "agregada" | "eliminada" | string;
  cantidad_base?: number | null;
  pu_base?: number | null;
  cantidad_modificada?: boolean;
  pu_modificado?: boolean;
};

const fmtNum = (v: number | null | undefined) =>
  v != null ? Number(v).toLocaleString("es-MX") : "ÔÇö";

export function VigenteTable({ rows }: { rows: VigenteRow[] }) {
  if (rows.length === 0) {
    return <p className="text-sm text-muted-foreground">Sin renglones.</p>;
  }

  return (
    <TooltipProvider delayDuration={200}>
      <Card className="overflow-x-auto">
        <table className="w-full min-w-[640px] text-xs table-fixed">
          <colgroup>
            <col className="w-28" />
            <col />
            <col className="w-16" />
            <col className="w-20" />
            <col className="w-24" />
            <col className="w-28" />
          </colgroup>
          <thead className="bg-muted/50 text-[11px] uppercase tracking-wider text-muted-foreground">
            <tr>
              <th className="text-left px-2 py-1.5">Clave</th>
              <th className="text-left px-2 py-1.5">Concepto</th>
              <th className="text-left px-2 py-1.5">Unidad</th>
              <th className="text-right px-2 py-1.5">Cantidad</th>
              <th className="text-right px-2 py-1.5">PU</th>
              <th className="text-right px-2 py-1.5">Importe</th>
            </tr>
          </thead>
          <tbody>
            {rows.map((r) => {
              const eliminada = r.origen === "eliminada";
              const modCant = r.cantidad_modificada && !eliminada;
              const modPU = r.pu_modificado && !eliminada;
              const rowClass = eliminada
                ? "bg-muted/30 text-muted-foreground/70"
                : r.es_grupo
                  ? "bg-muted/30 font-medium"
                  : "";
              const highlightClass =
                "bg-amber-100 dark:bg-amber-950/40 text-amber-900 dark:text-amber-200 font-medium rounded-sm";
              return (
                <tr key={r.clave} className={`border-t border-border ${rowClass}`}>
                  <td
                    className="px-2 py-1 tabular-nums whitespace-nowrap overflow-hidden text-ellipsis"
                    style={{
                      paddingLeft: `${0.5 + ((r.nivel ?? 1) - 1) * 1}rem`,
                    }}
                  >
                    <div className="flex items-center gap-1.5">
                      <span className="truncate">{r.clave}</span>
                      {r.origen === "modificada" && (
                        <Badge variant="secondary" className="text-xs h-4 px-1 shrink-0">
                          Mod
                        </Badge>
                      )}
                      {r.origen === "agregada" && (
                        <Badge className="text-xs h-4 px-1 shrink-0">Nuevo</Badge>
                      )}
                      {eliminada && (
                        <Badge
                          variant="outline"
                          className="text-xs h-4 px-1 shrink-0 text-muted-foreground"
                        >
                          Eliminado
                        </Badge>
                      )}
                    </div>
                  </td>
                  <td className="px-2 py-1 max-w-0">
                    <Tooltip>
                      <TooltipTrigger asChild>
                        <div
                          className={`truncate whitespace-nowrap overflow-hidden text-ellipsis cursor-default ${eliminada ? "line-through" : ""}`}
                        >
                          {r.concepto}
                        </div>
                      </TooltipTrigger>
                      <TooltipContent
                        side="top"
                        align="start"
                        className="max-w-md whitespace-normal"
                      >
                        {r.concepto}
                      </TooltipContent>
                    </Tooltip>
                  </td>
                  <td className="px-2 py-1 text-muted-foreground whitespace-nowrap overflow-hidden text-ellipsis">
                    {r.unidad ?? "ÔÇö"}
                  </td>
                  <td className="px-2 py-1 text-right tabular-nums whitespace-nowrap">
                    {eliminada ? (
                      <span>0</span>
                    ) : modCant ? (
                      <Tooltip>
                        <TooltipTrigger asChild>
                          <span className={`inline-block px-1.5 ${highlightClass}`}>
                            {fmtNum(r.cantidad)}
                          </span>
                        </TooltipTrigger>
                        <TooltipContent side="top">Antes: {fmtNum(r.cantidad_base)}</TooltipContent>
                      </Tooltip>
                    ) : (
                      fmtNum(r.cantidad)
                    )}
                  </td>
                  <td className="px-2 py-1 text-right tabular-nums whitespace-nowrap">
                    {eliminada ? (
                      r.precio_unitario != null ? (
                        formatMXN(Number(r.precio_unitario))
                      ) : (
                        "ÔÇö"
                      )
                    ) : modPU ? (
                      <Tooltip>
                        <TooltipTrigger asChild>
                          <span className={`inline-block px-1.5 ${highlightClass}`}>
                            {r.precio_unitario != null ? formatMXN(Number(r.precio_unitario)) : "ÔÇö"}
                          </span>
                        </TooltipTrigger>
                        <TooltipContent side="top">
                          Antes: {r.pu_base != null ? formatMXN(Number(r.pu_base)) : "ÔÇö"}
                        </TooltipContent>
                      </Tooltip>
                    ) : r.precio_unitario != null ? (
                      formatMXN(Number(r.precio_unitario))
                    ) : (
                      "ÔÇö"
                    )}
                  </td>
                  <td className="px-2 py-1 text-right tabular-nums whitespace-nowrap">
                    {eliminada
                      ? formatMXN(0)
                      : r.importe != null
                        ? formatMXN(Number(r.importe))
                        : "ÔÇö"}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </Card>
    </TooltipProvider>
  );
}

