  DialogDescription,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Card } from "@/components/ui/card";
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { formatDate } from "@/lib/format";
import {
  getCotizacionRequisicion,
  listProveedores,
  enviarOCASupervisor,
  reabrirOC,
  enviarOCAProveedor,
} from "@/lib/api-client/cotizaciones.functions";
import { listPagosOC, cancelarPagoOC } from "@/lib/api-client/pagos.functions";
import { RegistrarPagoOCDialog } from "@/components/pagos/RegistrarPagoOCDialog";
import { RecepcionDialog } from "@/components/almacen/RecepcionDialog";

import { getSolicitudesRequisicion } from "@/lib/api-client/solicitudes-cotizacion.functions";
import { SolicitudesTab } from "./SolicitudesTab";
import { ComparativaTable } from "./ComparativaTable";
import { RecepcionesTab } from "./RecepcionesTab";
import { useEffectiveRoles } from "@/stores/auth";
import { usePermisos } from "@/hooks/usePermisos";

export type CotizacionTab = "requisicion" | "solicitudes" | "comparativa" | "ocs" | "recepciones";

interface Props {
  requisicionId: string;
  open: boolean;
  onOpenChange: (o: boolean) => void;
  initialTab?: CotizacionTab;
  readOnly?: boolean;
}

const OC_BADGE: Record<string, { label: string; className: string }> = {
  borrador: { label: "Borrador", className: "bg-slate-100 text-slate-700" },
  pendiente_autorizacion: {
    label: "Pendiente autorizaci├│n",
    className: "bg-amber-100 text-amber-800",
  },
  autorizada: { label: "Autorizada", className: "bg-emerald-100 text-emerald-800" },
  enviada: { label: "Enviada al proveedor", className: "bg-blue-100 text-blue-800" },
  recibida_parcial: { label: "Recibida parcial", className: "bg-cyan-100 text-cyan-800" },
  recibida: { label: "Recibida", className: "bg-teal-100 text-teal-800" },
  rechazada: { label: "Rechazada", className: "bg-rose-100 text-rose-800" },
  pagada: { label: "Pagada", className: "bg-violet-100 text-violet-800" },
};

const REQ_BADGE: Record<string, { label: string; className: string }> = {
  borrador: { label: "Borrador", className: "bg-slate-100 text-slate-700" },
  enviada: { label: "Enviada", className: "bg-blue-100 text-blue-800" },
  en_cotizacion: { label: "En cotizaci├│n", className: "bg-amber-100 text-amber-800" },
  cotizada: { label: "Cotizada", className: "bg-indigo-100 text-indigo-800" },
  autorizada: { label: "Autorizada", className: "bg-emerald-100 text-emerald-800" },
  oc_generada: { label: "OC generada", className: "bg-emerald-100 text-emerald-800" },
  completada: { label: "Completada", className: "bg-emerald-100 text-emerald-800" },
  rechazada: { label: "Rechazada", className: "bg-rose-100 text-rose-800" },
};

const mxn = (n: number) => n.toLocaleString("es-MX", { style: "currency", currency: "MXN" });

export function CotizacionSheet({
  requisicionId,
  open,
  onOpenChange,
  initialTab = "requisicion",
  readOnly = false,
}: Props) {
  const qc = useQueryClient();
  const fetchCot = useServerFn(getCotizacionRequisicion);
  const fetchProv = useServerFn(listProveedores);
  const fetchSols = useServerFn(getSolicitudesRequisicion);
  const enviarFn = useServerFn(enviarOCASupervisor);
  const reabrirFn = useServerFn(reabrirOC);
  const enviarProvFn = useServerFn(enviarOCAProveedor);

  const roles = useEffectiveRoles();

  const [tab, setTab] = useState<CotizacionTab>(initialTab);

  const cotQ = useQuery({
    queryKey: ["cotizacion", requisicionId],
    queryFn: () => fetchCot({ data: { requisicionId } }),
    enabled: open,
  });
  const provQ = useQuery({
    queryKey: ["proveedores-list"],
    queryFn: () => fetchProv(),
    enabled: open,
  });
  const solsQ = useQuery({
    queryKey: ["solicitudes", requisicionId],
    queryFn: () => fetchSols({ data: { requisicionId } }),
    enabled: open,
  });

  const invalidate = () => {
    qc.invalidateQueries({ queryKey: ["cotizacion", requisicionId] });
    qc.invalidateQueries({ queryKey: ["requisiciones"] });
  };

  const enviarMut = useMutation({
    mutationFn: (ocId: string) => enviarFn({ data: { ocId } }),
    onSuccess: () => {
      toast.success("OC enviada al supervisor");
      invalidate();
    },
    onError: (e: any) => toast.error(e?.message ?? "Error"),
  });

  const reabrirMut = useMutation({
    mutationFn: (ocId: string) => reabrirFn({ data: { ocId } }),
    onSuccess: () => {
      toast.success("OC reabierta");
      invalidate();
    },
    onError: (e: any) => toast.error(e?.message ?? "Error"),
  });

  const enviarProvMut = useMutation({
    mutationFn: (ocId: string) => enviarProvFn({ data: { ocId } }),
    onSuccess: () => {
      toast.success("OC marcada como enviada al proveedor");
      invalidate();
    },
    onError: (e: any) => toast.error(e?.message ?? "Error"),
  });

  const { can } = usePermisos();
  const puedeGestionar = !readOnly && can("cotizaciones.gestionar");
  const puedeCrearOC = !readOnly && can("oc.crear");
  const puedeCancelarOC = !readOnly && can("oc.cancelar");
  const isAdmin = puedeGestionar || puedeCrearOC;
  void isAdmin;
  void roles;

  if (!open) return null;

  const req = (cotQ.data as any)?.requisicion;
  const reqItems: any[] = req?.items ?? [];
  const paquetes: any[] = (cotQ.data as any)?.paquetes ?? [];
  const ocs: any[] = (cotQ.data as any)?.ocs ?? [];
  const proveedores: any[] = provQ.data ?? [];

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="flex h-[calc(100dvh-1rem)] w-[calc(100%-1rem)] max-w-6xl flex-col gap-0 overflow-hidden p-0 sm:h-[min(90dvh,900px)] sm:w-[calc(100%-3rem)]">
        <DialogHeader className="shrink-0 border-b px-5 py-4 text-left sm:px-6">
          <DialogTitle>Cotizaci├│n ┬À {req?.folio ?? "ÔÇö"}</DialogTitle>
          <DialogDescription>
            Compara precios, asigna proveedores y autoriza pedidos
          </DialogDescription>
        </DialogHeader>

        <div className="min-h-0 flex-1 overflow-y-auto px-4 py-4 sm:px-6">
          {cotQ.isLoading ? (
            <p className="text-sm text-muted-foreground">CargandoÔÇª</p>
          ) : (
          <Tabs value={tab} onValueChange={(v) => setTab(v as CotizacionTab)}>
            <TabsList className="flex h-auto w-full justify-start overflow-x-auto">
              <TabsTrigger className="shrink-0" value="requisicion">Requisici├│n</TabsTrigger>
              <TabsTrigger className="shrink-0" value="solicitudes">
                Cotizaciones ({(solsQ.data ?? []).length})
              </TabsTrigger>
              <TabsTrigger className="shrink-0" value="comparativa">Comparativa</TabsTrigger>
              <TabsTrigger className="shrink-0" value="ocs">OCs ({ocs.length})</TabsTrigger>
              <TabsTrigger className="shrink-0" value="recepciones">Recepciones</TabsTrigger>
            </TabsList>

            <TabsContent value="requisicion" className="mt-4 space-y-4">
              <Card className="p-4 space-y-2">
                <div className="flex items-center justify-between gap-2 flex-wrap">
                  <div>
                    <p className="font-semibold">{req?.folio ?? "ÔÇö"}</p>
                    <p className="text-xs text-muted-foreground">
                      Solicitante: {req?.solicitante ?? "ÔÇö"}
                    </p>
                  </div>
                  {req?.estatus && (
                    <Badge
                      className={REQ_BADGE[req.estatus]?.className ?? "bg-slate-100 text-slate-700"}
                    >
                      {REQ_BADGE[req.estatus]?.label ?? req.estatus}
                    </Badge>
                  )}
                </div>
                <div className="grid grid-cols-2 gap-2 text-xs text-muted-foreground">
                  <p>Creada: {req?.created_at ? formatDate(req.created_at) : "ÔÇö"}</p>
                  <p>Enviada: {req?.enviada_at ? formatDate(req.enviada_at) : "ÔÇö"}</p>
                </div>
                {req?.notas && (
                  <p className="text-sm bg-muted/40 p-2 rounded-md">
                    <strong>Notas:</strong> {req.notas}
                  </p>
                )}
              </Card>

              <div className="border rounded-md overflow-x-auto">
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>Insumo</TableHead>
                      <TableHead className="text-right">Cantidad</TableHead>
                      <TableHead>Fecha requerida</TableHead>
                      <TableHead>Nota</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {reqItems.length === 0 && (
                      <TableRow>
                        <TableCell
                          colSpan={4}
                          className="text-center text-sm text-muted-foreground"
                        >
                          Sin insumos
                        </TableCell>
                      </TableRow>
                    )}
                    {reqItems.map((it: any) => (
                      <TableRow key={it.id}>
                        <TableCell>{it.insumo?.nombre}</TableCell>
                        <TableCell className="text-right">
                          {Number(it.cantidad)} {it.insumo?.unidad}
                        </TableCell>
                        <TableCell>
                          {it.fecha_requerida ? formatDate(it.fecha_requerida) : "ÔÇö"}
                        </TableCell>
                        <TableCell className="text-muted-foreground">{it.nota ?? "ÔÇö"}</TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </div>
            </TabsContent>

            <TabsContent value="solicitudes" className="mt-4">
              <SolicitudesTab
                requisicionId={requisicionId}
                reqItems={reqItems}
                proveedores={proveedores}
                solicitudes={solsQ.data ?? []}
                bloqueadoPorOC={ocs.some((o: any) => o.estatus !== "rechazada")}
                readOnly={readOnly}
              />
            </TabsContent>

            <TabsContent
              value="comparativa"
              forceMount
              className="mt-4 data-[state=inactive]:hidden"
            >
              <ComparativaTable
                reqItems={reqItems}
                solicitudes={solsQ.data ?? []}
                paquetes={paquetes}
                ocs={ocs}
                requisicionId={requisicionId}
                roles={roles}
                readOnly={readOnly}
              />
            </TabsContent>

            <TabsContent value="ocs" className="space-y-3 mt-4">
              {ocs.length === 0 && (
                <Card className="p-8 text-center border-dashed">
                  <FileText className="size-8 mx-auto text-muted-foreground" />
                  <p className="mt-2 text-sm text-muted-foreground">A├║n no hay ├│rdenes de compra</p>
                  <p className="text-xs text-muted-foreground mt-1">
                    Asigna proveedores en Comparativa y env├¡alos a autorizaci├│n.
                  </p>
                </Card>
              )}
              {ocs.map((oc) => {
                const items = oc.paquete?.items ?? [];
                const total = Number(oc.total);
                const pagado = Number(oc.monto_pagado ?? 0);
                const saldoPendiente = +(total - pagado).toFixed(2);
                const estadoPagoRaw: "pendiente" | "parcial" | "pagado" =
                  oc.estado_pago ?? "pendiente";
                const fullyPaid =
                  estadoPagoRaw === "pagado" || (pagado > 0 && pagado + 0.01 >= total);
                const estadoPago: "pendiente" | "parcial" | "pagado" = fullyPaid
                  ? "pagado"
                  : estadoPagoRaw;
                const recibidoMap: Record<string, number> = oc.recibido_por_insumo ?? {};
                const recepcionCompleta: boolean = !!oc.recepcion_completa;
                const cerrada = recepcionCompleta && estadoPago === "pagado";
                const meta = OC_BADGE[oc.estatus];
                const puedePagar =
                  can("cxp.registrar_pago") &&
                  (oc.estatus === "autorizada" ||
                    oc.estatus === "enviada" ||
                    oc.estatus === "recibida_parcial" ||
                    oc.estatus === "recibida") &&
                  !fullyPaid;
                const puedeRecibirRol = roles.includes("director") || roles.includes("residente");
                const puedeRecibir =
                  puedeRecibirRol &&
                  (oc.estatus === "enviada" || oc.estatus === "recibida_parcial") &&
                  !cerrada;
                return (
                  <Card key={oc.id} className="p-4 space-y-3">
                    <div className="flex items-start justify-between gap-2">
                      <div>
                        <div className="flex items-center gap-2 flex-wrap">
                          <p className="font-semibold">{oc.folio}</p>
                          {cerrada ? (
                            <Badge className="bg-emerald-100 text-emerald-800">Cerrada</Badge>
                          ) : (
                            <>
                              <Badge className={meta?.className}>{meta?.label}</Badge>
                              {(oc.estatus === "autorizada" ||
                                oc.estatus === "enviada" ||
                                oc.estatus === "recibida_parcial" ||
                                oc.estatus === "recibida" ||
                                estadoPago !== "pendiente") && (
                                <Badge
                                  className={
                                    estadoPago === "pagado"
                                      ? "bg-emerald-100 text-emerald-800"
                                      : estadoPago === "parcial"
                                        ? "bg-amber-100 text-amber-800"
                                        : "bg-slate-100 text-slate-700"
                                  }
                                >
                                  {estadoPago === "pagado"
                                    ? "Pagada"
                                    : estadoPago === "parcial"
                                      ? "Pago parcial"
                                      : "Sin pago"}
                                </Badge>
                              )}
                            </>
                          )}
                        </div>
                        <p className="text-sm text-muted-foreground">
                          {oc.proveedor?.razon_social}
                        </p>
                      </div>
                      <div className="text-right">
                        <p className="text-lg font-semibold">{mxn(total)}</p>
                        {pagado > 0 && (
                          <p className="text-xs text-muted-foreground">
                            Pagado {mxn(pagado)} ┬À pend. {mxn(saldoPendiente)}
                          </p>
                        )}
                      </div>
                    </div>

                    <div className="border rounded-md overflow-x-auto">
                      <Table>
                        <TableHeader>
                          <TableRow>
                            <TableHead>Insumo</TableHead>
                            <TableHead className="text-right">Pedido</TableHead>
                            <TableHead className="text-right">Recibido</TableHead>
                            <TableHead className="text-right">P. Unit</TableHead>
                            <TableHead className="text-right">Subtotal</TableHead>
                          </TableRow>
                        </TableHeader>
                        <TableBody>
                          {items.map((it: any) => {
                            const pedido = Number(it.cantidad);
                            const recibido = Number(recibidoMap[it.insumo?.id] ?? 0);
                            const cls =
                              recibido <= 0
                                ? "text-muted-foreground"
                                : recibido + 1e-6 < pedido
                                  ? "text-amber-700"
                                  : "text-emerald-700";
                            return (
                              <TableRow key={it.id}>
                                <TableCell>{it.insumo?.nombre}</TableCell>
                                <TableCell className="text-right">
                                  {pedido} {it.insumo?.unidad}
                                </TableCell>
                                <TableCell className={`text-right font-medium ${cls}`}>
                                  {recibido} {it.insumo?.unidad}
                                </TableCell>
                                <TableCell className="text-right">
                                  {mxn(Number(it.precio_unitario))}
                                </TableCell>
                                <TableCell className="text-right">
                                  {mxn(Number(it.subtotal))}
                                </TableCell>
                              </TableRow>
                            );
                          })}
                        </TableBody>
                      </Table>
                    </div>

                    {oc.estatus === "borrador" && (
                      <div className="flex justify-end gap-2">
                        <Button size="sm" variant="outline" onClick={() => setTab("comparativa")}>
                          Editar en Comparativa
                        </Button>
                        <Button
                          size="sm"
                          onClick={() => enviarMut.mutate(oc.id)}
                          disabled={enviarMut.isPending}
                        >
                          <Send className="size-4 mr-1" /> Enviar a supervisor
                        </Button>
                      </div>
                    )}
                    {oc.estatus === "pendiente_autorizacion" && (
                      <p className="text-sm text-muted-foreground">
                        Enviada al supervisor ┬À{" "}
                        {oc.enviada_supervisor_at ? formatDate(oc.enviada_supervisor_at) : "ÔÇö"}
                      </p>
                    )}
                    {oc.estatus === "autorizada" && (
                      <div className="flex items-center justify-between gap-2 flex-wrap">
                        <p className="text-sm flex items-center gap-1 text-emerald-700">
                          <CheckCircle2 className="size-4" /> Autorizada{" "}
                          {oc.autorizada_at ? `┬À ${formatDate(oc.autorizada_at)}` : ""}
                        </p>
                        {puedeCrearOC && (
                          <Button
                            size="sm"
                            onClick={() => enviarProvMut.mutate(oc.id)}
                            disabled={enviarProvMut.isPending}
                          >
                            <Send className="size-4 mr-1" /> Marcar como enviada al proveedor
                          </Button>
                        )}
                      </div>
                    )}
                    {(oc.estatus === "enviada" ||
                      oc.estatus === "recibida_parcial" ||
                      oc.estatus === "recibida") &&
                      !cerrada && (
                        <div className="flex items-center justify-between gap-2 flex-wrap">
                          <p className="text-sm flex items-center gap-1 text-blue-700">
                            <Send className="size-4" /> Enviada al proveedor{" "}
                            {oc.enviada_proveedor_at
                              ? `┬À ${formatDate(oc.enviada_proveedor_at)}`
                              : ""}
                          </p>
                          {puedeRecibir && <OCRecepcionButton ocId={oc.id} onSaved={invalidate} />}
                        </div>
                      )}
                    {cerrada && (
                      <p className="text-sm flex items-center gap-1 text-emerald-700">
                        <CheckCircle2 className="size-4" /> Cerrada
                        {oc.ultima_recepcion_at ? ` ┬À ${formatDate(oc.ultima_recepcion_at)}` : ""}
                      </p>
                    )}
                    {oc.estatus === "rechazada" && (
                      <div className="space-y-2">
                        {oc.notas_supervisor && (
                          <p className="text-sm text-rose-700 bg-rose-50 p-2 rounded-md">
                            <strong>Motivo:</strong> {oc.notas_supervisor}
                          </p>
                        )}
                        <div className="flex justify-end gap-2">
                          <Button size="sm" variant="outline" onClick={() => setTab("comparativa")}>
                            Revisar en Comparativa
                          </Button>
                          <Button
                            size="sm"
                            variant="outline"
                            onClick={() => reabrirMut.mutate(oc.id)}
                            disabled={reabrirMut.isPending}
                          >
                            Reabrir
                          </Button>
                        </div>
                      </div>
                    )}

                    {(oc.estatus === "autorizada" ||
                      oc.estatus === "enviada" ||
                      oc.estatus === "recibida_parcial" ||
                      oc.estatus === "recibida" ||
                      pagado > 0) && (
                      <OCPagosPanel
                        ocId={oc.id}
                        ocFolio={oc.folio}
                        saldoPendiente={saldoPendiente}
                        puedePagar={puedePagar}
                        puedeCancelar={puedeCancelarOC}
                        onChange={invalidate}
                      />
                    )}
                  </Card>
                );
              })}
            </TabsContent>

            <TabsContent value="recepciones" className="mt-4">
              <RecepcionesTab requisicionId={requisicionId} />
            </TabsContent>
          </Tabs>
          )}
        </div>
      </DialogContent>
    </Dialog>
  );
}

function OCPagosPanel({
  ocId,
  ocFolio,
  saldoPendiente,
  puedePagar,
  puedeCancelar,
  onChange,
}: {
  ocId: string;
  ocFolio: string;
  saldoPendiente: number;
  puedePagar: boolean;
  puedeCancelar: boolean;
  onChange: () => void;
}) {
  const fetchPagos = useServerFn(listPagosOC);
  const cancelarFn = useServerFn(cancelarPagoOC);
  const [openDialog, setOpenDialog] = useState(false);
  const qc = useQueryClient();

  const pagosQ = useQuery({
    queryKey: ["pagos-oc", ocId],
    queryFn: () => fetchPagos({ data: { ocId } }),
  });
  const pagos: any[] = pagosQ.data ?? [];

  const cancelMut = useMutation({
    mutationFn: (pagoId: string) => cancelarFn({ data: { pagoId } }),
    onSuccess: () => {
      toast.success("Pago cancelado");
      qc.invalidateQueries({ queryKey: ["pagos-oc", ocId] });
      qc.invalidateQueries({ queryKey: ["cuentas-activas"] });
      onChange();
    },
    onError: (e: any) => toast.error(e?.message ?? "Error"),
  });

  return (
    <div className="border-t pt-3 space-y-2">
      <div className="flex items-center justify-between">
        <p className="text-sm font-semibold flex items-center gap-1">
          <Wallet className="size-4" /> Pagos
        </p>
        {puedePagar && (
          <Button size="sm" onClick={() => setOpenDialog(true)}>
            Registrar pago
          </Button>
        )}
      </div>

      {pagos.length === 0 ? (
        <p className="text-xs text-muted-foreground">Sin pagos registrados.</p>
      ) : (
        <div className="border rounded-md overflow-x-auto">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Fecha</TableHead>
                <TableHead>Cuenta</TableHead>
                <TableHead>M├®todo</TableHead>
                <TableHead>Ref.</TableHead>
                <TableHead className="text-right">Monto</TableHead>
                {puedeCancelar && <TableHead></TableHead>}
              </TableRow>
            </TableHeader>
            <TableBody>
              {pagos.map((p) => (
                <TableRow key={p.id}>
                  <TableCell>{formatDate(p.fecha)}</TableCell>
                  <TableCell>{p.cuenta?.nombre}</TableCell>
                  <TableCell className="capitalize">{p.metodo}</TableCell>
                  <TableCell className="text-xs">{p.referencia ?? "ÔÇö"}</TableCell>
                  <TableCell className="text-right font-medium">{mxn(Number(p.monto))}</TableCell>
                  {puedeCancelar && (
                    <TableCell>
                      <Button
                        size="icon"
                        variant="ghost"
                        aria-label="Cancelar pago"
                        title="Cancelar pago"
                        onClick={() => {
                          if (
                            confirm(
                              "┬┐Cancelar este pago? Se revertir├í el saldo de la cuenta y de la OC.",
                            )
                          ) {
                            cancelMut.mutate(p.id);
                          }
                        }}
                      >
                        <Trash2 className="size-4 text-rose-600" />
                      </Button>
                    </TableCell>
                  )}
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </div>
      )}

      <RegistrarPagoOCDialog
        ocId={ocId}
        ocFolio={ocFolio}
        saldoPendiente={saldoPendiente}
        open={openDialog}
        onOpenChange={setOpenDialog}
        onSaved={() => {
          qc.invalidateQueries({ queryKey: ["pagos-oc", ocId] });
          qc.invalidateQueries({ queryKey: ["cuentas-activas"] });
          onChange();
        }}
      />
    </div>
  );
}

function OCRecepcionButton({ ocId, onSaved }: { ocId: string; onSaved: () => void }) {
  const [open, setOpen] = useState(false);
  const qc = useQueryClient();
  return (
    <>
      <Button size="sm" variant="outline" onClick={() => setOpen(true)}>
        Registrar recepci├│n
      </Button>
      {open && (
        <RecepcionDialog
          ocId={ocId}
          open={open}
          onOpenChange={(o) => {
            setOpen(o);
            if (!o) {
              qc.invalidateQueries({ queryKey: ["almacen"] });
              onSaved();
            }
          }}
        />
      )}
    </>
  );
}

"use client";

import { useEffect, useMemo, useState } from "react";
import { useServerFn } from "@/lib/server-fn/client";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { format, parseISO, startOfDay } from "date-fns";
import { CalendarIcon, Plus, Trash2, Search, Check, Save, PackagePlus } from "lucide-react";
import { toast } from "sonner";
import { Sheet, SheetContent, SheetHeader, SheetTitle } from "@/components/ui/sheet";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command";
import { Calendar } from "@/components/ui/calendar";
import { cn } from "@/lib/utils";
import { listInsumos, listCategorias, listUnidades } from "@/lib/api-client/insumos.functions";
import { SolicitarInsumoRapidoDialog } from "@/components/insumos/SolicitarInsumoRapidoDialog";

import { useEffectiveRoles, isDirector as checkDirector } from "@/stores/auth";
import {
  guardarBorradorRequisicion,
  enviarBorradorRequisicion,
  getBorradorRequisicion,
} from "@/lib/api-client/requisiciones.functions";

interface Props {
  obraId: string;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  borradorId?: string | null;
}

interface Bloque {
  insumo_id: string;
  cantidad: string;
  fecha_requerida: Date | undefined;
  nota: string;
}

function emptyBloque(): Bloque {
  return { insumo_id: "", cantidad: "", fecha_requerida: undefined, nota: "" };
}

export function NuevaRequisicionSheet({ obraId, open, onOpenChange, borradorId }: Props) {
  const qc = useQueryClient();
  const fetchInsumos = useServerFn(listInsumos);
  const fetchCategorias = useServerFn(listCategorias);
  const guardarBorrador = useServerFn(guardarBorradorRequisicion);
  const enviarBorrador = useServerFn(enviarBorradorRequisicion);
  const fetchBorrador = useServerFn(getBorradorRequisicion);

  const insumosQ = useQuery({
    queryKey: ["insumos", "autorizado"],
    queryFn: () => fetchInsumos({ data: { estatus: "autorizado" } }),
    enabled: open,
  });
  const insumos = (insumosQ.data ?? []) as Array<{
    id: string;
    nombre: string;
    unidad: string;
    categoria?: { id: string; nombre: string } | null;
  }>;

  const categoriasQ = useQuery({
    queryKey: ["insumo-categorias"],
    queryFn: () => fetchCategorias(),
    enabled: open,
  });
  const categorias = (categoriasQ.data ?? []) as Array<{ id: string; nombre: string }>;

  const fetchUnidades = useServerFn(listUnidades);
  const unidadesQ = useQuery({
    queryKey: ["insumo-unidades"],
    queryFn: () => fetchUnidades(),
    enabled: open,
  });
  const unidades = (unidadesQ.data ?? []) as Array<{ id: string; codigo: string; nombre?: string }>;

  const roles = useEffectiveRoles();
  const isDirector = checkDirector(roles);

  const [bloques, setBloques] = useState<Bloque[]>([emptyBloque()]);
  const [notas, setNotas] = useState("");
  const [openFechaIdx, setOpenFechaIdx] = useState<number | null>(null);
  const [currentBorradorId, setCurrentBorradorId] = useState<string | null>(borradorId ?? null);
  const [solicitarForIdx, setSolicitarForIdx] = useState<number | null>(null);

  // Reset y carga del borrador cuando abre
  useEffect(() => {
    if (!open) return;
    setCurrentBorradorId(borradorId ?? null);
    if (!borradorId) {
      setBloques([emptyBloque()]);
      setNotas("");
      return;
    }
    fetchBorrador({ data: { id: borradorId } })
      .then((r: any) => {
        setNotas(r.notas ?? "");
        const items = (r.items ?? []) as Array<any>;
        if (items.length === 0) {
          setBloques([emptyBloque()]);
        } else {
          setBloques(
            items.map((it) => ({
              insumo_id: it.insumo_id ?? "",
              cantidad: it.cantidad != null ? String(it.cantidad) : "",
              fecha_requerida: it.fecha_requerida ? parseISO(it.fecha_requerida) : undefined,
              nota: it.nota ?? "",
            })),
          );
        }
      })
      .catch((e: any) => toast.error(e?.message ?? "Error al cargar borrador"));
  }, [open, borradorId, fetchBorrador]);

  const resetForm = () => {
    setBloques([emptyBloque()]);
    setNotas("");
    setCurrentBorradorId(null);
  };

  const invalidateLists = () => {
    qc.invalidateQueries({ queryKey: ["requisiciones", obraId] });
  };

  const mut = useMutation({
    mutationFn: async () => {
      const items = bloques.map((b) => ({
        insumo_id: b.insumo_id,
        cantidad: Number(b.cantidad),
        fecha_requerida: b.fecha_requerida ? format(b.fecha_requerida, "yyyy-MM-dd") : "",
        nota: b.nota?.trim() || null,
      }));
      for (const it of items) {
        if (!it.insumo_id) throw new Error("Selecciona un insumo en cada bloque");
        if (!(it.cantidad > 0)) throw new Error("Cantidad debe ser mayor a 0");
        if (!it.fecha_requerida) throw new Error("Fecha requerida obligatoria");
      }
      // Si no hay borrador, primero creamos uno y luego lo enviamos
      let bid = currentBorradorId;
      if (!bid) {
        const created = await guardarBorrador({
          data: {
            obraId,
            notas: notas.trim() || null,
            insumos: items.map((it) => ({
              insumo_id: it.insumo_id,
              cantidad: it.cantidad,
              fecha_requerida: it.fecha_requerida,
              nota: it.nota,
            })),
          },
        });
        bid = (created as any).id as string;
      }
      return enviarBorrador({
        data: { borradorId: bid, notas: notas.trim() || null, insumos: items },
      });
    },
    onSuccess: (res: any) => {
      toast.success(`Requisici├│n ${res.folio} enviada`);
      invalidateLists();
      resetForm();
      onOpenChange(false);
    },
    onError: (e: any) => toast.error(e?.message ?? "Error al enviar"),
  });

  const guardar = useMutation({
    mutationFn: async () => {
      const items = bloques.map((b) => ({
        insumo_id: b.insumo_id || null,
        cantidad: b.cantidad !== "" ? Number(b.cantidad) : null,
        fecha_requerida: b.fecha_requerida ? format(b.fecha_requerida, "yyyy-MM-dd") : null,
        nota: b.nota?.trim() || null,
      }));
      const hasAny = items.some(
        (it) => it.insumo_id || (it.cantidad ?? 0) > 0 || it.fecha_requerida || it.nota,
      );
      if (!hasAny && !notas.trim()) {
        throw new Error("Agrega al menos un dato antes de guardar el borrador");
      }
      const res = await guardarBorrador({
        data: {
          borradorId: currentBorradorId ?? undefined,
          obraId,
          notas: notas.trim() || null,
          insumos: items,
        },
      });
      return res as { id: string };
    },
    onSuccess: (res) => {
      setCurrentBorradorId(res.id);
      toast.success("Borrador guardado");
      invalidateLists();
      onOpenChange(false);
    },
    onError: (e: any) => toast.error(e?.message ?? "Error al guardar borrador"),
  });

  const updateBloque = (i: number, patch: Partial<Bloque>) =>
    setBloques((arr) => arr.map((b, idx) => (idx === i ? { ...b, ...patch } : b)));
  const removeBloque = (i: number) =>
    setBloques((arr) => (arr.length === 1 ? arr : arr.filter((_, idx) => idx !== i)));

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent side="right" className="w-full sm:max-w-lg overflow-y-auto">
        <SheetHeader>
          <SheetTitle>
            {currentBorradorId ? "Editar borrador de requisici├│n" : "Nueva requisici├│n"}
          </SheetTitle>
        </SheetHeader>

        <div className="space-y-3 mt-4">
          {bloques.map((b, i) => {
            const insumoSel = insumos.find((x) => x.id === b.insumo_id);
            return (
              <div key={i} className="border rounded-lg p-2.5 space-y-2 relative text-xs">
                <div className="flex items-center justify-between">
                  <span className="text-[11px] font-medium text-muted-foreground">
                    Insumo {i + 1}
                  </span>
                  {bloques.length > 1 && (
                    <Button
                      type="button"
                      variant="ghost"
                      className="h-8 w-8 p-0"
                      onClick={() => removeBloque(i)}
                    >
                      <Trash2 className="size-3.5 text-destructive" />
                    </Button>
                  )}
                </div>

                <div className="space-y-0.5">
                  <Label className="text-[11px]">Insumo</Label>
                  <InsumoPicker
                    insumos={insumos}
                    categorias={categorias}
                    value={b.insumo_id}
                    onChange={(v) => updateBloque(i, { insumo_id: v })}
                    disabledIds={bloques
                      .filter((_, idx) => idx !== i)
                      .map((x) => x.insumo_id)
                      .filter(Boolean)}
                    onRequestNew={() => setSolicitarForIdx(i)}
                  />
                </div>

                <div className="grid grid-cols-[1fr_1fr_1.4fr] gap-2">
                  <div className="space-y-0.5">
                    <Label className="text-[11px]">Cantidad</Label>
                    <Input
                      type="number"
                      min="0"
                      step="0.01"
                      className="h-8 text-xs [appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none"
                      value={b.cantidad}
                      onChange={(e) => updateBloque(i, { cantidad: e.target.value })}
                    />
                  </div>
                  <div className="space-y-0.5">
                    <Label className="text-[11px]">Unidad</Label>
                    <Input
                      className="h-8 text-xs"
                      value={insumoSel?.unidad ?? ""}
                      readOnly
                      disabled
                    />
                  </div>
                  <div className="space-y-0.5">
                    <Label className="text-[11px]">Fecha requerida</Label>
                    <Popover
                      open={openFechaIdx === i}
                      onOpenChange={(v) => setOpenFechaIdx(v ? i : null)}
                    >
                      <PopoverTrigger asChild>
                        <Button
                          variant="outline"
                          className={cn(
                            "w-full h-8 px-2 justify-start text-left font-normal text-xs",
                            !b.fecha_requerida && "text-muted-foreground",
                          )}
                        >
                          <CalendarIcon className="size-3.5 mr-1.5" />
                          {b.fecha_requerida
                            ? format(b.fecha_requerida, "dd/MM/yyyy")
                            : "Selecciona"}
                        </Button>
                      </PopoverTrigger>
                      <PopoverContent className="w-auto p-0" align="start">
                        <Calendar
                          mode="single"
                          selected={b.fecha_requerida}
                          onSelect={(d) => {
                            updateBloque(i, { fecha_requerida: d ?? undefined });
                            setOpenFechaIdx(null);
                          }}
                          initialFocus
                          startMonth={startOfDay(new Date())}
                          disabled={{ before: startOfDay(new Date()) }}
                          className={cn("p-3 pointer-events-auto")}
                        />
                      </PopoverContent>
                    </Popover>
                  </div>
                </div>

                <div className="space-y-0.5">
                  <Label className="text-[11px]">Nota (opcional)</Label>
                  <Textarea
                    rows={1}
                    className="min-h-[32px] text-xs resize-none"
                    value={b.nota}
                    onChange={(e) => updateBloque(i, { nota: e.target.value })}
                  />
                </div>
              </div>
            );
          })}

          <Button
            type="button"
            variant="outline"
            className="w-full"
            onClick={() => setBloques((arr) => [...arr, emptyBloque()])}
          >
            <Plus className="size-4 mr-1" /> Agregar otro insumo
          </Button>

          <div className="space-y-1">
            <Label>Notas generales</Label>
            <Textarea
              rows={3}
              value={notas}
              onChange={(e) => setNotas(e.target.value)}
              placeholder="Observaciones para administraci├│nÔÇª"
            />
          </div>

          <div className="flex flex-col sm:flex-row gap-2 pt-1">
            <Button
              variant="outline"
              className="w-full sm:w-auto sm:flex-1"
              disabled={guardar.isPending || mut.isPending}
              onClick={() => guardar.mutate()}
            >
              <Save className="size-4 mr-1" />
              {guardar.isPending ? "GuardandoÔÇª" : "Guardar borrador"}
            </Button>
            <Button
              className="w-full sm:w-auto sm:flex-1"
              disabled={mut.isPending || guardar.isPending}
              onClick={() => mut.mutate()}
            >
              {mut.isPending ? "EnviandoÔÇª" : "Enviar requisici├│n"}
            </Button>
          </div>
        </div>
      </SheetContent>
      <SolicitarInsumoRapidoDialog
        open={solicitarForIdx !== null}
        onOpenChange={(v) => {
          if (!v) setSolicitarForIdx(null);
        }}
        categorias={categorias}
        unidades={unidades}
        isDirector={isDirector}
        onCreated={(newId) => {
          qc.invalidateQueries({ queryKey: ["insumos"] });
          if (newId && solicitarForIdx !== null) {
            updateBloque(solicitarForIdx, { insumo_id: newId });
          }
          setSolicitarForIdx(null);
        }}
      />
    </Sheet>
  );
}

type InsumoItem = {
  id: string;
  nombre: string;
  unidad: string;
  categoria?: { id: string; nombre: string } | null;
};

function InsumoPicker({
  insumos,
  categorias,
  value,
  onChange,
  disabledIds,
  onRequestNew,
}: {
  insumos: InsumoItem[];
  categorias: Array<{ id: string; nombre: string }>;
  value: string;
  onChange: (id: string) => void;
  disabledIds?: string[];
  onRequestNew?: () => void;
}) {
  const [open, setOpen] = useState(false);
  const [categoriaId, setCategoriaId] = useState<string>("all");

  const selected = insumos.find((x) => x.id === value);

  const filtered = useMemo(() => {
    const base =
      categoriaId === "all"
        ? insumos
        : categoriaId === "none"
          ? insumos.filter((i) => !i.categoria)
          : insumos.filter((i) => i.categoria?.id === categoriaId);
    return [...base].sort((a, b) =>
      a.nombre.localeCompare(b.nombre, "es", { sensitivity: "base", numeric: true }),
    );
  }, [insumos, categoriaId]);

  return (
    <div className="flex items-center gap-1">
      <Popover open={open} onOpenChange={setOpen}>
        <PopoverTrigger asChild>
          <Button
            type="button"
            variant="outline"
            className={cn(
              "h-8 flex-1 justify-start text-left font-normal text-xs px-2 truncate",
              !selected && "text-muted-foreground",
            )}
          >
            <span className="truncate">{selected ? selected.nombre : "SeleccionaÔÇª"}</span>
          </Button>
        </PopoverTrigger>
        <PopoverContent
          className="p-0 w-[--radix-popover-trigger-width] min-w-[280px]"
          align="start"
          onWheel={(e) => e.stopPropagation()}
          onTouchMove={(e) => e.stopPropagation()}
        >
          <div className="p-2 border-b">
            <Select value={categoriaId} onValueChange={setCategoriaId}>
              <SelectTrigger className="h-8 text-xs">
                <SelectValue placeholder="Categor├¡a" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">Todas las categor├¡as</SelectItem>
                <SelectItem value="none">Sin categor├¡a</SelectItem>
                {categorias.map((c) => (
                  <SelectItem key={c.id} value={c.id}>
                    {c.nombre}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
          <Command
            filter={(value, search) => {
              const norm = (s: string) =>
                s
                  .toLowerCase()
                  .normalize("NFD")
                  .replace(/\p{Diacritic}/gu, "");
              return norm(value).includes(norm(search)) ? 1 : 0;
            }}
          >
            <CommandInput autoFocus placeholder="Buscar insumoÔÇª" className="h-9 text-xs" />
            <CommandList className="max-h-64">
              <CommandEmpty>
                <div className="py-3 text-center space-y-2">
                  <p className="text-xs text-muted-foreground">Sin resultados.</p>
                  {onRequestNew && (
                    <Button
                      type="button"
                      variant="outline"
                      size="sm"
                      className="h-7 text-xs"
                      onClick={() => {
                        setOpen(false);
                        onRequestNew();
                      }}
                    >
                      <PackagePlus className="size-3.5 mr-1" /> Solicitar nuevo insumo
                    </Button>
                  )}
                </div>
              </CommandEmpty>
              <CommandGroup>
                {filtered.map((ins) => {
                  const isDisabled = disabledIds?.includes(ins.id) ?? false;
                  return (
                    <CommandItem
                      key={ins.id}
                      value={`${ins.nombre} ${ins.unidad} ${ins.categoria?.nombre ?? ""}`}
                      disabled={isDisabled}
                      onSelect={() => {
                        if (isDisabled) return;
                        onChange(ins.id);
                        setOpen(false);
                      }}
                      className={cn("text-xs", isDisabled && "opacity-50 cursor-not-allowed")}
                    >
                      <Check
                        className={cn(
                          "mr-2 size-3.5",
                          value === ins.id ? "opacity-100" : "opacity-0",
                        )}
                      />
                      <div className="flex-1 min-w-0">
                        <div className="truncate">
                          {ins.nombre} <span className="text-muted-foreground">({ins.unidad})</span>
                        </div>
                        {ins.categoria?.nombre && (
                          <div className="text-xs text-muted-foreground truncate">
                            {ins.categoria.nombre}
                          </div>
                        )}
                      </div>
                      {isDisabled && (
                        <span className="ml-2 text-xs text-muted-foreground shrink-0">
                          Ya agregado
                        </span>
                      )}
                    </CommandItem>
                  );
                })}
              </CommandGroup>
              {onRequestNew && filtered.length > 0 && (
                <div className="border-t p-2">
                  <Button
                    type="button"
                    variant="ghost"
                    size="sm"
                    className="h-7 w-full justify-start text-xs"
                    onClick={() => {
                      setOpen(false);
                      onRequestNew();
                    }}
                  >
                    <PackagePlus className="size-3.5 mr-1" /> Solicitar nuevo insumo
                  </Button>
                </div>
              )}
            </CommandList>
          </Command>
        </PopoverContent>
      </Popover>
      <Button
        type="button"
        variant="outline"
        className="h-8 w-8 p-0 shrink-0"
        onClick={() => setOpen(true)}
        aria-label="Buscar insumo"
      >
        <Search className="size-3.5" />
      </Button>
    </div>
  );
}

"use client";

import { useMemo, useState } from "react";
import { useServerFn } from "@/lib/server-fn/client";
import { useQuery, useQueryClient, useMutation } from "@tanstack/react-query";
import {
  Plus,
  FileText,
  ShieldCheck,
  ChevronRight,
  ChevronDown,
  Pencil,
  Trash2,
} from "lucide-react";
import { toast } from "sonner";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  listRequisiciones,
  eliminarBorradorRequisicion,
} from "@/lib/api-client/requisiciones.functions";
import { ESTATUS_META, type RequisicionEstatus } from "./constants";
import { NuevaRequisicionSheet } from "./NuevaRequisicionSheet";
import { CotizacionSheet, type CotizacionTab } from "./CotizacionSheet";
import { useEffectiveRoles } from "@/stores/auth";
import { usePermisos } from "@/hooks/usePermisos";
import { formatDate } from "@/lib/format";

interface Props {
  obraId: string;
}

export function RequisicionesModule({ obraId }: Props) {
  const roles = useEffectiveRoles();
  void roles;
  const { can } = usePermisos();
  const puedeCrear = can("requisiciones.crear");
  const puedeRevisar = can("requisiciones.aprobar") || can("requisiciones.rechazar");
  const puedeCotizar = can("cotizaciones.gestionar");
  const puedeCrearOC = can("oc.crear");
  const puedeGestionar = puedeCotizar || puedeCrearOC;
  const puedeVerOC = can("requisiciones.ver_oc") || can("oc.autorizar") || can("oc.cancelar");
  const usarVistaTabla = puedeGestionar || puedeVerOC;

  const [tab, setTab] = useState<"activas" | "historial">("activas");
  const [openNueva, setOpenNueva] = useState(false);
  const [borradorEnEdicion, setBorradorEnEdicion] = useState<string | null>(null);
  const [cotizacion, setCotizacion] = useState<{
    id: string;
    tab: CotizacionTab;
    readOnly?: boolean;
  } | null>(null);
  const abrirVisor = (id: string) => setCotizacion({ id, tab: "requisicion", readOnly: true });
  const [expandidos, setExpandidos] = useState<Set<string>>(new Set());
  const qc = useQueryClient();
  const eliminarBorradorFn = useServerFn(eliminarBorradorRequisicion);
  const eliminarBorrador = useMutation({
    mutationFn: (id: string) => eliminarBorradorFn({ data: { id } }),
    onSuccess: () => {
      toast.success("Borrador eliminado");
      qc.invalidateQueries({ queryKey: ["requisiciones", obraId] });
    },
    onError: (e: any) => toast.error(e?.message ?? "Error al eliminar"),
  });
  const abrirBorrador = (id: string) => {
    setBorradorEnEdicion(id);
    setOpenNueva(true);
  };
  const toggleExpand = (id: string) => {
    setExpandidos((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  };
  const formatDateShort = (d: string | Date | null | undefined) => {
    if (!d) return "";
    const date = typeof d === "string" ? new Date(d) : d;
    if (isNaN(date.getTime())) return "";
    const dd = String(date.getDate()).padStart(2, "0");
    const mm = String(date.getMonth() + 1).padStart(2, "0");
    const yy = String(date.getFullYear()).slice(-2);
    return `${dd}/${mm}/${yy}`;
  };

  const fetchList = useServerFn(listRequisiciones);
