                  );
                })
              )}
            </TableBody>
          </Table>
        </TooltipProvider>
      </Card>

      {(creating || editing) && (
        <TerceroFormDialog
          open

          initial={(editing as any) ?? null}
          onClose={() => {
            setCreating(false);
            setEditing(null);
          }}
