export const getCompanyLogoSignedUrl = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .inputValidator((d: unknown) => z.object({ path: z.string().min(1) }).parse(d))
  .handler(async ({ data, context }) => {
    const { supabase } = context;
    const { data: signed, error } = await supabase.storage
      .from("company-logos")
      .createSignedUrl(data.path, 3600);
    if (error) throw new Error(error.message);
    return { url: signed.signedUrl };
  });

export const updateCompanyCapitalSocial = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .inputValidator((d: unknown) =>
    z.object({ capital_social: z.number().min(0).max(9_999_999_999) }).parse(d),
  )
  .handler(async ({ data, context }) => {
    const { supabase, userId } = context;
    const companyId = await getMyCompanyId(supabase, userId);
    // Solo director
    const { data: roles } = await supabase
      .from("user_roles")
      .select("role")
      .eq("user_id", userId)
      .eq("company_id", companyId);
    if (!(roles ?? []).some((r: any) => r.role === "director")) {
      throw new Error("Solo el director puede actualizar el capital social");
    }
    const { error } = await supabase
      .from("companies")
      .update({ capital_social: data.capital_social })
      .eq("id", companyId);
    if (error) throw new Error(error.message);
    return { ok: true as const };
  });

export const listCompanyDocumentos = createServerFn({ method: "GET" })
  .middleware([requireSupabaseAuth])
  .handler(async ({ context }) => {
    const { supabase, userId } = context;
    const companyId = await getMyCompanyId(supabase, userId);

    const { data: docs, error } = await (supabase as any)
      .from("company_documentos")
      .select("id, company_id, tipo, url, nombre_archivo, fecha_vencimiento, created_at, updated_at")
      .eq("company_id", companyId)
      .order("created_at", { ascending: false });

    if (error) throw new Error(error.message);

    // ponytail: revisi├│n pasiva de vigencia al consultar documentos
    const now = new Date();
    const hoyStr = now.toISOString().split("T")[0];
    const en30Dias = new Date(now.getTime() + 30 * 24 * 60 * 60 * 1000).toISOString().split("T")[0];

    const porVencerOExpirados = (docs ?? []).filter(
      (d: any) => d.fecha_vencimiento && d.fecha_vencimiento <= en30Dias,
    );

    if (porVencerOExpirados.length > 0) {
      try {
        const { supabaseAdmin } = await import("@/integrations/supabase/client.server");
        for (const doc of porVencerOExpirados) {
          const yaExpiro = doc.fecha_vencimiento < hoyStr;
          const titulo = yaExpiro
            ? `Documento expirado: ${doc.tipo}`
            : `Documento por vencer: ${doc.tipo}`;
          const mensaje = yaExpiro
            ? `El documento "${doc.tipo}" (${doc.nombre_archivo}) expir├│ el ${doc.fecha_vencimiento}.`
            : `El documento "${doc.tipo}" (${doc.nombre_archivo}) vence el ${doc.fecha_vencimiento}.`;

          const { data: exists } = await supabaseAdmin
            .from("notificaciones")
            .select("id")
            .eq("user_id", userId)
            .eq("tipo", "doc_empresa_vencimiento")
            .eq("titulo", titulo)
            .gte("created_at", new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000).toISOString())
            .maybeSingle();

          if (!exists) {
            await supabaseAdmin.from("notificaciones").insert({
              user_id: userId,
              company_id: companyId,
              tipo: "doc_empresa_vencimiento",
              titulo,
              mensaje,
              link: "/app/configuracion?tab=documentacion",
            });
          }
        }
      } catch (e) {
        console.error("Error al procesar alertas de vencimiento de documentos:", e);
      }
    }

    return (docs ?? []) as Array<{
      id: string;
      company_id: string;
      tipo: string;
      url: string;
      nombre_archivo: string;
      fecha_vencimiento: string | null;
      created_at: string;
      updated_at: string;
    }>;
  });

export const saveCompanyDocumento = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .inputValidator((d: unknown) =>
    z
      .object({
        tipo: z.string().trim().min(1).max(100),
        url: z.string().min(1),
        nombre_archivo: z.string().min(1),
        fecha_vencimiento: z.string().nullable().optional(),
      })
      .parse(d),
  )
  .handler(async ({ data, context }) => {
    const { supabase, userId } = context;
    const companyId = await getMyCompanyId(supabase, userId);

    const { error } = await (supabase as any).from("company_documentos").upsert(
      {
        company_id: companyId,
        tipo: data.tipo,
        url: data.url,
        nombre_archivo: data.nombre_archivo,
        fecha_vencimiento: data.fecha_vencimiento || null,
        updated_at: new Date().toISOString(),
      },
      { onConflict: "company_id,tipo" },
    );

    if (error) throw new Error(error.message);
    return { ok: true as const };
  });

export const deleteCompanyDocumento = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .inputValidator((d: unknown) =>
    z
      .object({
        id: z.string().uuid(),
      })
      .parse(d),
  )
  .handler(async ({ data, context }) => {
    const { supabase, userId } = context;
    const companyId = await getMyCompanyId(supabase, userId);

    const { error } = await (supabase as any)
      .from("company_documentos")
      .delete()
      .eq("id", data.id)
      .eq("company_id", companyId);

    if (error) throw new Error(error.message);
    return { ok: true as const };
  });

"use client";

/**
 * Next.js equivalents for the small subset of TanStack Router used by the app.
 *
 * Keeping this compatibility layer means UI components only needed their import
 * path changed (`@tanstack/react-router` ÔåÆ `@/lib/navigation`) and their markup
 * stayed exactly the same (`<Link to=... params=...>`).
 */
import NextLink from "next/link";
import {
  useParams as useNextParams,
  usePathname,
  useRouter,
  useSearchParams,
} from "next/navigation";
import { useCallback, useEffect, useMemo, useState } from "react";
import type { AnchorHTMLAttributes, ReactNode } from "react";

type ParamMap = Record<string, unknown>;
type SearchValue = string | number | boolean | null | undefined;
type SearchObject = Record<string, SearchValue>;

export type NavigateOptions = {
  to?: string;
  params?: ParamMap;
  search?: SearchObject | ((prev: SearchObject) => SearchObject);
  replace?: boolean;
};

const SPLAT_KEYS = ["slug", "_splat"];

function flattenParams(params: ParamMap): ParamMap {
  const flat: ParamMap = { ...params };
  for (const key of SPLAT_KEYS) {
    const value = params[key];
    if (Array.isArray(value)) flat._splat = value.join("/");
  }
  return flat;
}

function interpolate(path: string, params?: ParamMap): string {
  if (!params) return path;
  const flat = flattenParams(params);
  return path.replace(/\$(\w+)?/g, (_match, name: string | undefined) => {
    if (!name) {
      const splat = flat._splat ?? flat.slug;
      return Array.isArray(splat) ? splat.join("/") : String(splat ?? "");
    }
    const value = flat[name];
    return Array.isArray(value) ? value.join("/") : String(value ?? "");
  });
}

function toQueryString(
  search?: SearchObject | ((prev: SearchObject) => SearchObject),
  prev?: SearchObject,
) {
  if (!search) return "";
  const resolved = typeof search === "function" ? search(prev ?? {}) : search;
  const qs = new URLSearchParams();
  for (const [key, value] of Object.entries(resolved ?? {})) {
    if (value === undefined || value === null || value === "") continue;
    if (Array.isArray(value)) {
      for (const item of value) qs.append(key, String(item));
    } else {
      qs.set(key, String(value));
    }
  }
  return qs.toString();
}

export function buildHref(
  to: string,
  params?: ParamMap,
  search?: SearchObject | ((prev: SearchObject) => SearchObject),
  currentSearch?: SearchObject,
): string {
  const path = interpolate(to, params);
  const qs = toQueryString(search, currentSearch);
  return qs ? `${path}?${qs}` : path;
}

/**
 * Derives params that Next.js layouts cannot see (child dynamic segments).
 * AppShell lives at `/app` but needs `obraId` to render the obra navigation.
 */
function deriveParams(pathname: string): Record<string, string> {
  const derived: Record<string, string> = {};
  const obra = /\/app\/obras\/([^/]+)/.exec(pathname);
  if (obra && obra[1] !== "nueva") derived.obraId = obra[1];
  const cliente = /\/app\/catalogos\/clientes\/([^/]+)/.exec(pathname);
  if (cliente) derived.clienteId = cliente[1];
  return derived;
}

type LinkProps = Omit<AnchorHTMLAttributes<HTMLAnchorElement>, "href"> & {
  to: string;
  params?: ParamMap;
  search?: SearchObject | ((prev: SearchObject) => SearchObject);
  hash?: string;
  replace?: boolean;
  children?: ReactNode;
};

/**
 * Un enlace sin `search` no necesita leer los query params actuales. Por eso el
 * componente se divide: si llamara `useSearchParams()` siempre, cualquier
 * p├ígina con un `<Link>` se pospondr├¡a a cliente y su HTML saldr├¡a vac├¡o (la
 * landing incluida), que es el peor intercambio posible para la primera
 * pintura.
 */
export function Link({ to, params, search, hash, replace, children, ...rest }: LinkProps) {
  if (search) {
    return (
      <LinkConBusqueda
        to={to}
        params={params}
        search={search}
        hash={hash}
        replace={replace}
        {...rest}
      >
        {children}
      </LinkConBusqueda>
    );
  }

  const href = buildHref(to, params);
  return (
    <NextLink href={hash ? `${href}#${hash}` : href} replace={replace} {...rest}>
      {children}
    </NextLink>
  );
}

function LinkConBusqueda({
  to,
  params,
  search,
  hash,
  replace,
  children,
  ...rest
}: LinkProps & { search: NonNullable<LinkProps["search"]> }) {
  const searchParams = useSearchParams();
  const currentSearch = useMemo(
    () => Object.fromEntries(searchParams.entries()) as SearchObject,
    [searchParams],
  );
  const baseHref = buildHref(to, params, search, currentSearch);
  const href = hash ? `${baseHref}#${hash}` : baseHref;
  return (
    <NextLink href={href} replace={replace} {...rest}>
      {children}
    </NextLink>
  );
}

export function useNavigate() {
  const router = useRouter();
  const pathname = usePathname();
  const params = useNextParams() as ParamMap;

  return useCallback(
    (options: NavigateOptions | string) => {
      if (typeof options === "string") {
        router.push(options);
        return;
      }
      // Los query params se leen en el momento del clic, no en el render: con
      // `useSearchParams()` aqu├¡, /login y /onboarding se pospon├¡an a cliente y
      // llegaban sin HTML.
      const currentSearch =
        typeof window === "undefined"
          ? ({} as SearchObject)
          : (Object.fromEntries(
              new URLSearchParams(window.location.search).entries(),
            ) as SearchObject);
      const base = !options.to || options.to === "." ? pathname : options.to;
      const href = buildHref(
        base,
        { ...flattenParams(params), ...deriveParams(pathname), ...(options.params ?? {}) },
        options.search,
        currentSearch,
      );
      if (options.replace) router.replace(href);
      else router.push(href);
    },
    [router, pathname, params],
  );
}

export function useRouterState<T>(options: {
  select: (state: { location: { pathname: string; search: SearchObject; href: string } }) => T;
}): T {
  const pathname = usePathname();
  const searchParams = useSearchParams();
  const search = useMemo(
    () => Object.fromEntries(searchParams.entries()) as SearchObject,
    [searchParams],
  );
  const href = searchParams.size > 0 ? `${pathname}?${searchParams.toString()}` : pathname;
  return options.select({ location: { pathname, search, href } });
}

export function useParams<T = Record<string, string>>(_options?: unknown): T {
  const params = useNextParams();
  const pathname = usePathname();
  const flattened = useMemo(() => {
    const flat: Record<string, string | string[]> = {
      ...(params as Record<string, string | string[]>),
    };
    if (Array.isArray(flat.slug)) flat._splat = flat.slug.join("/");
    for (const [key, value] of Object.entries(deriveParams(pathname))) {
      if (flat[key] === undefined) flat[key] = value;
    }
    return flat;
  }, [params, pathname]);
  return flattened as T;
}

export function useSearch<T = Record<string, string>>(_options?: unknown): T {
  const searchParams = useSearchParams();
  return useMemo(
    () => Object.fromEntries(searchParams.entries()) as SearchObject,
    [searchParams],
  ) as T;
}

export function ClientOnly({
  children,
  fallback = null,
}: {
  children: ReactNode;
  fallback?: ReactNode;
}) {
  const [mounted, setMounted] = useState(false);
  useEffect(() => setMounted(true), []);
  return <>{mounted ? children : fallback}</>;
}
